local config = {
  ui_story_5026_50260101_1_dialog_content = "PlayerName, PlayerName?",
  ui_story_5026_50260101_2_dialog_content = "Hei! Kau bangun kesiangan!",
  ui_story_5026_50260101_3_dialog_content = "(Siapa itu yang bicara?)",
  ui_story_5026_50260101_4_dialog_content = "Kalau kau tidak segera bangun, waktu penukaran hadiahnya keburu selesai, lho!",
  ui_story_5026_50260101_5_dialog_content = "Waktu penukaran hadiah?",
  ui_story_5026_50260101_6_dialog_content = "Kau membeli Shadow Prize Ticket di Umbraton dan memenangkan hadiah utama senilai sepuluh juta Nightium!",
  ui_story_5026_50260101_7_dialog_content = "<size=50>S-SEPULUH JUTA?!</size>",
  ui_story_5026_50260101_8_dialog_content = "Kau pasti bercanda... Apa aku bermimpi?!",
  ui_story_5026_50260101_9_dialog_content = "Ayo kita pikirkan baik-baik mau diapakan uangnya!",
  ui_story_5026_50260101_10_dialog_content = "Hm, coba kupikirkan dulu...",
  ui_story_5026_50260101_11_dialog_content = "Pertama, aku mau menggunakan tiga juta untuk investasi pembangunan Cloud Gardens!",
  ui_story_5026_50260101_12_dialog_content = "Belum lama ini, Obelisk of Return muncul dan mengubah seluruh lanskap Eraveil.",
  ui_story_5026_50260101_13_dialog_content = "Aku juga sibuk mengurus hal lain, dan waktu pun berlalu... Cloud Gardens juga mulai membaik...",
  ui_story_5026_50260101_14_dialog_content = "Hmm, masuk akal, sih. Biar kucatat dulu.",
  ui_story_5026_50260101_15_dialog_content = "Aku juga butuh tiga juta lagi untuk mencari tim manajemen yang bisa diandalkan!",
  ui_story_5026_50260101_16_dialog_content = "Kau benar-benar sudah membantuku untuk mengurus Colossus, Vice.",
  ui_story_5026_50260101_17_dialog_content = "Tapi, Cloud Gardens itu sangat besar. Kita butuh lebih banyak tenaga kerja untuk mengurusnya.",
  ui_story_5026_50260101_18_dialog_content = "Aku mau merekrut orang yang bisa membantuku untuk mengelola rumah.",
  ui_story_5026_50260101_19_dialog_content = "Oh. Ya, tentu saja.",
  ui_story_5026_50260101_20_dialog_content = "Nah, terakhir, aku mau menyisihkan tiga juta untuk pemeliharaan harian dan perbaikan Soroz!",
  ui_story_5026_50260101_21_dialog_content = "Belakangan ini Soroz mengalami masa-masa yang berat.",
  ui_story_5026_50260101_22_dialog_content = "Pendaratan paksa sudah jadi hal yang biasa... Ini pasti sangat sulit untuk Soroz.",
  ui_story_5026_50260101_23_dialog_content = "Semoga Soroz tak akan marah besar kalau bangun...",
  ui_story_5026_50260101_24_dialog_content = "Nah, setelah dikurangi semua itu, sisanya jadi satu juta.",
  ui_story_5026_50260101_25_dialog_content = "Kau siap, PlayerName? Kita harus berangkat sekarang.",
  ui_story_5026_50260101_26_dialog_content = "Aduh, ini memang sudah siang, ya?",
  ui_story_5026_50260101_27_dialog_content = "Mau kita apakan sisa uangnya? Ayo kita pikirkan dalam perjalanan ke sana.",
  ui_story_5026_50260101_28_dialog_content = "Baiklah! Kalau begitu...",
  ui_story_5026_50260101_29_dialog_content = "Ayo kita pergi!",
  ui_story_5026_50260101_30_dialog_content = "Hmm? Di mana Vice? Bahkan Carleen pun...",
  ui_story_5026_50260101_31_dialog_content = "Chubb!",
  ui_story_5026_50260101_32_dialog_content = "Ternyata hanya mimpi...",
  ui_story_5026_50260101_33_dialog_content = "Tadinya aku cuma mau duduk dan istirahat sebentar, ternyata malah ketiduran.",
  ui_story_5026_50260101_34_dialog_content = "(Hmm... Carleen dan Vice masing-masing sudah pulang ke Lumopolis dan Gannon City untuk melanjutkan tugas mereka.)",
  ui_story_5026_50260101_35_dialog_content = "(Mungkin sekarang mereka sedang melaporkan pengalaman sebagai peserta pertempuran Obelisk of Return.)",
  ui_story_5026_50260101_36_dialog_content = "(...)",
  ui_story_5026_50260101_37_dialog_content = "(Hadiah utama senilai sepuluh juta... Pasti menyenangkan kalau itu jadi kenyataan...)",
  ui_story_5026_50260101_38_dialog_content = "(Sebaiknya aku cari angin dulu untuk menyegarkan pikiran.)",
  ui_story_5026_50260101_39_dialog_content = "Sunyi sekali.",
  ui_story_5026_50260101_40_dialog_content = "Meski sekarang hanya tinggal reruntuhan, mungkin dulu tempat ini sangat meriah.",
  ui_story_5026_50260101_42_dialog_content = "Hingga...",
  ui_story_5026_50260101_43_dialog_content = "Chubb! Chubb!",
  ui_story_5026_50260101_44_dialog_content = "Hah? Aku melamun lagi, ya? Kalau begini terus, aku tak akan sampai ke tempat memancing itu meski sudah berjalan seharian.",
  ui_story_5026_50260101_46_dialog_content = "Vice, Carleen, dan yang lain... Mereka sedang apa, ya?",
  ui_story_5026_50260101_47_dialog_content = "Berkat mereka semua, aku tak pernah merasa kesepian meski Soroz tertidur.",
  ui_story_5026_50260101_48_dialog_content = "Tapi, sekarang mereka semua sudah pulang.",
  ui_story_5026_50260101_49_dialog_content = "Lagi pula, memang ke tempat inilah seharusnya aku pulang, Eraveil.",
  ui_story_5026_50260101_50_dialog_content = "Memang sudah semestinya begitu, tapi kenapa... Hah?",
  ui_story_5026_50260101_51_dialog_content = "Kelihatannya ada sesuatu di rumput sebelah sana...",
  ui_story_5026_50260101_52_dialog_content = "Huaaaaaa?!",
  ui_story_5026_50260101_53_dialog_content = "G-gaah?!",
  ui_story_5026_50260101_54_dialog_content = "K-kok bisa-bisanya Eclipsite masuk ke Cloud Gardens?",
  ui_story_5026_50260101_55_dialog_content = "Graaaaaah!",
  ui_story_5026_50260101_56_dialog_content = "... Kelihatannya ia tak begitu kuat.",
  ui_story_5026_50260101_57_dialog_content = "<size=33>Gah...</size>",
  ui_story_5026_50260101_58_dialog_content = "Meski kelihatannya ia tak begitu kuat, aku tak bisa mengalahkannya dengan kail saja...",
  ui_story_5026_50260101_59_dialog_content = "Ah! Jangan kabur!",
  ui_story_5026_50260101_60_dialog_content = "<color=#e8d9bb>Ding...</color>",
  ui_story_5026_50260101_61_dialog_content = "Fufufu!",
  ui_story_5026_50260101_62_dialog_content = "Sepertinya aku datang tepat waktu.",
  ui_story_5026_50260101_63_dialog_content = "Bethel! Terima kasih untuk yang tadi!",
  ui_story_5026_50260101_64_dialog_content = "Bukan apa-apa. Aku justru khawatir kunjunganku yang mendadak akan merepotkanmu, PlayerName.",
  ui_story_5026_50260101_65_dialog_content = "Sama sekali tidak! Kalau tak ada kau, petak rumput ini mungkin sudah dirusak Spikepest.",
  ui_story_5026_50260101_66_dialog_content = "Cepat sekali lari mereka... Oh, apa kau kemari untuk mencariku karena suatu urusan?",
  ui_story_5026_50260101_67_dialog_content = "Sebenarnya, aku kemari untuk mewakili Sheol.",
  ui_story_5026_50260101_68_dialog_content = "Mewakili Sheol?",
  ui_story_5026_50260101_69_dialog_content = "Ini soal <color=#FFB400>tagihan</color> yang belum dibayar.",
  ui_story_5026_50260101_70_dialog_content = "PlayerName, kau ingat petualangan bawah tanahmu di Undercity di dekat Eternal Night?",
  ui_story_5026_50260101_71_dialog_content = "Kalau kau mau melakukan sesuatu untukku sebagai gantinya, aku mau-mau saja mencarikanmu informasi intel di Undercity.",
  ui_story_5026_50260101_72_dialog_content = "Sebaiknya kau pulang hidup-hidup dan membayarku.",
  ui_story_5026_50260101_73_dialog_content = "Sepertinya Vice tidak ada. Biasanya dia yang membantumu untuk mengelola pengeluaran, 'kan?",
  ui_story_5026_50260101_74_dialog_content = "Nah, ini tagihannya. Periksalah.",
  ui_story_5026_50260101_75_dialog_content = "Sini, biar kuperiksa. Hah?! <size=45>Ini biayanya?!</size>",
  ui_story_5026_50260101_76_dialog_content = "Aku tahu. Aku masih bermimpi. Pasti begitu! Ahahaha...",
  ui_story_5026_50260101_77_dialog_content = "Kau mau mengambil pinjaman, PlayerName?",
  ui_story_5026_50260101_78_dialog_content = "Aku bisa mewakilimu untuk melakukan negosiasinya, tapi harus ada catatan dari Umbraton Witness, Jane.",
  ui_story_5026_50260101_79_dialog_content = "Ini mungkin memengaruhi kelayakan kreditmu di Umbraton, tapi juga pengembangan Cloud Gardens jangka panjang.",
  ui_story_5026_50260101_80_dialog_content = "Tenang saja! Akan kubayar! Tapi, tidak sekarang...",
  ui_story_5026_50260101_81_dialog_content = "Satu hal lagi. Kau mau mengumpulkan dananya dengan cara apa?",
  ui_story_5026_50260101_82_option_content = "Mendirikan kios di Umbraton dan mengomersialkan kemampuan psikisku?",
  ui_story_5026_50260101_83_option_content = "Menangkap Corrupted Eclipsite?",
  ui_story_5026_50260101_84_dialog_content = "Rencana ceroboh begitu tak akan disetujui, PlayerName.",
  ui_story_5026_50260101_85_dialog_content = "Hmm... Cloud Gardens ini lumayan bagus.",
  ui_story_5026_50260101_86_dialog_content = "Ada pemandangan indah, banyak sumber daya, dan karya-karya unik Caelestite.",
  ui_story_5026_50260101_87_dialog_content = "Chubb?",
  ui_story_5026_50260101_88_dialog_content = "M-maksudmu, kau minta aku menjual Cloud Gardens? Atau menjual Chubb?",
  ui_story_5026_50260101_89_dialog_content = "Pedagang lain di Umbraton mungkin bakal mengusulkan ide yang sama.",
  ui_story_5026_50260101_90_dialog_content = "Tapi, tempat ini adalah rumah yang berhasil kaudapatkan dengan susah payah, 'kan?",
  ui_story_5026_50260101_91_dialog_content = "Begini, kalau merawatnya dengan lebih baik, kau bisa meraup keuntungan yang cukup besar.",
  ui_story_5026_50260101_92_dialog_content = "Maaf, butuh waktu yang sangat lama bagiku untuk memahaminya setelah mengalami banyak hal.",
  ui_story_5026_50260101_93_dialog_content = "Akhirnya aku punya rumah, tapi tak bisa mengurusnya dengan baik.",
  ui_story_5026_50260101_94_dialog_content = "Yah, seperti yang kaulihat tadi. Bahkan Eclipsite muncul di Cloud Gardens.",
  ui_story_5026_50260101_95_dialog_content = "Tepat saat tak ada orang di sini!",
  ui_story_5026_50260101_97_dialog_content = "Tolong beri tahu Sheol bahwa aku sangat berterima kasih atas bantuannya, dan aku tak akan lupa membayar tagihannya.",
  ui_story_5026_50260101_98_dialog_content = "Ya, aku paham. Akan kuajukan masa tenggang untukmu, PlayerName.",
  ui_story_5026_50260101_99_dialog_content = "Kau punya rencana untuk menangani para Eclipsite itu?",
  ui_story_5026_50260101_100_dialog_content = "Tak ada yang tahu dari mana mereka berasal...",
  ui_story_5026_50260101_100X1_dialog_content = "Kupikir Chord of the Law telah membuat Eraveil bersih dari Eclipsite.",
  ui_story_5026_50260101_100X2_dialog_content = "Tapi, kejadian di Obelisk of Return sudah lama, jadi mungkin Eclipsite itu berkeliaran dari tempat lain.",
  ui_story_5026_50260101_100X3_dialog_content = "Hmm… kalau hanya beberapa Spikepest, seharusnya aku bisa membereskannya sendiri…",
  ui_story_5026_50260101_101_dialog_content = "Bagaimana kalau...",
  ui_story_5026_50260101_102_dialog_content = "Bagaimana kalau kau merekrut sekelompok manajer untuk membantu? Tentu mereka harus memenuhi persyaratanmu.",
  ui_story_5026_50260101_103_dialog_content = "Ini akan langsung memecahkan masalah Eclipsite sekaligus memberimu nasihat dalam pembangunan Cloud Gardens. Sekali merengkuh dayung, dua tiga pulau terlampaui.",
  ui_story_5026_50260101_104_dialog_content = "Bagus juga idemu. Tapi, bagaimana cara mencari kandidat yang tepat?",
  ui_story_5026_50260101_105_dialog_content = "Proses rekrutmen, dan sumber daya yang relevan...",
  ui_story_5026_50260101_106_dialog_content = "Biar kubantu kau mengurus semuanya, PlayerName. Percayalah padaku.",
  ui_story_5026_50260101_107_dialog_content = "Tenang saja. Aku akan membantumu sebagai teman. Ini bukan perintah guild.",
  ui_story_5026_50260101_108_dialog_content = "Terima kasih sudah jadi teman yang bisa diandalkan, Bethel...",
  ui_story_5026_50260101_109_dialog_content = "Kalau begitu, kuserahkan padamu, ya!",
  ui_story_5026_50260201_1_dialog_content = "<color=#e8d9bb>Di Luar Eraveil</color>",
  ui_story_5026_50260201_2_dialog_content = "Bagus. Ini sudah dekat dengan Cloud Gardens.",
  ui_story_5026_50260201_3_dialog_content = "Eraveil, ujung dunia... Bahkan Ayah pun tak bakal punya pengaruh di sini.",
  ui_story_5026_50260201_4_dialog_content = "Jangan sampai ketinggalan, <color=#FFB400>Sanae</color>.",
  ui_story_5026_50260201_5_dialog_content = "N-Nona Nina! Tunggu aku!",
  ui_story_5026_50260201_6_dialog_content = "Sebelum kita berangkat tadi, sudah kubilang panggil aku <color=#FFB400>Nina</color>. Panggil aku Nina saja saat kita di luar!",
  ui_story_5026_50260201_7_dialog_content = "Nah, kau berjanji kita tak akan diikuti saat meninggalkan Umbraton, 'kan, Tuan Odd Jobs?",
  ui_story_5026_50260201_8_dialog_content = "Wah, kata-katamu barusan membuatku tersinggung, Nona Andersen. Mata pencaharianku bergantung pada kepercayaan klien.",
  ui_story_5026_50260201_9_dialog_content = "Odd Jobs akan melakukan apa pun yang klien minta, dari menyelamatkan dunia hingga mencari kucing...",
  ui_story_5026_50260201_10_dialog_content = "Yah, kalau begitu aku mau tanya. Sedang apa dia di sini?",
  ui_story_5026_50260201_11_dialog_content = "Argh. Ini sebabnya tadinya aku tak mau melakukan pekerjaan ini...",
  ui_story_5026_50260201_12_dialog_content = "Selamat siang, Nona Nina. Kau sudah menempuh perjalanan panjang. Silakan istirahat di sini.",
  ui_story_5026_50260201_13_dialog_content = "... <color=#FFB400>Minos</color>, kapan kau sampai di sini?",
  ui_story_5026_50260201_14_dialog_content = "Kumohon, Nona. Jangan asal menuduh Taki. Aku benar-benar tak mengikuti kelompokmu.",
  ui_story_5026_50260201_15_dialog_content = "Oho! Tenda, selimut piknik, air soda, roti isi, lilin wangi, dan bahkan bunga segar...",
  ui_story_5026_50260201_16_dialog_content = "Wah, rupanya persiapanmu sangat matang. Sepertinya kau memang sudah ada di sini sebelum Nona itu datang ke kantorku.",
  ui_story_5026_50260201_17_dialog_content = "Pelayan elite keluarga Andersen memang luar biasa.",
  ui_story_5026_50260201_18_dialog_content = "Dengan informasi intel yang cukup, rencana perjalanan Nona Nina tak terlalu sulit untuk diprediksi.",
  ui_story_5026_50260201_19_dialog_content = "Tolong pulanglah denganku kalau kau sudah selesai minum teh, Nona. Tuan mengkhawatirkanmu.",
  ui_story_5026_50260201_20_dialog_content = "Aku tak mau pulang! A-aku kabur dari rumah!",
  ui_story_5026_50260201_21_dialog_content = "Ya, tapi aku sudah mendapat perintah. Bahkan kalau aku harus mengejarmu sampai ke ujung dunia...",
  ui_story_5026_50260201_22_dialog_content = "Aku harus membawamu pulang.",
  ui_story_5026_50260201_23_dialog_content = "Bodoh! Ayah memang bodoh!",
  ui_story_5026_50260201_24_dialog_content = "Tolong jaga bicaramu, Nona. Jangan lupa bersikap elegan seperti layaknya wanita bangsawan.",
  ui_story_5026_50260201_25_dialog_content = "Ehem. Sepertinya tak ada yang bisa kulakukan lagi. Terima kasih atas bantuanmu, Nona Andersen.",
  ui_story_5026_50260201_26_dialog_content = "Jangan lupa memberikan ulasan yang bagus setelah kau pulang ke Umbraton!",
  ui_story_5026_50260201_27_dialog_content = "Sudah kubilang aku tak mau pulang!",
  ui_story_5026_50260201_28_dialog_content = "Setidaknya hingga aku bisa mendekati Caelestite itu, mewujudkan rencanaku, dan membuktikan kemampuanku! Pokoknya aku tak mau pulang dulu!",
  ui_story_5026_50260201_29_dialog_content = "Eh, Tuan Minos, aku...",
  ui_story_5026_50260201_30_dialog_content = "Tak perlu menjelaskannya, Sanae. Prioritas kita sekarang adalah menenangkan Nona Muda dan membawanya pulang dengan selamat.",
  ui_story_5026_50260201_31_dialog_content = "Kau sudah lalai dalam tugasmu sebagai pelayan keluarga Andersen untuk melapor tepat waktu. Aku akan mencatatnya dalam penilaian akhir bulan.",
  ui_story_5026_50260201_32_dialog_content = "A-aku bakal dipecat...?",
  ui_story_5026_50260201_33_dialog_content = "Kau sudah melakukan tindakan yang mengancam!",
  ui_story_5026_50260201_34_dialog_content = "Aduh! Hentikan, Manae!",
  ui_story_5026_50260201_35_dialog_content = "Lho? Kan memang begitu kenyataannya!",
  ui_story_5026_50260201_36_dialog_content = "Aku tahu Nona Muda sangat dekat denganmu karena kau satu-satunya orang di wastu yang berusia sebaya dengannya.",
  ui_story_5026_50260201_37_dialog_content = "Mungkin itu alasannya mengajakmu kabur.",
  ui_story_5026_50260201_38_dialog_content = "Tapi, keberlangsungan pekerjaanmu di wastu bergantung pada kinerjamu kali ini.",
  ui_story_5026_50260201_39_dialog_content = "M-maksudmu...",
  ui_story_5026_50260201_40_dialog_content = "Sanae! Kenapa kau lama sekali? Nanti kita terlambat untuk tes wawancaranya!",
  ui_story_5026_50260201_41_dialog_content = "I-iya! Aku datang!",
  ui_story_5026_50260201_42_dialog_content = "Tekad Nona Muda benar-benar mengagumkan.",
  ui_story_5026_50260201_43_dialog_content = "Kalau begitu, aku juga harus melakukan tindakan drastis.",
  ui_story_5026_50260201_44_dialog_content = "<color=#e8d9bb>Di Area Tes Wawancara Manajer Cloud Gardens</color>",
  ui_story_5026_50260201_45_dialog_content = "...",
  ui_story_5026_50260201_46_dialog_content = "<size=33>Ayolah. Katakan sesuatu, PlayerName.</size>",
  ui_story_5026_50260201_47_dialog_content = "<size=33>Seperti latihan kita tadi!</size>",
  ui_story_5026_50260201_48_dialog_content = "Kalau begitu... Pertanyaan pertama: Kenapa kau melamar posisi manajer di Cloud Gardens?",
  ui_story_5026_50260201_49_dialog_content = "Aduh, membosankan sekali.",
  ui_story_5026_50260201_50_dialog_content = "Apa?",
  ui_story_5026_50260201_51_dialog_content = "Aku berubah pikiran, ah. Hentikan wawancaranya. Toh aku hanya mau melihat-lihat saja.",
  ui_story_5026_50260201_52_dialog_content = "Cari aku lagi kalau kau butuh membakar sesuatu, ya.",
  ui_story_5026_50260201_53_dialog_content = "Semoga kau segera mendapat kandidat yang tepat.",
  ui_story_5026_50260201_54_dialog_content = "Dia sudah pergi...",
  ui_story_5026_50260201_55_dialog_content = "Jangan terlalu takut-takut begitu, PlayerName. Ayo tunjukkan martabat sebagai pewawancara.",
  ui_story_5026_50260201_56_dialog_content = "Kau kan master Eraveil!",
  ui_story_5026_50260201_57_dialog_content = "Kandidat berikutnya!",
  ui_story_5026_50260201_58_dialog_content = "Halo, PlayerName. A-aku Connolly.",
  ui_story_5026_50260201_59_dialog_content = "(Martabat... Master...)",
  ui_story_5026_50260201_60_option_content = "Tiru kebijaksanaan Schwartz",
  ui_story_5026_50260201_61_dialog_content = "Silakan duduk, Connolly. Senang kau datang kemari.",
  ui_story_5026_50260201_62_dialog_content = "Kita langsung saja. Coba jelaskan apa yang kaupahami tentang Cloud Gardens dan posisi manajer.",
  ui_story_5026_50260201_63_dialog_content = "Kau punya strategi untuk menangani Eclipsite? Sebagai anak muda, apa kau punya ide bagus? Aku siap mendengarkan.",
  ui_story_5026_50260201_64_option_content = "Tiru keberanian Reinhardt",
  ui_story_5026_50260201_65_dialog_content = "Hahaha! Duduklah, Connolly!",
  ui_story_5026_50260201_66_dialog_content = "Kau tak punya pengalaman sebagai manajer sungguhan, 'kan?",
  ui_story_5026_50260201_67_dialog_content = "Bagus. Aku menghargai semangatmu yang giat.",
  ui_story_5026_50260201_68_dialog_content = "Tak bakal ada masalah asalkan kau mau kerja keras. Akan kujadikan kau \"tentara\" yang hebat!",
  ui_story_5026_50260201_69_option_content = "Tiru ketenangan Bethlehem",
  ui_story_5026_50260201_70_dialog_content = "Duduklah. Kedatanganmu juga merupakan takdir.",
  ui_story_5026_50260201_71_dialog_content = "Sepertinya kau agak gugup. Mau minum teh hitam?",
  ui_story_5026_50260201_72_dialog_content = "Eh... Tingkah Navigator aneh sekali hari ini!",
  ui_story_5026_50260201_73_dialog_content = "Maaf! Aku tak bermaksud menyulitkanmu!",
  ui_story_5026_50260201_74_dialog_content = "Sayang sekali. Aku mengacau lagi.",
  ui_story_5026_50260201_75_dialog_content = "Sebentar lagi malam. Ada berapa sisa kandidatnya?",
  ui_story_5026_50260201_76_dialog_content = "Ini sisa resumenya. Biar kulihat...",
  ui_story_5026_50260201_77_dialog_content = "G-graah!",
  ui_story_5026_50260201_78_dialog_content = "Itu kandidat? Kok agak aneh.",
  ui_story_5026_50260201_79_dialog_content = "(Bahasa Eclipsian) Akan kulakukan apa pun! Tolong beri aku pekerjaan!",
  ui_story_5026_50260201_80_dialog_content = "Ada Eclipsite! Kok dia bisa masuk?",
  ui_story_5026_50260201_81_dialog_content = "Jumlahnya lebih dari satu!",
  ui_story_5026_50260202_1_dialog_content = "Tak kusangka Eclipsite bakal ikut rekrutmen...",
  ui_story_5026_50260202_2_dialog_content = "Ternyata masalah Eclipsite di Cloud Gardens lebih serius dari dugaanku.",
  ui_story_5026_50260202_3_dialog_content = "Meski sangat butuh bantuan, aku tak berharap bisa menemukan kandidat yang cocok hari ini.",
  ui_story_5026_50260202_4_dialog_content = "Aku benar-benar minta maaf... Aku sudah janji akan membantumu.",
  ui_story_5026_50260202_5_dialog_content = "Tidak, tidak. Ini bukan salahmu, kok.",
  ui_story_5026_50260202_6_dialog_content = "Aku butuh mempekerjakan orang, tapi gaji yang sanggup kubayarkan bahkan tak cukup untuk membeli lukisan tiruan.",
  ui_story_5026_50260202_7_dialog_content = "Meski punya banyak teman di Umbraton...",
  ui_story_5026_50260202_8_dialog_content = "Aku tak bisa terus-terusan mengandalkan kebaikan hati mereka. Dedikasi mereka tak boleh disia-siakan.",
  ui_story_5026_50260202_9_dialog_content = "Tapi, kalau keadaannya begini terus...",
  ui_story_5026_50260202_10_dialog_content = "Senang bertemu denganmu, Navigator.",
  ui_story_5026_50260202_11_dialog_content = "Wow, ini Cloud Gardens yang jadi buah bibir itu...",
  ui_story_5026_50260202_12_dialog_content = "Agak berbeda dengan yang Umbraton Daily deskripsikan dalam serial: \"Terungkap! Caelestite Terakhir yang Membingungkan!\"",
  ui_story_5026_50260202_13_dialog_content = "Masih ada kandidat lain...?",
  ui_story_5026_50260202_14_dialog_content = "H-halo. Biar kubaca dulu resume kalian... Kau pasti Nina.",
  ui_story_5026_50260202_15_dialog_content = "Lulusan Dawn Academy dengan segudang pengalaman dalam pengembangan bisnis dan sumber daya manusia.",
  ui_story_5026_50260202_16_dialog_content = "Benar sekali!",
  ui_story_5026_50260202_17_dialog_content = "Lalu, rekanmu Sanae bisa mengerjakan tugas bersih-bersih rumah, berkebun, dan berbagai tugas cuci-mencuci?",
  ui_story_5026_50260202_18_dialog_content = "A-akan kucoba semampuku!",
  ui_story_5026_50260202_19_dialog_content = "Sejauh ini mereka tampak seperti kandidat terbaik!",
  ui_story_5026_50260202_20_dialog_content = "Bagus sekali, PlayerName.",
  ui_story_5026_50260202_21_dialog_content = "Kau siap mencapai puncak kehidupan dengan bantuanku?",
  ui_story_5026_50260202_22_dialog_content = "Hah?",
  ui_story_5026_50260202_23_dialog_content = "Sebagai Caelestite terakhir di benua ini, aku akan membuatkanmu rencana penaklukan!",
  ui_story_5026_50260202_24_dialog_content = "Penaklukan?! Itu agak dramatis...",
  ui_story_5026_50260202_25_dialog_content = "Situasi ini akan sama-sama menguntungkan bagi kita berdua. Kau pasti akan membuat keputusan yang tepat.",
  ui_story_5026_50260202_26_dialog_content = "B-baiklah. Tunggu sebentar, ya.",
  ui_story_5026_50260202_27_dialog_content = "Resume ini hanya berisi informasi dua orang. Siapa kalian sebenarnya?",
  ui_story_5026_50260202_28_dialog_content = "Salam. Maafkan aku karena sudah mengganggu. Panggil saja aku Minos.",
  ui_story_5026_50260202_29_dialog_content = "Dulu aku belajar di Butler Training School di Lumopolis. Ini sertifikat dan lisensiku.",
  ui_story_5026_50260202_30_dialog_content = "Wow, sangat profesional! Kalian bertiga satu tim, ya?",
  ui_story_5026_50260202_31_dialog_content = "Tentu saja tidak!",
  ui_story_5026_50260202_32_dialog_content = "Apa?",
  ui_story_5026_50260202_33_dialog_content = "Ada kesalahpahaman kecil di antara aku dan Nona Nina. Tolong jangan dipikirkan. Biar kuurus.",
  ui_story_5026_50260202_34_dialog_content = "Kalau aku tidak salah, kau cukup puas dengan resume kami, 'kan?",
  ui_story_5026_50260202_35_dialog_content = "Ya…",
  ui_story_5026_50260202_36_dialog_content = "Aku merasa terhormat karena jadi yang terpilih, alih-alih orang lain.",
  ui_story_5026_50260202_37_dialog_content = "Yah, soal itu... Sebenarnya...",
  ui_story_5026_50260202_38_dialog_content = "Kau pasti punya persyaratan yang sangat ketat untuk posisi manajer, dan seleksi terakhir ini membuatmu bingung.",
  ui_story_5026_50260202_39_dialog_content = "Terlepas dari persyaratannya, gaji yang bisa kubayarkan agak...",
  ui_story_5026_50260202_40_dialog_content = "Aku punya usul.",
  ui_story_5026_50260202_41_dialog_content = "Bagaimana kalau aku dan kedua gadis itu <color=#FFB400>dibagi dalam dua kelompok</color> dan jadi <color=#FFB400>manajer percobaan</color> tanpa dibayar?",
  ui_story_5026_50260202_42_dialog_content = "Semuanya gratis?",
  ui_story_5026_50260202_43_dialog_content = "Benar. Kami akan jadi manajermu, nanti kau pilih sendiri kelompok yang lebih kompeten.",
  ui_story_5026_50260202_44_dialog_content = "Kepuasanmu terhadap kinerja kami adalah yang utama. Masalah gaji bisa dirundingkan setelah masa percobaan.",
  ui_story_5026_50260202_45_dialog_content = "Ini juga hal yang lumrah dalam penawaran komersial di Umbraton, dan kuharap ini bisa mengatasi masalahmu.",
  ui_story_5026_50260202_46_dialog_content = "Gratis!",
  ui_story_5026_50260202_47_dialog_content = "Nona Nina, Sanae, maafkan aku karena sudah merenggut kebebasan kalian dengan mengajukan usulan ini. Kalau kalian keberatan...",
  ui_story_5026_50260202_48_dialog_content = "Bukan masalah. Ayo kita bersaing!",
  ui_story_5026_50260202_49_dialog_content = "Aku tak peduli dengan gajinya karena potensi Eraveil tak bisa diukur dengan uang. Iya, 'kan?",
  ui_story_5026_50260202_50_dialog_content = "Yah, kurasa begitu.",
  ui_story_5026_50260202_51_dialog_content = "Bagaimanapun, mendapat tiga asisten yang sangat cakap dengan gratis justru melampaui ekspektasiku.",
  ui_story_5026_50260202_52_dialog_content = "Bethel, bagaimana menurutmu?",
  ui_story_5026_50260202_53_dialog_content = "...",
  ui_story_5026_50260202_54_dialog_content = "Bagus! Sepertinya hasil tes wawancaranya sudah jelas!",
  ui_story_5026_50260202_55_dialog_content = "Hah? Ya!",
  ui_story_5026_50260202_56_dialog_content = "Kalau begitu, Minos, Nina, dan Sanae... Kuserahkan pengelolaan Cloud Gardens kepada kalian!",
  ui_story_5026_50260202_57_dialog_content = "Memang agak terlambat mengatakannya, tapi... Selamat datang di Cloud Gardens. Semoga kalian menyukai tempat ini!",
  ui_story_5026_50260202_58_dialog_content = "Nina, Nina Andersen...",
  ui_story_5026_50260202_59_dialog_content = "Nona Muda dari keluarga Andersen. Kenapa dia menyembunyikan nama belakangnya dan melamar posisi manajer di Cloud Gardens?",
  ui_story_5026_50260202_60_dialog_content = "Sanae juga adalah pelayan yang kuperkenalkan kepada keluarga Andersen baru-baru ini.",
  ui_story_5026_50260202_61_dialog_content = "Kalau Minos, dia memang pelayan sungguhan.",
  ui_story_5026_50260202_62_dialog_content = "Dia selalu mengikuti Count Andersen seperti bayang-bayang saat aku mengunjungi wastu mereka untuk urusan bisnis.",
  ui_story_5026_50260202_63_dialog_content = "Kelompok yang aneh.",
  ui_story_5026_50260202_64_dialog_content = "Tapi, keluarga Andersen berteman dengan ayahku. Kudengar Nina adalah anak yang tekun saat bersekolah di Dawn Academy...",
  ui_story_5026_50260202_65_dialog_content = "Masih ada banyak tugas yang harus kuselesaikan. Aku harus kembali ke Umbraton.",
  ui_story_5026_50260202_66_dialog_content = "Semoga semuanya baik-baik saja...",
  ui_story_5026_50260301_1_dialog_content = "<color=#e8d9bb>Di Samping Fountain of Hope di Cloud Gardens</color>",
  ui_story_5026_50260301_2_dialog_content = "Aku kemari setelah membaca pemberitahuan rekrutmen yang dipasang Cloudrover Guild, tapi tak kusangka Bethel yang membuatnya.",
  ui_story_5026_50260301_3_dialog_content = "Dia sudah menjalin hubungan bisnis yang stabil dengan Caelestite itu? Tak diragukan lagi, dia memang siswa berprestasi.",
  ui_story_5026_50260301_4_dialog_content = "Kau juga, Minos. Apa yang kaurencanakan?",
  ui_story_5026_50260301_5_dialog_content = "Tolong jaga bicaramu, Nona. Jangan lupa bersikap elegan seperti layaknya wanita bangsawan.",
  ui_story_5026_50260301_6_dialog_content = "Seperti yang kukatakan padamu tadi, dan pada PlayerName, aku hanya memberi usul.",
  ui_story_5026_50260301_7_dialog_content = "Mau coba-coba mencegahku tinggal di sini, ya? Memangnya kau pikir aku bakal pulang dengan patuh kalau kau pakai cara begitu?",
  ui_story_5026_50260301_8_dialog_content = "Sebagai orang yang sangat dipercaya ayahku, kupikir kau bakal melakukan sesuatu yang lebih pintar.",
  ui_story_5026_50260301_9_dialog_content = "Kau terlalu memujiku, Nona. Senang rasanya dipuji begitu olehmu dan Tuan.",
  ui_story_5026_50260301_10_dialog_content = "Aku tidak memujimu!",
  ui_story_5026_50260301_11_dialog_content = "Biar kuperjelas, ya—aku tak akan kalah!",
  ui_story_5026_50260301_12_dialog_content = "Aku punya banyak toko di Umbraton: toko pakaian, toko perhiasan, toko senjata...",
  ui_story_5026_50260301_13_dialog_content = "Perkebunan di pedesaan biasa bukanlah masalah bagiku.",
  ui_story_5026_50260301_14_dialog_content = "Mengelola tempat seperti ini adalah urusan sepele.",
  ui_story_5026_50260301_15_dialog_content = "Oh, ya, setelah aku mendapat kepercayaan Caelestite itu...",
  ui_story_5026_50260301_16_dialog_content = "Akan kubangun tempat ini menjadi kota metropolitan komersial yang tak kalah dengan Umbraton dengan cara apa pun, langkah demi langkah!",
  ui_story_5026_50260301_17_dialog_content = "Suatu hari nanti, tempat ini akan jadi lebih maju ketimbang kota mati yang hidup di balik bayang-bayang Lumopolis.",
  ui_story_5026_50260301_18_dialog_content = "Aku akan membuktikannya padamu dan Ayah tanpa uang dan pengaruh keluarga Andersen...",
  ui_story_5026_50260301_19_dialog_content = "Aku tetap bisa berdiri sendiri!",
  ui_story_5026_50260301_20_dialog_content = "Tentu saja, Nona. Visi besarmu memang mengagumkan.",
  ui_story_5026_50260301_21_dialog_content = "Kalau begitu, aku mau mengajukan satu usul lagi.",
  ui_story_5026_50260301_22_dialog_content = "Kalau kau bisa mengalahkanku dalam <color=#FFB400>hal apa saja</color> saat bekerja di Cloud Gardens, aku akan berhenti berusaha membawamu pulang.",
  ui_story_5026_50260301_23_dialog_content = "Silakan.",
  ui_story_5026_50260301_24_dialog_content = "Kalau kau menang, aku akan langsung pergi. Kita tak akan bertemu lagi kecuali kau yang minta.",
  ui_story_5026_50260301_25_dialog_content = "Janji?",
  ui_story_5026_50260301_26_dialog_content = "Aku janji. Lagi pula, kau bisa mencari asisten. Itu saranku.",
  ui_story_5026_50260301_27_dialog_content = "Tapi, entah seberapa banyak bantuan yang bisa Sanae berikan. Toh jumlah cangkir yang dipecahkannya lebih banyak dari yang dicucinya saat di wastu.",
  ui_story_5026_50260301_28_dialog_content = "Kau…!",
  ui_story_5026_50260301_29_dialog_content = "N-Nona! Eh, maksudku, Nina! PlayerName kemari.",
  ui_story_5026_50260301_30_dialog_content = "Maaf, aku terlambat. Membersihkan area tes wawancara butuh waktu.",
  ui_story_5026_50260301_31_dialog_content = "Apa terjadi sesuatu?",
  ui_story_5026_50260301_32_dialog_content = "(Sepertinya tadi kulihat Nina coba memukul kepala Minos dengan payungnya... Itu payung, 'kan?)",
  ui_story_5026_50260301_33_dialog_content = "Sama sekali bukan apa-apa!",
  ui_story_5026_50260301_34_dialog_content = "Tak ada yang perlu dikhawatirkan, Navigator. Silakan lanjutkan.",
  ui_story_5026_50260301_35_dialog_content = "Ehem, seperti yang kutuliskan di deskripsi pekerjaannya...",
  ui_story_5026_50260301_36_dialog_content = "Kuharap kalian mau ikut berpatroli di setiap area, mengevaluasi tingkat keparahan serangan Eclipsite, dan menyingkirkan Eclipsite.",
  ui_story_5026_50260301_37_dialog_content = "Selain itu, aku mau kalian turut serta dalam tugas harian pengelolaan Cloud Gardens, dan memberikan saran profesional tentang cara mendapatkan pemasukan.",
  ui_story_5026_50260301_38_dialog_content = "(Bethel yang menuliskan deskripsinya, dan kalimatnya sangat resmi! Aduh, aku tak terbiasa seperti ini...)",
  ui_story_5026_50260301_39_dialog_content = "Kalau begitu... Akan kuperkenalkan tempat ini dengan singkat sebelum kita mulai bekerja.",
  ui_story_5026_50260301_40_dialog_content = "Ini adalah area pusat Cloud Gardens.",
  ui_story_5026_50260301_41_dialog_content = "Ke mana pun Anda ingin mengunjungi, ini adalah tempat awal yang paling nyaman.",
  ui_story_5026_50260301_42_dialog_content = "Menara putih di belakang kita disebut Hyacinth Tower.",
  ui_story_5026_50260301_43_dialog_content = "Semua menara putih ini, termasuk Hyacinth Tower, adalah kompleks peninggalan kaum Caelestite kuno.",
  ui_story_5026_50260301_44_dialog_content = "Di menara, ada banyak tumpukan cetak biru dan beberapa perangkat yang gagal kuaktifkan...",
  ui_story_5026_50260301_45_dialog_content = "Oh? Penemuan kaum Caelestite? Kau punya cetak biru senjata?",
  ui_story_5026_50260301_46_dialog_content = "Eh... Sejauh ini aku hanya menemukan cetak biru bangunan dan perabot, sih.",
  ui_story_5026_50260301_47_dialog_content = "PlayerName, kaulah satu-satunya Caelestite yang diketahui sejauh ini.",
  ui_story_5026_50260301_48_dialog_content = "Kau punya pesawat raksasa dan teknologi kuno misterius. Kau juga bisa memperkuat Aurorian dalam pertempuran.",
  ui_story_5026_50260301_49_dialog_content = "Kudengar kaum Caelestite adalah kaum yang selalu bersikap baik dan cinta damai...",
  ui_story_5026_50260301_50_dialog_content = "Tapi, cita-citamu bukan hanya membangun Eraveil, 'kan?",
  ui_story_5026_50260301_51_dialog_content = "(Sepertinya Nina sudah mempelajariku!)",
  ui_story_5026_50260301_52_dialog_content = "Kau tampak terkejut?",
  ui_story_5026_50260301_53_dialog_content = "Pemeriksaan latar belakang itu perlu karena kau adalah rekan yang penting.",
  ui_story_5026_50260301_54_dialog_content = "Jadi, kau mulai tertarik dengan rencana penaklukanku?",
  ui_story_5026_50260301_55_dialog_content = "Sekarang, aku bahkan belum mengurus segala hal yang ada di Eraveil...",
  ui_story_5026_50260301_56_dialog_content = "Prioritas kita sekarang adalah mengerjakan dengan baik tugas-tugas yang ada di depan mata.",
  ui_story_5026_50260301_57_dialog_content = "Kalau tak ada pertanyaan lain...",
  ui_story_5026_50260301_58_dialog_content = "Bagaimana kalau kita mulai menanam pohon?",
  ui_story_5026_50260301_59_dialog_content = "Nah, di sinilah tempat untuk membudidayakan tanaman bernama Unique Tree...",
  ui_story_5026_50260301_60_dialog_content = "Yah, pokoknya tanaman apa saja.",
  ui_story_5026_50260301_61_dialog_content = "Mungkin ciri uniknya adalah kemampuan tanaman itu untuk jadi tak kasat mata?",
  ui_story_5026_50260301_62_dialog_content = "Eraveil yang terpencil ini memang punya spesies tanaman yang sangat unik, ya.",
  ui_story_5026_50260301_63_dialog_content = "Harus kuakui, aku tak tahu cara membudidayakan tanaman. Jadi, seperti yang kalian lihat...",
  ui_story_5026_50260301_64_dialog_content = "Banyak sekali tanaman yang gagal berkecambah, dan yang bisa tumbuh malah bengkok batangnya.",
  ui_story_5026_50260301_65_dialog_content = "Ehem, iya. Tapi, aku tak mau menyerah.",
  ui_story_5026_50260301_66_dialog_content = "Ayo kita pangkas tanaman yang rusak dan tanam benih baru.",
  ui_story_5026_50260301_67_dialog_content = "Sepertinya pekerjaan ini akan mengotori rok...",
  ui_story_5026_50260301_68_dialog_content = "Benda apa yang seperti sendok raksasa itu?",
  ui_story_5026_50260301_69_dialog_content = "Itu sekop tebal untuk menyekop. Belum pernah lihat?",
  ui_story_5026_50260301_70_dialog_content = "Tentu pernah! Aku sering melihatnya saat mengunjungi kebun dengan ayahku!",
  ui_story_5026_50260301_71_dialog_content = "Hanya saja ini berbeda dengan yang biasa keluargaku gunakan!",
  ui_story_5026_50260301_72_dialog_content = "S-sini, berikan padaku. Biar kuperiksa!",
  ui_story_5026_50260301_73_dialog_content = "Memangnya ada banyak jenis sekop, ya? Ternyata tanam-menanam jauh lebih rumit dari dugaanku.",
  ui_story_5026_50260301_74_dialog_content = "Aku mau lihat mereka berdua sedang apa.",
  ui_story_5026_50260301_75_dialog_content = "Halo, PlayerName.",
  ui_story_5026_50260301_76_dialog_content = "Tentang pemangkasan Unique Tree... Kau lebih suka gaya Lumopolis atau Northland Winter Palace?",
  ui_story_5026_50260301_77_dialog_content = "Keduanya sama-sama populer di Umbraton, tapi selera Caelestite Terakhir mungkin berbeda.",
  ui_story_5026_50260301_78_dialog_content = "Maafkan aku. Aku sudah lancang.",
  ui_story_5026_50260301_79_dialog_content = "... Ya ampun!",
  ui_story_5026_50260301_80_dialog_content = "<size=37>Seperti apa rasa buah Unique Tree?</size>",
  ui_story_5026_50260301_81_dialog_content = "<size=35>Apa aku bakal mendapat kekuatan spesial kalau memakannya? Apa bakal tumbuh sayap dan ekor?</size>",
  ui_story_5026_50260301_82_dialog_content = "<size=33>Apalagi ini kebun Caelestite Terakhir yang Membingungkan itu...</size>",
  ui_story_5026_50260301_83_dialog_content = "<size=40>Aah! Bukan waktunya bertanya-tanya! Kalau tidak membantu Minos, aku bakal...</size>",
  ui_story_5026_50260301_84_dialog_content = "<size=33>Tapi, aku juga tak mau membuat Nona Nina sedih...</size>",
  ui_story_5026_50260301_85_dialog_content = "(Sanae menatap lubang besar di hadapannya sambil berbicara sendiri...)",
  ui_story_5026_50260301_86_dialog_content = "Eh, Sanae...",
  ui_story_5026_50260301_87_dialog_content = "Iya! Aku di sini!",
  ui_story_5026_50260301_88_dialog_content = "Kita butuh beberapa lubang dangkal untuk menanam benih. Lubang yang kaugali itu terlalu dalam, bahkan cukup untuk menguburku.",
  ui_story_5026_50260301_89_dialog_content = "A-aku hanya menggali sedikit, kok!",
  ui_story_5026_50260301_90_dialog_content = "Chubb...",
  ui_story_5026_50260301_91_dialog_content = "Caelestite terdeteksi, Chubb!",
  ui_story_5026_50260301_92_dialog_content = "Suara apa itu?",
  ui_story_5026_50260301_93_dialog_content = "Sekop tebal ini benar-benar hebat, PlayerName.",
  ui_story_5026_50260301_94_dialog_content = "Tinggal kubur benih pohonnya lalu tepuk-tepuk tanah dengan sekop dua kali...",
  ui_story_5026_50260301_95_dialog_content = "Lalu sebatang Unique Tree yang bisa bicara tahu-tahu langsung jadi besar.",
  ui_story_5026_50260301_96_dialog_content = "Oh, ini bukan Unique Tree. Mungkin ia berjalan ke tumpukan ini secara kebetulan.",
  ui_story_5026_50260301_97_dialog_content = "Aku... aku tahu, kok! Mana mungkin ini Unique Tree?",
  ui_story_5026_50260301_98_dialog_content = "Kami memanggilnya Chubb. Mereka datang bersama Cloud Gardens setelah Obelisk of Return muncul.",
  ui_story_5026_50260301_99_dialog_content = "Chubb!",
  ui_story_5026_50260301_100_dialog_content = "Dia…",
  ui_story_5026_50260301_101_dialog_content = "Dia imut sekali...!",
  ui_story_5026_50260301_102_dialog_content = "Ehem... Si kecil ini bisa melakukan apa?",
  ui_story_5026_50260301_103_dialog_content = "Menurut deskripsimu, ia adalah penghuni Cloud Gardens, seperti dirimu.",
  ui_story_5026_50260301_104_dialog_content = "Jadi, selain tampak imut, ia juga menyumbangkan sesuatu untuk tempat ini, 'kan?",
  ui_story_5026_50260301_105_dialog_content = "Chubb...",
  ui_story_5026_50260301_106_dialog_content = "Beberapa Chubb mengajariku berbagai hal tentang Cloud Gardens dan membantuku untuk mengurus Unique Tree.",
  ui_story_5026_50260301_107_dialog_content = "Tapi, sebagian besar yang Chubb lakukan hanya jalan-jalan atau tidur di Cloud Gardens.",
  ui_story_5026_50260301_108_dialog_content = "Aku tak tahu banyak soal spesifikasi struktur atau fungsinya.",
  ui_story_5026_50260301_109_dialog_content = "Tapi, melihatnya berjalan-jalan sudah membuatku senang.",
  ui_story_5026_50260301_110_dialog_content = "Beberapa orang Rediesel Wrench dan Illumina suka mengejarnya dan berkata ingin membongkarnya agar bisa melihat bagian dalamnya...",
  ui_story_5026_50260301_111_dialog_content = "Chubb! Jangan bongkar Chubb!",
  ui_story_5026_50260301_112_dialog_content = "Dia pemalu, seperti kelinci.",
  ui_story_5026_50260301_113_dialog_content = "Eh... Aku membelai si kecil ini karena ia tampak ketakutan. Sebenarnya aku tak mau membelainya, kok. Jangan salah paham.",
  ui_story_5026_50260301_114_dialog_content = "(Eclipsite bermunculan di Cloud Gardens, tapi Chubb tetap tenang-tenang saja.)",
  ui_story_5026_50260301_115_dialog_content = "(Mereka ini memang bodoh atau tak menganggap Eclipsite sebagai musuh seperti yang dilakukan Caelestite, ya?)",
  ui_story_5026_50260301_116_dialog_content = "(Relik dari ribuan tahun lalu menyimpan begitu banyak rahasia. Entah apa aku ingin mengetahui semuanya...)",
  ui_story_5026_50260301_117_dialog_content = "Chubb?",
  ui_story_5026_50260301_118_dialog_content = "(Yah, kurasa mereka memang bodoh.)",
  ui_story_5026_50260301_119_dialog_content = "Chubb!",
  ui_story_5026_50260301_120_dialog_content = "Lagi? Kau mau aku menggaruk telingamu juga? Yah, apa boleh buat.",
  ui_story_5026_50260301_121_dialog_content = "Kalau yang ini bernama Chubb, yang itu siapa?",
  ui_story_5026_50260301_122_dialog_content = "Hah? Namanya juga Chubb.",
  ui_story_5026_50260301_123_dialog_content = "Tapi, mereka tampak berbeda. Lihat bentuk mata dan lekuk mulut mereka saat tersenyum!",
  ui_story_5026_50260301_124_dialog_content = "Hah? Memangnya, apa bedanya?",
  ui_story_5026_50260301_125_dialog_content = "Dasar amatir...",
  ui_story_5026_50260301_126_dialog_content = "Amatir?",
  ui_story_5026_50260301_127_dialog_content = "Dengar, PlayerName.",
  ui_story_5026_50260301_128_dialog_content = "Salah satu prinsip utama manajemen adalah mengenal karyawan dengan baik.",
  ui_story_5026_50260301_129_dialog_content = "Dari tadi aku mau menanyakannya... Mana daftar staf, buku besar, dan buku catatan harta milik punyamu?",
  ui_story_5026_50260301_130_dialog_content = "Hah? Apa itu?",
  ui_story_5026_50260301_131_dialog_content = "Kau bahkan tak tahu daftar staf?",
  ui_story_5026_50260301_132_dialog_content = "Rasanya aku bakal menghina kecerdasanmu kalau kujelaskan, tapi biar kumulai dari bagian dasarnya.",
  ui_story_5026_50260301_133_dialog_content = "Sebentar, rasanya ada yang mendekat... Itu—",
  ui_story_5026_50260301_134_dialog_content = "Waaaah!",
  ui_story_5026_50260301_135_dialog_content = "A-apa lagi sekarang?!",
  ui_story_5026_50260301_136_dialog_content = "<anim type=Shake>Graagh!</anim>",
  ui_story_5026_50260301_137_dialog_content = "A-aku baru saja menyentuh semak-semak...",
  ui_story_5026_50260301_138_dialog_content = "Kau \"menyentuh\" dengan sekuat tenaga, ya?!",
  ui_story_5026_50260402_1_dialog_content = "<anim type=Shake>Gaah...</anim>",
  ui_story_5026_50260402_2_dialog_content = "Huh. Gampang sekali.",
  ui_story_5026_50260402_3_dialog_content = "Sanae, PlayerName, kalian baik-baik saja?",
  ui_story_5026_50260402_4_dialog_content = "M-mereka tiba-tiba melompat keluar dari semak-semak dan menakutiku.",
  ui_story_5026_50260402_5_dialog_content = "Wah, ini kejutan. Ternyata Nina bisa bertarung.",
  ui_story_5026_50260402_6_dialog_content = "Huh, kau baru tahu rupanya.",
  ui_story_5026_50260402_7_dialog_content = "Kemampuan psikismu juga sangat spesial. Kau bisa melihat jejak cahaya karenanya. Aku jadi punya inspirasi untuk membuat desain baru.",
  ui_story_5026_50260402_8_dialog_content = "Sebentar... Maksudmu apa bilang \"kejutan\"? Kau meremehkanku, ya?",
  ui_story_5026_50260402_9_dialog_content = "Habis kau tak kelihatan seperti orang yang sering mengayunkan senjata, sih...",
  ui_story_5026_50260402_10_dialog_content = "Tapi, kau memang benar. Maafkan aku. Seharusnya aku tak langsung menilaimu berdasarkan kesan pertama.",
  ui_story_5026_50260402_11_dialog_content = "Berkat bantuanmu, musuh bisa dikalahkan. Area ini sudah bebas dari Darkflow.",
  ui_story_5026_50260402_12_dialog_content = "Terima kasih, Nina.",
  ui_story_5026_50260402_13_dialog_content = "T-tak perlu bersikap serius begitu, dan...",
  ui_story_5026_50260402_14_dialog_content = "Tak perlu dekat-dekat juga!",
  ui_story_5026_50260402_15_dialog_content = "(Justru kau yang dekat-dekat duluan!)",
  ui_story_5026_50260402_16_dialog_content = "<size=33>Ini orang yang Istvan awasi dengan cermat... Aku tak boleh lengah.</size>",
  ui_story_5026_50260402_17_dialog_content = "Kau benar. Sebagai seorang wanita bangsawan...",
  ui_story_5026_50260402_18_dialog_content = "... Eh, mereka bilang apa, ya? Oh, iya, sebagai seorang wanita bangsawan, aku harus \"lebih elegan dan bermartabat\" dan tak boleh \"berjalan sambil membawa senjata\".",
  ui_story_5026_50260402_19_dialog_content = "Apalagi aku lebih suka membuat senjata ketimbang menentengnya.",
  ui_story_5026_50260402_20_dialog_content = "Aku jadi penasaran bagaimana pendapat para wanita bangsawan itu kalau mereka sampai tahu soal ini.",
  ui_story_5026_50260402_21_dialog_content = "Wanita bangsawan?",
  ui_story_5026_50260402_22_dialog_content = "B-bukan apa-apa! Menyingkirkan Eclipsite kan termasuk pekerjaanku. Aku hanya melakukan tugasku, kok!",
  ui_story_5026_50260402_23_dialog_content = "Selain itu, ini hanya langkah pertama dalam penataan ulang Cloud Gardens—tunggu dan lihat saja aksi-aksiku yang hebat!",
  ui_story_5026_50260402_24_dialog_content = "Oh, iya. Omong-omong soal itu...",
  ui_story_5026_50260402_25_dialog_content = "Sepertinya Minos sudah selesai menanam saat kita membicarakan perbedaan Chubb.",
  ui_story_5026_50260402_26_dialog_content = "Hah?",
  ui_story_5026_50260402_27_dialog_content = "Dia menggemburkan tanah, menabur benih, menyiramnya, dan memupuknya...",
  ui_story_5026_50260402_28_dialog_content = "Dia juga memasang penanda untuk setiap bidang tanah, dan mengelilinginya dengan bunga yang melengkapi warna pohon.",
  ui_story_5026_50260402_29_dialog_content = "Seperti yang kulihat, Chubb!",
  ui_story_5026_50260402_30_dialog_content = "Bagus sekali, Chubb!",
  ui_story_5026_50260402_31_dialog_content = "Kau baik sekali, Navigator... dan para Chubb kecil yang manis.",
  ui_story_5026_50260402_32_dialog_content = "Kuingatkan kau, Master dari Cloud Gardens, terlalu dini kalau merasa tenang soal masalah Eclipsite.",
  ui_story_5026_50260402_33_dialog_content = "Barusan aku melihat bayangan gelap yang kuduga adalah Eclipsite yang berlari ke dalam bangunan-bangunan di kejauhan.",
  ui_story_5026_50260402_34_dialog_content = "Aku mau pergi memeriksanya dulu untuk berjaga-jaga. Permisi.",
  ui_story_5026_50260402_35_dialog_content = "Wow, cepat sekali perginya!",
  ui_story_5026_50260402_36_dialog_content = "Aku kalah satu babak. Aku tak boleh tertinggal lagi.",
  ui_story_5026_50260402_37_dialog_content = "Sanae, ayo!",
  ui_story_5026_50260402_38_dialog_content = "Memangnya kita punya peluang menang dari Minos...?",
  ui_story_5026_50260402_39_dialog_content = "Dibandingkan aku, rasanya mereka justru lebih mengkhawatirkan keamanan Cloud Gardens...",
  ui_story_5026_50260402_40_dialog_content = "Apa memang begini ya semangat kerja kontrak orang-orang Umbraton?",
  ui_story_5026_50260501_1_dialog_content = "Apa? Tak ada Eclipsite di mana pun!",
  ui_story_5026_50260501_2_dialog_content = "Apa Minos sudah membereskannya?",
  ui_story_5026_50260501_3_dialog_content = "Aku juga tidak merasakan Darkflow. Tapi, jangan sampai lengah.",
  ui_story_5026_50260501_4_dialog_content = "Setidaknya area terbuka di depan ini aman.",
  ui_story_5026_50260501_5_dialog_content = "Kelihatannya tempat ini tidak asing...",
  ui_story_5026_50260501_6_dialog_content = "Jelas sekali. Tak peduli ke arah mana pun kau melihat, tempat ini hanya lapangan berumput yang sama yang membentang ke luar.",
  ui_story_5026_50260501_7_dialog_content = "Oh, benar juga! Aku pernah berburu harta karun di dekat sini dengan Vice!",
  ui_story_5026_50260501_8_dialog_content = "Kudengar penduduk di daerah terpencil juga suka melakukan itu untuk menarik minat petualang yang bermimpi bisa mendapat kekayaan dengan mudah.",
  ui_story_5026_50260501_9_dialog_content = "Itu memang bukan cara yang buruk untuk menghidupkan lagi ekonomi setempat sih, tapi...",
  ui_story_5026_50260501_10_dialog_content = "Ini kelihatan seperti lapangan kosong. Memangnya ada benda berharga yang terkubur di dalamnya?",
  ui_story_5026_50260501_11_dialog_content = "Aduh… yah…",
  ui_story_5026_50260501_12_dialog_content = "<size=45>Waaah!</size>",
  ui_story_5026_50260501_13_dialog_content = "H-hah?!",
  ui_story_5026_50260501_14_dialog_content = "Aku tersandung... batu?",
  ui_story_5026_50260501_15_dialog_content = "Harta karunnya ketemu! Chubb!",
  ui_story_5026_50260501_16_dialog_content = "Oooh, gila... Sepertinya satu Chubb berubah menjadi beberapa Chubb.",
  ui_story_5026_50260501_17_dialog_content = "Benar-benar ada banyak Chubb, Chubb!",
  ui_story_5026_50260501_18_dialog_content = "Aduh, aduh, minggir sana! Chubb!",
  ui_story_5026_50260501_19_dialog_content = "Aku terimpit, Chubb...",
  ui_story_5026_50260501_20_dialog_content = "Kelihatannya Sanae selalu sial, ya. Dia itu kena sial atau justru beruntung...?",
  ui_story_5026_50260501_21_dialog_content = "Nina? Ada apa? Kau juga mau menggali?",
  ui_story_5026_50260501_22_dialog_content = "Aku tidak mau.",
  ui_story_5026_50260501_23_dialog_content = "Kotor sekali, gaunku bakal kena noda. Gaun ini adalah gaun buatanku yang paling baru…",
  ui_story_5026_50260501_24_dialog_content = "(Dia terus menatap alat di tanganku...)",
  ui_story_5026_50260501_25_dialog_content = "Ayo kita coba. Kau boleh pinjam ini.",
  ui_story_5026_50260501_26_dialog_content = "Eh... Karena kau bersikeras, dan ini juga bagian dari pekerjaan sehari-hari di Cloud Gardens, biar kucoba.",
  ui_story_5026_50260501_27_dialog_content = "Tapi, coba gerakkan dengan lebih cepat.",
  ui_story_5026_50260501_28_dialog_content = "Lihatlah. Entah sejak kapan dia melakukannya, tapi Minos sudah mendapat setumpuk panenan di dekat kakinya.",
  ui_story_5026_50260501_29_dialog_content = "Bahkan Chubb tampak terkagum-kagum.",
  ui_story_5026_50260501_30_dialog_content = "(Hah? Sebentar...)",
  ui_story_5026_50260501_31_dialog_content = "(Apa mereka pernah melompat-lompat di sekitarku dengan semangat dan bahagia seperti itu sebelumnya?)",
  ui_story_5026_50260501_32_dialog_content = "Aku tidak kaget, sih. Dia memang sangat cakap dalam segala hal... Ini tidak adil!",
  ui_story_5026_50260501_33_dialog_content = "Oh, dia pakai metode apa, ya? Tadi aku malah keasyikan melihat Sanae sampai-sampai tidak memperhatikan proses pengumpulannya...",
  ui_story_5026_50260501_34_dialog_content = "Hei, apa ada alat-alat yang lebih praktis untuk berburu harta karun?",
  ui_story_5026_50260501_35_dialog_content = "Ada beberapa alat lain sih di dekat kincir angin di sebelah sana.",
  ui_story_5026_50260501_36_dialog_content = "Sebentar, sepertinya alat-alatnya ditaruh di gudang sebelah kincir angin... Tapi, gudang itu sudah lama tidak dibersihkan.",
  ui_story_5026_50260501_37_dialog_content = "Cih. Kok bisa?",
  ui_story_5026_50260501_38_dialog_content = "Sebagai penguasa Cloud Gardens, seharusnya kau memahami wilayahmu sendiri!",
  ui_story_5026_50260501_39_dialog_content = "Biar kuperiksa sendiri.",
  ui_story_5026_50260501_40_dialog_content = "Ah, Nina! Tunggu aku!",
  ui_story_5026_50260501_41_dialog_content = "<color=#e8d9bb>Cloud Gardens: Ruang Peralatan</color>",
  ui_story_5026_50260501_42_dialog_content = "Aduh! Tempat ini berdebu sekali!",
  ui_story_5026_50260501_43_dialog_content = "Ada banyak perabot yang baru disusun setengah jadi. Ini karya Caelestite itu, ya?",
  ui_story_5026_50260501_44_dialog_content = "Tak kusangka PlayerName itu pekerja keras.",
  ui_story_5026_50260501_45_dialog_content = "Kelangkaannya justru bisa membuatnya jadi berharga. Kalau barang-barang ini dinamai \"karya seni Caelestite\" lalu dikirim ke rumah lelang di Umbraton, mungkin bisa terjual dengan harga tinggi.",
  ui_story_5026_50260501_46_dialog_content = "Benda-benda itu bisa dikemas dengan baik, dan bahkan dipajang di pameran...",
  ui_story_5026_50260501_47_dialog_content = "Tidak. Sekarang bukan waktunya memikirkan hal itu.",
  ui_story_5026_50260501_48_dialog_content = "Alat-alat... Mana alat-alatnya? Cahayanya terlalu redup...",
  ui_story_5026_50260501_49_dialog_content = "<color=#e8d9bb>Wuush…</color>",
  ui_story_5026_50260501_50_dialog_content = "<size=45>Hah? Oh!</size>",
  ui_story_5026_50260501_51_dialog_content = "Hanya angin. Sudah kuduga...",
  ui_story_5026_50260501_52_dialog_content = "<color=#e8d9bb>Pranggg...</color>",
  ui_story_5026_50260501_53_dialog_content = "<size=45>Aah?!</size>",
  ui_story_5026_50260501_54_dialog_content = "Itu... itu pasti Chubb yang sembunyi di balik perabot...",
  ui_story_5026_50260501_55_dialog_content = "Jangan sembunyi di tempat gelap, dong... Keluarlah!",
  ui_story_5026_50260501_56_dialog_content = "Aku sama sekali tidak takut. Sedikit pun tidak...",
  ui_story_5026_50260501_57_dialog_content = "<size=45>Aaaaah!</size>",
  ui_story_5026_50260501_58_dialog_content = "<anim type=Shake><size=50>Graaagh!</size></anim>",
  ui_story_5026_50260501_59_dialog_content = "Oh... Rupanya bukan hantu...",
  ui_story_5026_50260501_60_dialog_content = "Berani-beraninya Eclipsite membuatku takut!",
  ui_story_5026_50260502_1_dialog_content = "Kau baik-baik saja, Nina?",
  ui_story_5026_50260502_2_dialog_content = "Tadi aku dengar ada yang menjerit.",
  ui_story_5026_50260502_3_dialog_content = "K-kau salah dengar! G-gudang ini tidak gelap dan tidak menyeramkan, kok!",
  ui_story_5026_50260502_4_dialog_content = "Tadi ada beberapa Eclipsite. Mereka langsung kalah hanya dengan beberapa kali pukul!",
  ui_story_5026_50260502_5_dialog_content = "Syukurlah kalau kau baik-baik saja. Alatnya sudah ketemu?",
  ui_story_5026_50260502_6_dialog_content = "Saat kau sibuk mencari alat tadi, Minos... melakukan perubahan drastis pada tempat ini.",
  ui_story_5026_50260502_7_dialog_content = "Huuuh?",
  ui_story_5026_50260502_8_dialog_content = "Sekarang dia sedang bersama Chubb, memperbaiki rumput agar jadi seperti semula. Dia sudah menyiraminya, dan bahkan menghitung jumlah cacing tanahnya...",
  ui_story_5026_50260502_9_dialog_content = "Begitu, ya. Rupanya begini kalau bersaing dengan Minos.",
  ui_story_5026_50260502_10_dialog_content = "Memperdayaku agar aku mau makan lebih banyak sayur dan mencegahku agar tidak mengerjai guruku adalah urusan sepele baginya.",
  ui_story_5026_50260502_11_dialog_content = "Kau dan Minos sudah lama saling kenal, ya?",
  ui_story_5026_50260502_12_dialog_content = "Ya, benar. Aku pun sudah lama menoleransi kelakuannya.",
  ui_story_5026_50260502_13_dialog_content = "Aku sudah muak diperlakukan seperti anak kecil oleh dia dan ayahku.",
  ui_story_5026_50260502_14_dialog_content = "Baiklah, kita lanjut ke ujian berikutnya!",
  ui_story_5026_50260502_15_dialog_content = "Gagal tiga kali. Aku tak akan kalah dari Minos lagi.",
  ui_story_5026_50260502_16_dialog_content = "Berikutnya, ayo kita cari bijih.",
  ui_story_5026_50260502_17_dialog_content = "Huh... Memangnya kita bisa menemukan bijih lokal yang spesial di Cloud Gardens ini?",
  ui_story_5026_50260502_18_dialog_content = "Keluargaku—maksudku, rekan bisnisku, keluarga Andersen, menangani setengah dari mineral Umbraton.",
  ui_story_5026_50260502_19_dialog_content = "Jika saya dapat menemukan deposit bijih langka di sini, saya yakin itu akan membuat kepala keluarga terkesan, bukan?",
  ui_story_5026_50260502_20_dialog_content = "Setengah dari seluruh mineral? Wow, keluarga Andersen memang bukan keluarga sembarangan, ya.",
  ui_story_5026_50260502_21_dialog_content = "Mana kutahu? Hubunganku dengan mereka hanya sebatas urusan bisnis!",
  ui_story_5026_50260502_22_dialog_content = "Aku hanya peduli dengan cara penggunaan mineralnya, terutama permata.",
  ui_story_5026_50260502_23_dialog_content = "Memilih, menaksir harganya, mengirimnya untuk dipotong, mengatur—",
  ui_story_5026_50260502_24_dialog_content = "Sesuai desainku, membuat setiap permata menjadi bagian yang indah dari senjata, perhiasan, atau pakaian.",
  ui_story_5026_50260502_25_dialog_content = "Kau bisa mendesain banyak barang? Kau memang hebat, Nina.",
  ui_story_5026_50260502_26_dialog_content = "Heheh, desainku sangat populer di Umbraton, lho...",
  ui_story_5026_50260502_27_dialog_content = "...",
  ui_story_5026_50260502_28_dialog_content = "<size=33>... Tapi, belakang ini aku tahu bahwa kepopuleran ini mungkin tak hanya berasal dari kemampuanku sendiri.</size>",
  ui_story_5026_50260502_29_dialog_content = "Kok bisa?",
  ui_story_5026_50260502_30_dialog_content = "Eh, bukan apa-apa. Tadi aku melihat banyak perabot di gudang. Kau yang membuatnya?",
  ui_story_5026_50260502_31_dialog_content = "Iya. Aku hanya amatir, kok. Tapi, akhir-akhir ini aku menikmati pembuatan perabot dan konstruksi bangunan.",
  ui_story_5026_50260502_32_dialog_content = "Oh, ya? Jadi, semua perabot dan struktur yang kulihat di Cloud Gardens adalah desainmu?",
  ui_story_5026_50260502_33_dialog_content = "Ah... Aku hanya memperbaiki struktur Caelestite dari cetak biru yang kutemukan di berbagai tempat di Cloud Gardens.",
  ui_story_5026_50260502_34_dialog_content = "Memangnya apa serunya menyalin desain asli dari masa lalu?",
  ui_story_5026_50260502_35_dialog_content = "Nah, kalau dipikir-pikir, aku juga...",
  ui_story_5026_50260502_36_dialog_content = "Aku sudah lancang.",
  ui_story_5026_50260502_37_dialog_content = "Hah?",
  ui_story_5026_50260502_38_dialog_content = "Kau pasti punya alasan sendiri. Seharusnya aku tak mencelamu.",
  ui_story_5026_50260502_39_dialog_content = "Tidak.",
  ui_story_5026_50260502_40_dialog_content = "Gara-gara pertanyaanmu tadi, untuk pertama kalinya aku jadi serius berpikir kenapa memperbaiki barang membuatku gembira.",
  ui_story_5026_50260502_41_dialog_content = "Kenapa?",
  ui_story_5026_50260502_42_dialog_content = "Rasanya, dengan cara ini aku jadi bisa menciptakan kembali pemandangan yang hancur akibat dimakan usia dan perang...",
  ui_story_5026_50260502_43_dialog_content = "Selain itu, rasanya seperti ini akan mengusir kesepian.",
  ui_story_5026_50260502_44_dialog_content = "... Kau tak seperti dugaanku, PlayerName.",
  ui_story_5026_50260502_45_dialog_content = "Apa?",
  ui_story_5026_50260502_46_dialog_content = "Sanae sering membicarakan artikel di Umbraton Daily yang diklaim menggambarkan kehidupan PlayerName, si Caelestite, secara akurat.",
  ui_story_5026_50260502_47_dialog_content = "Ayah bilang omong kosong di halaman koran itu lebih banyak daripada barang palsu di Nightmist Market.",
  ui_story_5026_50260502_48_dialog_content = "Hah? Ada orang yang menulis artikel tentang aku?",
  ui_story_5026_50260502_49_dialog_content = "Akui saja, sekarang kau kan jadi pusat perhatian.",
  ui_story_5026_50260502_50_dialog_content = "Aku ingat judul artikel pertamanya. Judulnya: Mengejutkan! Remaja Hidup Lagi Setelah Terkubur 17 Tahun!",
  ui_story_5026_50260502_51_dialog_content = "Kalau kau tertarik, aku ingat Sanae selalu menyimpan kliping artikel setiap minggu dan membuat buku tempel...",
  ui_story_5026_50260502_52_dialog_content = "Dia juga membeli buku yang merupakan publikasi kumpulan semua artikel itu dalam satu volume.",
  ui_story_5026_50260502_53_dialog_content = "... Katakan, bagaimana cara membuat mereka berhenti menulis?",
  ui_story_5026_50260502_54_dialog_content = "Menarik. Kau mau coba-coba menulis artikelnya sendiri?",
  ui_story_5026_50260502_55_dialog_content = "Yah, sebagai penguasa baru, mengelola citra juga hal penting.",
  ui_story_5026_50260502_56_dialog_content = "Tidak, aku hanya... sangat malu...",
  ui_story_5026_50260502_57_dialog_content = "Bagi para jurnalis tabloid, kau adalah primadona berita. Berhati-hatilah dan sembunyikan rahasiamu rapat-rapat.",
  ui_story_5026_50260502_58_dialog_content = "Aku akan berhati-hati…",
  ui_story_5026_50260502_59_dialog_content = "Aduh! Aku tak sadar kita malah keasyikan mengobrol dari tadi!",
  ui_story_5026_50260502_60_dialog_content = "Sanae dan Minos pasti masih menunggu. Sebaiknya kita pergi ke tempat bijih-bijih itu sekarang, ya?",
  ui_story_5026_50260502_61_dialog_content = "Semoga kita tak bakal bertemu dengan Eclipsite lagi dalam perjalanan ke sana.",
  ui_story_5026_50260702_1_dialog_content = "Oh, dari mana semua Eclipsite ini berasal?",
  ui_story_5026_50260702_2_dialog_content = "Apa yang membuatmu terkejut? Di benua ini, terus-terusan diganggu oleh Eclipsite adalah hal yang lazim.",
  ui_story_5026_50260702_3_dialog_content = "Sebelum ini, aku tinggal di Colossus. Aku tak punya pengalaman seperti ini...",
  ui_story_5026_50260702_4_dialog_content = "Yang seperti ini sudah jelas terjadi di ladang, hutan, dan peternakan di sekitar Umbraton. Bahkan para nelayan di sepanjang Gold River juga tahu.",
  ui_story_5026_50260702_5_dialog_content = "Kedamaian memang hal yang langka dan berharga.",
  ui_story_5026_50260702_6_dialog_content = "Di sini, kau tak bisa terbang atau sembunyi di bawah tanah. Perlindungan dari Aurorian yang kuat pun tak ada.",
  ui_story_5026_50260702_7_dialog_content = "Jadi, sebaliknya, aku tak tahu kenapa Cloud Gardens bisa bebas dari gangguan Eclipsite.",
  ui_story_5026_50260702_8_dialog_content = "Memangnya Caelestite dan Aurorian menangani Eclipsite dengan cara yang sangat berbeda, ya?",
  ui_story_5026_50260702_9_dialog_content = "(Pertanyaannya menohok sekali!)",
  ui_story_5026_50260702_10_dialog_content = "Katanya, Caelestite tak bisa bertarung dengan menggunakan Luminatics.",
  ui_story_5026_50260702_11_dialog_content = "Kau juga tak bisa memanipulasi alat Luminatics untuk melakukan pekerjaan fisik. Kau harus menggunakan kekuatanmu sendiri seperti yang kulakukan sekarang.",
  ui_story_5026_50260702_12_dialog_content = "Dari pengamatanku, kau perlu mengayunkan beliung tiga atau empat kali untuk memotong bijih...",
  ui_story_5026_50260702_13_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5026_50260702_14_dialog_content = "Ah! Kena, ya? Maaf!",
  ui_story_5026_50260702_15_dialog_content = "<anim type=Shake>Chubb...</anim>",
  ui_story_5026_50260702_16_dialog_content = "Hmm... Aku memang lumayan bisa menggunakan senjata, tapi butuh waktu untuk membiasakan diri dengan berat alatnya dan cara kerjanya...",
  ui_story_5026_50260702_17_dialog_content = "Kita sampai mana tadi, PlayerName?",
  ui_story_5026_50260702_18_dialog_content = "Oh, iya. Dari yang kupelajari, kemampuan Caelestite mungkin tak akan berguna sama sekali untuk mempertahankan wilayah...",
  ui_story_5026_50260702_19_dialog_content = "Caelestite bisa mengomando Aurorian untuk bertarung dengan efisien, jadi apa leluhurmu mempekerjakan Aurorian sebagai penjaga?",
  ui_story_5026_50260702_20_dialog_content = "Kalau dulu sering terjadi komunikasi antara kedua ras, seharusnya ada lebih banyak informasi di perpustakaan Ayah yang—",
  ui_story_5026_50260702_21_dialog_content = "<size=45>Waah!</size>",
  ui_story_5026_50260702_22_dialog_content = "A-apa yang terjadi? Mereka bergabung karena ingin membalas dendam teman mereka?",
  ui_story_5026_50260702_23_option_content = "Sepertinya tidak.",
  ui_story_5026_50260702_24_option_content = "Boleh kucoba merasakannya?",
  ui_story_5026_50260702_25_dialog_content = "(Omong-omong, aku tak pernah memikirkan pendapat Chubb.)",
  ui_story_5026_50260702_26_dialog_content = "Tolong Chubb!",
  ui_story_5026_50260702_27_dialog_content = "Kalian... Kalian membantuku menyortir bijih yang kami tambang?",
  ui_story_5026_50260702_28_dialog_content = "Chubb!",
  ui_story_5026_50260702_29_dialog_content = "Baiklah, simpan yang ini. Ini pasti bijih besi, bisa digunakan untuk membuat peralatan.",
  ui_story_5026_50260702_30_dialog_content = "Ada kuarsa juga, tapi kualitasnya mungkin sedikit diragukan. Hanya bisa digunakan sebagai material konstruksi.",
  ui_story_5026_50260702_31_dialog_content = "Ah, itu mungkin permata langka! Hati-hati, ya!",
  ui_story_5026_50260702_32_dialog_content = "Baiklah, Chubb!",
  ui_story_5026_50260702_33_dialog_content = "Imutnya... Ehem... Maksudku, makhluk yang mengagumkan.",
  ui_story_5026_50260702_34_dialog_content = "Sepertinya keamanan dan produksi di Cloud Gardens menggunakan sistem yang unik.",
  ui_story_5026_50260702_35_dialog_content = "(Sistem yang unik? Aku malah belum pernah memikirkan hal ini sebelumnya.)",
  ui_story_5026_50260702_36_dialog_content = "(Kesan pertamaku tentang Nina... Dia naif, dan rencana penaklukannya juga tak begitu meyakinkan.)",
  ui_story_5026_50260702_37_dialog_content = "(Tapi, dia bisa diandalkan dalam masalah-masalah profesional!)",
  ui_story_5026_50260702_38_dialog_content = "(Sementara itu, aku... aku bahkan tak tahu banyak tentang tempat yang kusebut rumah ini.)",
  ui_story_5026_50260702_39_dialog_content = "(Justru aku yang sedang dalam masa percobaan, ya? Apa aku bakal lulus?)",
  ui_story_5026_50260702_40_dialog_content = "Sepertinya kau sangat tertarik pada mode operasi Cloud Gardens.",
  ui_story_5026_50260702_41_dialog_content = "Yah, lagi pula ini kan tempat dimulainya penaklukan dunia yang kurencanakan. Mempelajarinya sebanyak mungkin itu wajar, 'kan?",
  ui_story_5026_50260702_42_dialog_content = "Kelihatannya usia kita sebaya, tapi kau sangat hebat, ya.",
  ui_story_5026_50260702_43_dialog_content = "A-apa? Tak ada gunanya kau menyanjungku seperti itu.",
  ui_story_5026_50260702_44_dialog_content = "Berikutnya, saatnya menghitung bijih.",
  ui_story_5026_50260702_45_dialog_content = "Aku berhasil dapat banyak bijih. Kali ini aku pasti tak akan kalah dari Minos, 'kan?",
  ui_story_5026_50260702_46_dialog_content = "Bagus sekali, Chubb!",
  ui_story_5026_50260702_47_dialog_content = "Master juga hebat, Chubb!",
  ui_story_5026_50260702_48_dialog_content = "Master?",
  ui_story_5026_50260702_49_dialog_content = "Ada tumpukan yang lebih besar di sebelah tumpukan bijih yang Nina tambang. Ini yang Minos tambang?",
  ui_story_5026_50260702_50_dialog_content = "K-kapan kalian disuap oleh Minos?!",
  ui_story_5026_50260702_51_dialog_content = "Eh... Nona...",
  ui_story_5026_50260702_52_dialog_content = "Maksudku, Nina!",
  ui_story_5026_50260702_53_dialog_content = "Bagaimana kabarmu? Kami sepakat untuk mengonfirmasi arah lapisannya, tapi aku sudah tak sanggup menggali lagi. Lalu, aku...",
  ui_story_5026_50260702_54_dialog_content = "... Aku sangat lapar!",
  ui_story_5026_50260702_55_dialog_content = "Siapa yang bicara barusan?",
  ui_story_5026_50260702_56_dialog_content = "<size=45>Aaah! M-Manae!</size>",
  ui_story_5026_50260702_57_dialog_content = "Tak ada pekerjaan, tak ada makanan... Satu teguk minuman pun tak ada, padahal sudah menggali berjam-jam!",
  ui_story_5026_50260702_58_dialog_content = "Bahkan tambang tempat kita bekerja sebelumnya, yang kita datangi di tengah malam tanpa izin Shadowlord, tak terlalu eksploitatif!",
  ui_story_5026_50260702_59_dialog_content = "Manae! Shh!",
  ui_story_5026_50260702_60_dialog_content = "Maaf! Tak terpikir olehku sebelumnya. Biar kuambilkan minuman untukmu!",
  ui_story_5026_50260702_61_dialog_content = "(Hah? Memangnya boneka juga butuh minum?)",
  ui_story_5026_50260702_62_dialog_content = "(Auranya membuatku kewalahan. Aku sampai meminta maaf kepada boneka itu tanpa sadar...)",
  ui_story_5026_50260702_63_dialog_content = "(Tidak, tidak, tidak. Yang lebih penting...)",
  ui_story_5026_50260702_64_dialog_content = "<size=45>Boneka itu bisa bicara?!</size>",
  ui_story_5026_50260702_65_dialog_content = "Apa saking lelahnya aku sampai berhalusinasi, ya?",
  ui_story_5026_50260702_66_dialog_content = "Bagaimana kalau kita istirahat dulu, Navigator?",
  ui_story_5026_50260702_67_dialog_content = "Semuanya, duduklah di sini.",
  ui_story_5026_50260702_68_dialog_content = "Dari mana asal meja dan kursi ini?",
  ui_story_5026_50260702_69_dialog_content = "Lalu, dari mana camilan ini?",
  ui_story_5026_50260702_70_dialog_content = "Tadi aku meminjam dapurmu dengan bantuan Chubb. Kau suka camilannya?",
  ui_story_5026_50260702_71_dialog_content = "Lezat sekali...",
  ui_story_5026_50260702_72_dialog_content = "(Wah, sudah kuduga. Makanan tak enak yang ada di Cloud Gardens bukan gara-gara dapurnya.)",
  ui_story_5026_50260702_73_dialog_content = "Navigator, kau tadi ketakutan gara-gara aku, ya?",
  ui_story_5026_50260702_74_dialog_content = "Boneka ini bernama Manae. Sesekali dia bakal bicara sendiri dan mengatakan hal-hal yang kurang enak didengar.",
  ui_story_5026_50260702_75_dialog_content = "Aku tahu dia hanya menjagaku, tapi...",
  ui_story_5026_50260702_76_dialog_content = "Sanae, tehnya tumpah.",
  ui_story_5026_50260702_77_dialog_content = "<size=45>M-maaf!</size>",
  ui_story_5026_50260702_78_dialog_content = "Dua butir gula, diaduk sepuluh kali searah jarum jam dan tiga kali berlawanan arah jarum jam. Silakan, Nona Nina.",
  ui_story_5026_50260702_79_dialog_content = "Ya.",
  ui_story_5026_50260702_80_dialog_content = "(Sepertinya Nina terbiasa dengan ini...)",
  ui_story_5026_50260702_81_dialog_content = "(Benarkah tak apa-apa kalau aku bersantai-santai seperti ini padahal ada Eclipsite keluyuran di seluruh Cloud Gardens?)",
  ui_story_5026_50260702_82_dialog_content = "(Tapi, ini toh bukan masalah yang bisa diselesaikan dengan tergesa-gesa.)",
  ui_story_5026_50260702_83_dialog_content = "(Seperti pertanyaan Nina tadi, bagaimana cara Caelestite mempertahankan diri dari musuh di masa lalu?)",
  ui_story_5026_50260702_84_dialog_content = "(Jelas mustahil kalau mempekerjakan Aurorian sebagai pengawal.)",
  ui_story_5026_50260702_85_dialog_content = "(Kalau dulu satu-satunya cara bertahan di sini adalah dengan menggunakan Obelisk of Return, apa yang harus kulakukan kalau menaranya tidak aktif?)",
  ui_story_5026_50260702_86_dialog_content = "(Bahkan kalau ada senjata lain yang ditinggalkan oleh kaum Caelestite kuno, bisakah musuh mereka—)",
  ui_story_5026_50260702_87_dialog_content = "Apa yang kaupikirkan?",
  ui_story_5026_50260702_88_dialog_content = "B-bukan apa-apa!",
  ui_story_5026_50260702_89_dialog_content = "Waktu minum teh adalah waktu yang sakral, jadi tak boleh sampai terganggu. Jangan pikirkan hal-hal yang tak penting.",
  ui_story_5026_50260702_90_dialog_content = "Bersantai sesekali juga perlu.",
  ui_story_5026_50260702_91_dialog_content = "Tapi, kalau kau punya unek-unek tentang pekerjaan kami sejauh ini, bilang saja.",
  ui_story_5026_50260702_92_dialog_content = "Bukan unek-unek sih, tapi ada sesuatu yang membuatku penasaran.",
  ui_story_5026_50260702_93_dialog_content = "Kalian bertiga punya hubungan apa dan kenapa kalian melamar posisi manajer di Cloud Gardens?",
  ui_story_5026_50260702_94_dialog_content = "Sepertinya kau tidak terampil dalam pekerjaan tangan.",
  ui_story_5026_50260702_95_dialog_content = "K-kau tahu!?",
  ui_story_5026_50260702_96_dialog_content = "Sanae juga tidak mengerjakan tugas-tugas rumah tangga dengan teliti.",
  ui_story_5026_50260702_97_dialog_content = "T-tapi, aku... <size=45>Ahhhh! Cangkirnya!</size>",
  ui_story_5026_50260702_98_dialog_content = "Sebaliknya, Minos... mengerjakan semuanya tanpa cela. Kau tentu bisa menemukan pekerjaan yang lebih baik.",
  ui_story_5026_50260702_99_dialog_content = "Terima kasih atas pujianmu, tapi aku hanya pelayan biasa.",
  ui_story_5026_50260702_100_dialog_content = "Jangan salah paham. Aku bukannya mengkritik kalian semua!",
  ui_story_5026_50260702_101_dialog_content = "Juga, kalian pasti punya alasan untuk menyembunyikan sesuatu.",
  ui_story_5026_50260702_102_dialog_content = "Tanpa kalian, aku tak mungkin bisa menangani Eclipsite sebanyak itu.",
  ui_story_5026_50260702_103_dialog_content = "Berkat kalian, aku jadi menyadari bahwa ada banyak yang harus diperbaiki di Cloud Gardens.",
  ui_story_5026_50260702_104_dialog_content = "Minos menyebutku Master dari Cloud Gardens, dan Chubb juga memanggilku Master...",
  ui_story_5026_50260702_105_dialog_content = "Tapi, memangnya aku benar-benar pantas menyandang gelar ini?",
  ui_story_5026_50260702_105X1_dialog_content = "Daripada buang-buang waktu untuk meragukan diri, sebaiknya kau pikirkan apa yang bisa kau lakukan agar pantas menyandang gelar itu.",
  ui_story_5026_50260702_105X2_dialog_content = "Setidaknya, itu yang akan kulakukan.",
  ui_story_5026_50260702_105X3_dialog_content = "Tapi, kebalikan dari saranku, yang lebih kau butuhkan sekarang adalah…",
  ui_story_5026_50260702_106_dialog_content = "...",
  ui_story_5026_50260702_107_dialog_content = "PlayerName, apa ada hal lain yang kauinginkan di Cloud Gardens?",
  ui_story_5026_50260702_108_dialog_content = "Kalau sedang ingin menyendiri, aku bakal pergi memancing.",
  ui_story_5026_50260702_109_dialog_content = "Tapi, terakhir kali, aku malah bertemu dengan Eclipsite dalam perjalanan...",
  ui_story_5026_50260702_110_dialog_content = "Kenapa kau tanya...?",
  ui_story_5026_50260702_110X1_dialog_content = "I-ini bukan karena aku ingin kau bersantai atau semacamnya, lho!",
  ui_story_5026_50260702_111_dialog_content = "Mengetahui hobi rekan bisnisku juga bagian dari pekerjaan!",
  ui_story_5026_50260702_112_dialog_content = "Nah, karena kau sudah menyadarinya, cepat habiskan tehnya lalu kita pergi.",
  ui_story_5026_50260801_1_dialog_content = "<color=#e8d9bb>Eraveil: Wilderness</color>",
  ui_story_5026_50260801_2_dialog_content = "Hmm... Aku masih agak khawatir.",
  ui_story_5026_50260801_3_dialog_content = "Aku kembali ke Umbraton untuk menanyakan tentang keluarga Andersen...",
  ui_story_5026_50260801_4_dialog_content = "Jadi, apa yang terjadi?",
  ui_story_5026_50260801_5_dialog_content = "Wah! Kita sampai di sungai dengan aman kali ini!",
  ui_story_5026_50260801_6_dialog_content = "Terakhir kali, para Eclipsite itu tiba-tiba muncul saat aku kemari untuk memancing. Entah apa yang akan terjadi kalau tidak ada Bethel.",
  ui_story_5026_50260801_7_dialog_content = "Aku mungkin akan tersengat sehelai rumput karena Spikepest Eclipsite mengacaukan tempat itu.",
  ui_story_5026_50260801_8_dialog_content = "Seberapa akrab kau dengan Bethel?",
  ui_story_5026_50260801_9_dialog_content = "Kami bertarung bersama dengan Luke dari White Flame Mercenaries dalam insiden Blue Lion Guild.",
  ui_story_5026_50260801_10_dialog_content = "Setelah itu, kami bertemu beberapa kali. Saat dia menyelamatkanku, sebenarnya dia datang mewakili Sheol dan Cloudrover Guild.",
  ui_story_5026_50260801_11_dialog_content = "Hmm... Begitu rupanya.",
  ui_story_5026_50260801_12_dialog_content = "Dia memang pedagang yang hebat. Dia berhasil mengelola guild Istvan dengan baik.",
  ui_story_5026_50260801_13_dialog_content = "Dulu, waktu di Dawn Academy, semua orang menyanjung-nyanjung Bethel.",
  ui_story_5026_50260801_14_dialog_content = "T-tak usah terlalu dipikirkan! Aku tidak peduli dengan hubungan kalian, kok!",
  ui_story_5026_50260801_15_dialog_content = "(Rupanya dia peduli, ya.)",
  ui_story_5026_50260801_16_dialog_content = "Tadi kau bilang, memancing adalah bagian dari keseharianmu di Cloud Gardens, 'kan?",
  ui_story_5026_50260801_17_dialog_content = "Kalau begitu, ini bukan kegiatan biasa.",
  ui_story_5026_50260801_18_dialog_content = "Satu kali. Satu kali saja, aku harus mengalahkan Minos.",
  ui_story_5026_50260801_19_dialog_content = "Tapi, hanya ada satu joran, dan Chubb sudah memberikannya kepada Minos.",
  ui_story_5026_50260801_20_dialog_content = "Apa?",
  ui_story_5026_50260801_21_dialog_content = "Begitulah. Memang agak merepotkan kalau tak ada joran.",
  ui_story_5026_50260801_22_dialog_content = "Kenapa dia sangat populer di kalangan Chubb, sih?",
  ui_story_5026_50260801_23_dialog_content = "Jadi, kau sangat peduli soal itu, ya...",
  ui_story_5026_50260801_24_dialog_content = "Agar adil, aku akan mengajarimu cara memancing tanpa joran.",
  ui_story_5026_50260801_25_dialog_content = "Di Far East, orang-orang menyebutku \"Goldfish Master\"!",
  ui_story_5026_50260801_26_dialog_content = "Meski saat itu aku tak punya peralatan memancing dan ikannya berbeda... Yang namanya ikan tetap ikan, 'kan?",
  ui_story_5026_50260801_27_dialog_content = "...",
  ui_story_5026_50260801_28_dialog_content = "Sanae, kau pernah bilang bahwa dulu kau terbiasa menangkap ikan di sungai saat masih kecil, 'kan? Mau mengajariku, tidak?",
  ui_story_5026_50260801_29_dialog_content = "(Dia mengabaikanku!)",
  ui_story_5026_50260801_30_dialog_content = "Ah... Ahahahaha! Sepertinya barusan aku melihat ikan di sebelah sana. Aku lihat dulu, ah!",
  ui_story_5026_50260801_31_dialog_content = "PlayerName pergi...",
  ui_story_5026_50260801_32_dialog_content = "Nona Nina... Menangkap ikan bukan pekerjaan yang pantas untukmu! Biar aku saja!",
  ui_story_5026_50260801_33_dialog_content = "Dulu, bisa menangkap ikan atau tidak adalah urusan hidup dan mati bagiku.",
  ui_story_5026_50260801_34_dialog_content = "Meskipun tidak sehebat PlayerName yang terkenal, aku tetap akan berusaha semampuku!",
  ui_story_5026_50260801_35_dialog_content = "Tadi kau memanggilku \"Nona Nina\" lagi, ya?",
  ui_story_5026_50260801_36_dialog_content = "Ah! Maaf!",
  ui_story_5026_50260801_37_dialog_content = "Aku tak peduli kalau penyamaranku terbongkar. Kalau aku tidak salah, PlayerName pun tak terlalu peduli soal itu.",
  ui_story_5026_50260801_38_dialog_content = "Dia tak pernah mendengar nama Count Andersen. Aku tahu itu.",
  ui_story_5026_50260801_39_dialog_content = "Ayah memang menguasai banyak wilayah di seantero Astra, tapi dia cuma pria tua bagi Caelestite.",
  ui_story_5026_50260801_40_dialog_content = "Entah bagaimana, aku jadi senang.",
  ui_story_5026_50260801_41_dialog_content = "N-Nina...",
  ui_story_5026_50260801_42_dialog_content = "Benar, Sanae. Di sini aku hanya Nina. Dan... menangkap ikan sepertinya mengasyikkan.",
  ui_story_5026_50260801_43_dialog_content = "Aku sering melihat orang-orang melakukannya di samping Gold River saat melewati tempat itu. Dari dulu aku mau mencobanya.",
  ui_story_5026_50260801_44_dialog_content = "Hmm... Nina... Rokmu agak kepanjangan untuk menangkap ikan.",
  ui_story_5026_50260801_45_dialog_content = "Tidak apa-apa. Biar kusingkap.",
  ui_story_5026_50260801_46_dialog_content = "Jelaskan saja cara mengunci target, biar Luminatics yang mengurus sisanya.",
  ui_story_5026_50260801_47_dialog_content = "Aduh! Dingin sekali airnya!",
  ui_story_5026_50260801_48_dialog_content = "Batu-batu di dalam sungai ini licin. Hati-hati saat melangkah!",
  ui_story_5026_50260801_49_dialog_content = "Kalau Tuan Minos ada di sini, mungkin dia bakal mengingatkanmu tentang statusmu dan memintamu untuk bersikap elegan.",
  ui_story_5026_50260801_50_dialog_content = "Tapi, sekarang dia sedang sibuk dengan hal lain.",
  ui_story_5026_50260801_51_dialog_content = "Sini, biar kuajari kau cara menangkap ikan.",
  ui_story_5026_50260801_52_dialog_content = "Pertama, berdiri diam di dalam air, sama seperti saat kakimu berdiri di tepi sungai.",
  ui_story_5026_50260801_53_dialog_content = "Amati gerakan ikan, lalu pilih targetmu.",
  ui_story_5026_50260801_54_dialog_content = "Eh! Ada Globefish di sebelah sana. Rasanya lezat kalau dikukus!",
  ui_story_5026_50260801_55_dialog_content = "Knifefish terasa enak kalau dibakar...",
  ui_story_5026_50260801_56_dialog_content = "<size=45>Heheh... Hahahahah!</size>",
  ui_story_5026_50260801_57_dialog_content = "A-apa? Oh, maaf! Barusan aku makan camilan, dan sekarang aku...",
  ui_story_5026_50260801_58_dialog_content = "Tidak apa-apa. Aku hanya berpikir, seperti inilah dirimu.",
  ui_story_5026_50260801_59_dialog_content = "Kau jadi agak cerewet kalau sudah membahas sesuatu yang kau sukai.",
  ui_story_5026_50260801_60_dialog_content = "Benar... Menurutmu aneh, ya?",
  ui_story_5026_50260801_61_dialog_content = "Justru sebaliknya. Menurutku malah lucu.",
  ui_story_5026_50260801_62_dialog_content = "Hmm... T-tadi sampai mana, ya?",
  ui_story_5026_50260801_63_dialog_content = "Amati ikan dan pilih target.",
  ui_story_5026_50260801_64_dialog_content = "Oh, iya! Nah, sekarang tangkap ikannya saat ia lengah...",
  ui_story_5026_50260801_65_dialog_content = "<size=45>Sekarang!</size>",
  ui_story_5026_50260801_66_dialog_content = "Kena, deh!",
  ui_story_5026_50260801_67_dialog_content = "Luar biasa!",
  ui_story_5026_50260801_68_dialog_content = "Hehe…",
  ui_story_5026_50260801_69_dialog_content = "Biar kucoba... Wah! Licin sekali!",
  ui_story_5026_50260801_70_dialog_content = "Ikannya kabur...",
  ui_story_5026_50260801_71_dialog_content = "Jadi, begini ya cara Goldfish Master yang hebat menangkap ikan, PlayerName? Aku sampai tak bisa berkata-kata.",
  ui_story_5026_50260801_72_dialog_content = "Huh! Bagaimana kalau kau coba sendiri?",
  ui_story_5026_50260801_73_dialog_content = "Ha! Lihat, nih!",
  ui_story_5026_50260801_74_dialog_content = "Nona Nina benar-benar gembira.",
  ui_story_5026_50260801_75_dialog_content = "Hah? Tadinya kukira kau menangkap ikan dengan Nina, PlayerName?",
  ui_story_5026_50260801_76_dialog_content = "Dia bersenang-senang dengan Sanae, jadi kutinggalkan mereka berdua.",
  ui_story_5026_50260801_77_dialog_content = "Kenapa kau kembali? Eh, Sheol menolak permintaanku untuk menunda pembayaran, ya?",
  ui_story_5026_50260801_78_dialog_content = "Tidak, dia tak keberatan, tapi...",
  ui_story_5026_50260801_79_dialog_content = "Tuan Minos, apa benar Count Andersen tidak mau menerima tamu karena sedang sakit?",
  ui_story_5026_50260801_80_dialog_content = "Sepertinya kau sudah mendengarnya, Lady Bethel.",
  ui_story_5026_50260801_81_dialog_content = "...",
  ui_story_5026_50260801_82_dialog_content = "(Apa Minos sedang mengevaluasiku? Atau aku hanya salah paham?)",
  ui_story_5026_50260801_83_dialog_content = "Sebenarnya, itu terjadi setelah Nona Nina kabur dari rumah dan berkata \"Aku benci Ayah!\"...",
  ui_story_5026_50260801_84_dialog_content = "Tuan membatalkan semua pertemuan dan mengurung diri di dalam kamar.",
  ui_story_5026_50260801_85_dialog_content = "Sebentar. Kalau begitu, siapa yang menangani semua urusan properti dan wilayah mereka?",
  ui_story_5026_50260801_86_dialog_content = "Terima kasih sudah mencemaskannya, Lady Bethel.",
  ui_story_5026_50260801_87_dialog_content = "Tapi, bagiku tak ada urusan yang lebih penting ketimbang mereka berdua.",
  ui_story_5026_50260801_88_dialog_content = "Ayah! Ayah mengutus orang untuk membeli semua dagangan di tokoku?",
  ui_story_5026_50260801_89_dialog_content = "Nina, Sayang, apa maksudmu?",
  ui_story_5026_50260801_90_dialog_content = "Ayah membeli semua barang daganganku di toko agar barang-barang itu seolah-olah tampak laris, 'kan?",
  ui_story_5026_50260801_91_dialog_content = "P-padahal kukira desainku benar-benar bagus... tapi sekarang...",
  ui_story_5026_50260801_92_dialog_content = "Oh, Sayang... Jangan sedih!",
  ui_story_5026_50260801_93_dialog_content = "Ini salah Ayah! Ayah hanya ingin memberimu segalanya, yang terbaik!",
  ui_story_5026_50260801_94_dialog_content = "Ayah selalu begini!",
  ui_story_5026_50260801_95_dialog_content = "Setiap kali kukira sudah mencapai sesuatu sendiri, ternyata Ayah selalu campur tangan!",
  ui_story_5026_50260801_96_dialog_content = "Menurutmu, aku tak bisa apa-apa tanpa bantuanmu dan tanpa nama Andersen?!",
  ui_story_5026_50260801_97_dialog_content = "T-tidak! Tentu saja tidak! Bukan begitu, Nina!",
  ui_story_5026_50260801_98_dialog_content = "<size=45>Aku benci Ayah!</size>",
  ui_story_5026_50260801_99_dialog_content = "Begitulah ceritanya. Setelah itu, Nona Nina mengajak Sanae kabur.",
  ui_story_5026_50260801_100_dialog_content = "Jadi, Tuan mengutusku untuk membawa pulang Nona Nina... Tapi, tanpa memaksanya.",
  ui_story_5026_50260801_101_dialog_content = "(Itu pasti sangat memusingkan!)",
  ui_story_5026_50260801_102_dialog_content = "Sama sekali tidak. Itu memang bagian dari pekerjaanku.",
  ui_story_5026_50260801_103_dialog_content = "(Dia bisa membaca pikiranku?)",
  ui_story_5026_50260801_104_dialog_content = "Aku tidak membaca pikiranmu. Tenang saja.",
  ui_story_5026_50260801_105_dialog_content = "Kalau begitu, kenapa kau bisa tahu apa yang kupikirkan!?",
  ui_story_5026_50260801_106_dialog_content = "Maaf, Navigator, kau seperti orang yang mudah dipahami.",
  ui_story_5026_50260801_107_dialog_content = "Tapi, kau tak seperti orang yang pernah Nona Nina temui. Itu sebabnya dia terbuka kepadamu.",
  ui_story_5026_50260801_108_dialog_content = "Wow, kau sebut interaksi kita ini sebagai caranya “membuka” dirinya padaku?",
  ui_story_5026_50260801_109_dialog_content = "Bayangan mengawasimu, Navigator, dan tidak hanya satu.",
  ui_story_5026_50260801_110_dialog_content = "Semoga kau tak akan mengkhianati kepercayaan Nona Nina.",
  ui_story_5026_50260801_111_dialog_content = "Tenang saja. Bahkan dalam keadaan terburuk...",
  ui_story_5026_50260801_112_dialog_content = "Sheol tetap ingin memastikan bahwa kau harus bersaing dengan lebih sedikit transaksi setengah harga dalam urusan bisnis.",
  ui_story_5026_50260801_113_dialog_content = "Tentu juga akan ada konsekuensi yang tak berkaitan dengan masalah bisnis.",
  ui_story_5026_50260801_114_dialog_content = "Tidak, tidak, tidak, jangan bilang apa-apa lagi. Transaksi separuh harga sangat penting buatku!",
  ui_story_5026_50260801_115_dialog_content = "Terima kasih atas pengertianmu.",
  ui_story_5026_50260801_116_dialog_content = "Tapi, aku harus jujur kepadamu.",
  ui_story_5026_50260801_117_dialog_content = "Bagiku, Nina adalah Nina. Anggapan dunia tentangnya bukanlah hal penting untukku.",
  ui_story_5026_50260801_118_dialog_content = "Dia pasti akan sangat senang mendengarmu bilang begitu... sungguh.",
  ui_story_5026_50260801_119_dialog_content = "Kalau begitu, bolehkah aku bertanya sesuatu...",
  ui_story_5026_50260801_120_dialog_content = "Kalau dia marah kepadaku dan lari sambil berteriak \"PlayerName bodoh\"... Apa artinya itu?",
  ui_story_5026_50260801_121_dialog_content = "Nantinya kau bakal mati.",
  ui_story_5026_50260801_122_dialog_content = "(Bulu kudukku merinding... Jelas, aku tak menduganya!)",
  ui_story_5026_50260801_123_dialog_content = "Tadi itu hanya bercanda, kok. Aku bukan algojo, hanya seorang pelayan biasa.",
  ui_story_5026_50260801_124_dialog_content = "(Dia sama sekali tak kelihatan seperti sedang bercanda!)",
  ui_story_5026_50260801_125_dialog_content = "Menyenangkan, Tuan Navigator. Kau mau ikannya diapakan?",
  ui_story_5026_50260801_126_dialog_content = "Wow, banyak sekali! Semuanya ikan hias!",
  ui_story_5026_50260801_127_dialog_content = "Aku sudah menyuruh Chubb membawa ikan yang bisa dimakan ke dapur.",
  ui_story_5026_50260801_128_dialog_content = "Kalau tak merepotkan, tolong masukkan ikan itu ke Fountain of Hope di dekat Hyacinth Tower.",
  ui_story_5026_50260801_129_dialog_content = "Baiklah. Nah, aku permisi dulu, Lady Bethel, Tuan Navigator.",
  ui_story_5026_50260801_130_dialog_content = "Bethel... Apa semua pelayan di Umbraton memang seperti itu?",
  ui_story_5026_50260801_131_dialog_content = "Sama seperti di Guild milikku, Shadowlord juga punya bawahan yang menangani berbagai urusan.",
  ui_story_5026_50260801_132_dialog_content = "Kau mungkin kenal beberapa orang di antaranya. Mereka mahir menjalankan pekerjaan mereka tanpa kenal sungkan.",
  ui_story_5026_50260801_133_dialog_content = "Di Andersen Association, semua \"urusan\" yang tak relevan itu ditangani oleh Minos.",
  ui_story_5026_50260801_134_dialog_content = "Dia pelayan jempolan, tak ada pelayan lain yang sebaik dirinya.",
  ui_story_5026_50260801_135_dialog_content = "Benar... Terima kasih... Bethel.",
  ui_story_5026_50260801_136_dialog_content = "(Mungkin seharusnya aku tidak menanyakannya...)",
  ui_story_5026_50260801_137_dialog_content = "Nina, Nina! Ikannya menuju ke arahmu!",
  ui_story_5026_50260801_138_dialog_content = "...",
  ui_story_5026_50260801_139_dialog_content = "Minos, PlayerName, dan... Itu Bethel, bukan?",
  ui_story_5026_50260801_140_dialog_content = "Mereka sedang bahas apa, ya?",
  ui_story_5026_50260801_141_dialog_content = "Nina, kau dengar tidak, sih?",
  ui_story_5026_50260801_142_dialog_content = "Nina memandang ke arah ketiga orang itu sambil bergumam sendiri.",
  ui_story_5026_50260801_143_dialog_content = "Mungkin dia khawatir kalau tak berhasil mengalahkan Minos, berarti dia harus pulang dengannya.",
  ui_story_5026_50260801_144_dialog_content = "Sanae, apa kau sudah memutuskan siapa yang akan kaubantu?",
  ui_story_5026_50260801_145_dialog_content = "A-Aku tak akan membiarkan Nina kalah!",
  ui_story_5026_50260801_146_dialog_content = "Tapi, kalau kau sampai kehilangan pekerjaan ini, kau akan jadi gelandangan lagi.",
  ui_story_5026_50260801_147_dialog_content = "Jangan bilang begitu lagi kepadaku! Akan kutangkap ikan-ikannya, dan tak akan kubiarkan kau memengaruhi pikiranku!",
  ui_story_5026_50260801_148_dialog_content = "Sekarang!",
  ui_story_5026_50260801_149_dialog_content = "<size=45>Ah!</size>",
  ui_story_5026_50260801_150_dialog_content = "<color=#e8d9bb>Plop...</color>",
  ui_story_5026_50260801_151_dialog_content = "Sanae?",
  ui_story_5026_50260801_152_dialog_content = "Hah!?",
  ui_story_5026_50260901_1_dialog_content = "<anim type=Shake><size=45>H-Hatsyii!</size></anim>",
  ui_story_5026_50260901_2_dialog_content = "Handuk, Chubb!",
  ui_story_5026_50260901_3_dialog_content = "Chubb ini benar-benar penuh perhatian...",
  ui_story_5026_50260901_4_dialog_content = "Ini cuma ikan. Bagaimana mungkin kau tak hati-hati sampai tercebur ke air?",
  ui_story_5026_50260901_5_dialog_content = "Kau bahkan menjatuhkan bonekamu... Bisa jadi tadi kau membuat Manae takut.",
  ui_story_5026_50260901_6_dialog_content = "Akhirnya ada sesuatu yang... bisa kulakukan dengan baik. Aku hanya ingin menang...",
  ui_story_5026_50260901_7_dialog_content = "Maaf sudah merepotkanmu… Seharusnya tadi kupastikan dulu aku berdiri tegak. Seharusnya aku yang merawatmu…",
  ui_story_5026_50260901_8_dialog_content = "Rokmu juga jadi basah...",
  ui_story_5026_50260901_9_dialog_content = "M-Maafkan aku, Nina, Manae, dan Chubb...",
  ui_story_5026_50260901_10_dialog_content = "Bilang \"terima kasih\" saja.",
  ui_story_5026_50260901_11_dialog_content = "Atau, apa kau masih memperlakukanku seperti seorang putri walaupun kita sudah tak lagi tinggal di rumah besar itu?",
  ui_story_5026_50260901_12_dialog_content = "T-Tapi, aku selalu bertindak ceroboh dan tak bisa berbuat apa pun untukmu...",
  ui_story_5026_50260901_13_dialog_content = "Apa maksudmu? Kalau bukan karena kau melindungiku, tak mungkin kita bisa keluar dari rumah besar itu terang-terangan di depan Minos!",
  ui_story_5026_50260901_14_dialog_content = "Sayang sekali aku tak sempat melihat raut wajahnya saat dia menemukan lubang di pagar mawar itu...",
  ui_story_5026_50260901_15_dialog_content = "A-Aku tak terlalu cerdas... yang kubaca hanya hal-hal tak bermanfaat, dan kerjaku melamun saja...",
  ui_story_5026_50260901_16_dialog_content = "Apa hubungannya itu dengan caramu memperlakukanku layaknya orang normal?",
  ui_story_5026_50260901_17_dialog_content = "Sebenarnya, andai saja aku tak menyimak semua ceritamu tentang Cloud Island dan si Caelestite yang misterius itu...",
  ui_story_5026_50260901_18_dialog_content = "Mungkin aku tak akan memutuskan untuk pergi dari Umbraton dan melihat dunia ini dengan mata kepalaku sendiri.",
  ui_story_5026_50260901_19_dialog_content = "Kalau bukan karena itu, mungkin sekarang aku masih di kamarku dan merasa jengkel karena di luar hujan turun.",
  ui_story_5026_50260901_20_dialog_content = "Jadi, sebaiknya kau tak usah lagi khawatir bahwa aku akan terusik oleh pendapat orang-orang. Katakan saja yang kaupikirkan.",
  ui_story_5026_50260901_21_dialog_content = "Nina...",
  ui_story_5026_50260901_22_dialog_content = "Aku tak bermaksud menyela, tapi...",
  ui_story_5026_50260901_23_dialog_content = "Menurut syarat pengaturan staf yang diberitahukan PlayerName kepadaku, sekarang ini kita hanya butuh seorang tukang kayu.",
  ui_story_5026_50260901_24_dialog_content = "Hmm…",
  ui_story_5026_50260901_25_dialog_content = "Pakaian Sanae masih lembap. Bagaimana kalau kita istirahat saja dulu di sini?",
  ui_story_5026_50260901_26_dialog_content = "Menggunakan Luminatics di tempat yang hangat dan tak lembap bisa membuat pakaiannya cepat kering.",
  ui_story_5026_50260901_27_dialog_content = "Maafkan aku—maksudku, terima kasih, Lady Bethel.",
  ui_story_5026_50260901_28_dialog_content = "T-Tapi... Sejak tadi aku mau bertanya... Ini tempat apa?",
  ui_story_5026_50260901_29_dialog_content = "PlayerName menyuruh Chubb mengantar kita ke sini untuk beristirahat.",
  ui_story_5026_50260901_30_dialog_content = "Ini yang paling dekat! Di sini juga ada handuk, Chubb!",
  ui_story_5026_50260901_31_dialog_content = "Tapi, sepertinya ini kamar Tuan Navigator...",
  ui_story_5026_50260901_32_dialog_content = "Dia baik kepada kita. Sebaiknya aku berusaha membersihkan tempat ini untuknya.",
  ui_story_5026_50260901_33_dialog_content = "M-Maksudmu... Ini...",
  ui_story_5026_50260901_34_dialog_content = "Aku belum pernah masuk ke kamar laki-laki!",
  ui_story_5026_50260901_35_dialog_content = "K-Kenapa kau menutupi matamu, Nina?",
  ui_story_5026_50260901_36_dialog_content = "Ternyata kenyataan agak berbeda dari fiksi, ya?",
  ui_story_5026_50260901_37_dialog_content = "Lady Bethel?",
  ui_story_5026_50260901_38_dialog_content = "Sebenarnya, aku mau bertanya, kenapa kau santai sekali, Sanae?",
  ui_story_5026_50260901_39_dialog_content = "Aku... Sebelum tinggal bersama keluarga Andersen, aku sudah lama menjadi pelayan di beberapa keluarga lain.",
  ui_story_5026_50260901_40_dialog_content = "Aku juga sudah sering membersihkan kamar laki-laki.",
  ui_story_5026_50260901_41_dialog_content = "Aku ingat, di kolong ranjang mereka yang rapi, ternyata mereka menyembunyikan pakaian kotor mereka...",
  ui_story_5026_50260901_42_dialog_content = "Ada juga rak yang penuh berisi patung kecil, dan aku sama sekali tak boleh menyentuhnya walaupun isinya sudah sangat berdebu...",
  ui_story_5026_50260901_43_dialog_content = "Ada juga tumpukan berbagai macam barang yang langsung menimpaku begitu aku membuka lemari...",
  ui_story_5026_50260901_44_dialog_content = "Oh, di kolong ranjang juga ada—",
  ui_story_5026_50260901_45_dialog_content = "Anu... Nina... Kau baik-baik saja?",
  ui_story_5026_50260901_46_dialog_content = "Ini menyeramkan... Ini tempat paling menyeramkan sejak aku pergi dari rumah!",
  ui_story_5026_50260901_47_dialog_content = "Ini bahkan lebih seram daripada menyeberangi jembatan gantung!",
  ui_story_5026_50260901_48_dialog_content = "Kau akan baik-baik saja, Nina.",
  ui_story_5026_50260901_49_dialog_content = "Saat menghadapi hal asing, yang paling penting adalah mencari semua info intel yang bisa didapatkan.",
  ui_story_5026_50260901_50_dialog_content = "Aku pernah baca novel yang menceritakan bahwa tokoh utamanya menyimpan senjata di kolong ranjang.",
  ui_story_5026_50260901_51_dialog_content = "Kalau ada pembunuh bayaran yang menyelinap masuk ke rumahnya, dia akan mengambil senapannya dan melindungi si gadis!",
  ui_story_5026_50260901_52_dialog_content = "Oh... Aku pernah baca cerita itu!",
  ui_story_5026_50260901_53_dialog_content = "Dalam novel lain, si laki-laki itu pemalas dan ceroboh, tapi si gadis sangat memperhatikannya.",
  ui_story_5026_50260901_54_dialog_content = "Tapi, dia menyembunyikan banyak barang dewasa di kolong ranjangnya.",
  ui_story_5026_50260901_55_dialog_content = "Rupanya Lady Bethel suka baca novel roman. Apa kau pernah baca—",
  ui_story_5026_50260901_56_dialog_content = "Sanae... Aku mau keluar saja.",
  ui_story_5026_50260901_57_dialog_content = "Nina? Tunggu aku!",
  ui_story_5026_50260901_58_dialog_content = "Tugasnya hanya menebang kayu, kok! Aku bisa melakukannya sendiri. Mampirlah saja nanti!",
  ui_story_5026_50260901_59_dialog_content = "Nina tampak malu sekali. Dia tak nyaman dengan topik semacam ini...",
  ui_story_5026_50260901_60_dialog_content = "Sanae, barusan kau bilang kau juga membaca \"The Umbraton Seductress”?",
  ui_story_5026_50260901_61_dialog_content = "Bukan hanya kisah cinta antara tokoh utama, tapi kisah tentang kepercayaan dan pengkhianatan di antara para anggota geng itu juga seru!",
  ui_story_5026_50260901_62_dialog_content = "Kisahnya dengan jelas menggambarkan kondisi masyarakat kelas bawah di Umbraton. Itu salah satu cerita favoritku!",
  ui_story_5026_50260901_63_dialog_content = "Bagaimana dengan The Returned Princess of Lumopolis?",
  ui_story_5026_50260901_64_dialog_content = "Itu juga, dong! Aku suka adegan penculikan si mempelai wanita saat pernikahan di istana!",
  ui_story_5026_50260901_65_dialog_content = "Dulu aku ikut mengantre lama sekali hanya untuk membeli novel sekuelnya...",
  ui_story_5026_50260901_66_dialog_content = "Eh... Aku jadi kelewat bersemangat, ya?",
  ui_story_5026_50260901_67_dialog_content = "Tak apa. Akhirnya aku menemukan orang yang punya menyukai hal yang sama denganku. Andai saja kita bertemu sejak dulu!",
  ui_story_5026_50260901_68_dialog_content = "Seperti kata Nina tadi, kalau menyangkut topik yang kusukai, aku bisa jadi sangat cerewet.",
  ui_story_5026_50260901_69_dialog_content = "Tapi, aku tahu... Bukan hanya itu.",
  ui_story_5026_50260901_70_dialog_content = "Sejak dulu, kukira yang mau mendengarkanku cuma Manae.",
  ui_story_5026_50260901_71_dialog_content = "Nina membuatku sadar bahwa masih ada orang lain di dunia ini yang mau menerimaku apa adanya.",
  ui_story_5026_50260901_72_dialog_content = "Pasti itulah yang membuatku berani mengobrol denganmu seperti ini.",
  ui_story_5026_50260901_73_dialog_content = "Maksudku, aku memang berutang banyak kepadamu karena merusakkan kapal dari Cloud Island itu...",
  ui_story_5026_50260901_74_dialog_content = "Kalau aku masih seperti yang dulu, pasti aku tak akan berani berbicara denganmu...",
  ui_story_5026_50260901_75_dialog_content = "Sanae...",
  ui_story_5026_50260901_76_dialog_content = "Oh! Aku jelas akan bekerja keras untuk mendapatkan uang untuk melunasi utangku kepadamu!",
  ui_story_5026_50260901_77_dialog_content = "Heh... Tak usah terburu-buru. Tapi, sudah cukup obrolan tentang bisnisnya...",
  ui_story_5026_50260901_78_dialog_content = "Kita bahas The Returned Princess of Lumopolis II saja!",
  ui_story_5026_50260902_1_dialog_content = "<color=#e8d9bb>Cloud Gardens: Hutan</color>",
  ui_story_5026_50260902_2_dialog_content = "Tak kusangka aku bakal bertemu dengan Eclipsite yang tersesat di jalan. Ternyata butuh waktu yang lebih lama dari dugaanku.",
  ui_story_5026_50260902_3_dialog_content = "Terima kasih sudah menunjukkan jalan.",
  ui_story_5026_50260902_4_dialog_content = "Chubb!",
  ui_story_5026_50260902_5_dialog_content = "Sepertinya mereka lebih suka berada di balik rerimbunan pohon daripada di padang rumput terbuka.",
  ui_story_5026_50260902_6_dialog_content = "Sebagian besar binatang takut kepada Eclipsites. Kau juga, 'kan?",
  ui_story_5026_50260902_7_dialog_content = "Chubb?",
  ui_story_5026_50260902_8_dialog_content = "Benar-benar makhluk luar biasa. Dia tak kenal takut.",
  ui_story_5026_50260902_9_dialog_content = "Sama seperti si Caelestite itu.",
  ui_story_5026_50260902_10_dialog_content = "Tidak, mungkin aku menganggapnya aneh hanya karena aku sudah terlalu terbiasa dengan Umbraton...",
  ui_story_5026_50260902_11_dialog_content = "Terlalu terbiasa melihat semua orang di sana mengenakan topeng yang berlapis-lapis.",
  ui_story_5026_50260902_12_dialog_content = "Jangan khawatir! Aku akan melindungimu dari Eclipsite mana pun!",
  ui_story_5026_50260902_13_dialog_content = "Nina! Di sebelah sana!",
  ui_story_5026_50260902_14_dialog_content = "Bagaimana keadaan Sanae? Dia basah kuyup saat keluar dari sungai tadi.",
  ui_story_5026_50260902_15_dialog_content = "Tak apa. Bethel sedang mengeringkan pakaiannya dengan Luminatics.",
  ui_story_5026_50260902_16_dialog_content = "Di kamarmu.",
  ui_story_5026_50260902_17_dialog_content = "Di kamarku!?",
  ui_story_5026_50260902_18_dialog_content = "Kamar yang ada handuknya! Kamar paling dekat! Chubb!",
  ui_story_5026_50260902_19_dialog_content = "Memangnya harus di kamarku, ya?",
  ui_story_5026_50260902_20_dialog_content = "PlayerName, di kolong ranjangmu, tahu lah maksudku, anu...",
  ui_story_5026_50260902_21_dialog_content = "Uh... Kau menemukannya, ya?",
  ui_story_5026_50260902_22_dialog_content = "Apa...",
  ui_story_5026_50260902_23_dialog_content = "<size=45>D-Dasar tak tahu malu!</size>",
  ui_story_5026_50260902_24_dialog_content = "Apa maksudmu?",
  ui_story_5026_50260902_25_dialog_content = "Di sana hanya ada sekantung sisa Crunchy Munchy Crunch dan Pictorial Guide to Nature yang beberapa halamannya hilang.",
  ui_story_5026_50260902_26_dialog_content = "Harus kuakui, kamarku memang agak berantakan... Aku berniat membersihkannya sebelum Vice kembali...",
  ui_story_5026_50260902_27_dialog_content = "Apa... Jadi, itu...",
  ui_story_5026_50260902_28_option_content = "Kalau begitu, maksudmu tadi apa?",
  ui_story_5026_50260902_29_dialog_content = "Sama sekali bukan apa-apa!",
  ui_story_5026_50260902_30_option_content = "Memangnya ada apa lagi di sana!?",
  ui_story_5026_50260902_31_dialog_content = "M-Mana kutahu!?",
  ui_story_5026_50260902_32_dialog_content = "Tak usah ributkan hal-hal konyol itu. Apa yang kaubicarakan dengan Minos di sungai tadi?",
  ui_story_5026_50260902_33_dialog_content = "Yah... Sebatas membicarakan bahwa kau putri Count Andersen, dan kenapa kau kabur dari rumah.",
  ui_story_5026_50260902_34_dialog_content = "Sudah kuduga.",
  ui_story_5026_50260902_35_dialog_content = "Apa dia menawarimu bayaran tinggi asalkan kau tak mempekerjakanku?",
  ui_story_5026_50260902_36_dialog_content = "Aku memang butuh uang untuk melunasi utang-utangku, sih...",
  ui_story_5026_50260902_37_dialog_content = "Jadi, kau benar-benar menerima tawarannya?",
  ui_story_5026_50260902_38_dialog_content = "Tidak! Tentu saja tidak! Aku hanya bercanda.",
  ui_story_5026_50260902_39_dialog_content = "Omong-omong, bukankah bagus karena semua barang di tokomu terjual habis?",
  ui_story_5026_50260902_40_dialog_content = "Maksudku, orang membuka toko untuk mencari penghasilan, 'kan?",
  ui_story_5026_50260902_41_dialog_content = "Entah mana kata-katamu yang lebih mengejutkan...",
  ui_story_5026_50260902_42_dialog_content = "Yah... Eraveil jarang berdagang dengan dunia luar, dan Soroz tak bisa mengajariku banyak tentang hal itu.",
  ui_story_5026_50260902_43_dialog_content = "Sudahlah. Karena kau ini mitra bisnis yang penting, sepertinya lebih baik aku pura-pura tak tahu saja.",
  ui_story_5026_50260902_44_dialog_content = "Bagiku, ini semua cuma soal uang.",
  ui_story_5026_50260902_45_dialog_content = "Kau mungkin menganggapku ini seorang putri yang tak tahu apa-apa tentang kehidupan orang kebanyakan.",
  ui_story_5026_50260902_46_dialog_content = "Aku tahu, mendirikan bisnis yang menguntungkan itu tak mudah.",
  ui_story_5026_50260902_47_dialog_content = "Tapi, untuk desain-desainku, yang kuinginkan adalah pengakuan dari semua orang.",
  ui_story_5026_50260902_48_dialog_content = "Ayahku khawatir aku akan kecewa kalau barang daganganku tak terjual, maka dia pun memborong semuanya.",
  ui_story_5026_50260902_49_dialog_content = "Tapi, walaupun aku memang kecewa, aku sudah berusaha sebaik mungkin dan berhasil mendapatkan hasilnya.",
  ui_story_5026_50260902_50_dialog_content = "Tahu tidak, Bethel sudah jadi tangan kanan Shadowlord saat usianya masih sepantaran denganku?",
  ui_story_5026_50260902_51_dialog_content = "Jadi, targetmu adalah mengungguli Bethel dan menjadi saudagar top di Umbraton?",
  ui_story_5026_50260902_52_dialog_content = "Cih... Kau ini memang amatir yang berpikiran polos.",
  ui_story_5026_50260902_53_dialog_content = "Sudahlah. Aku tak heran sih kalau kau berpikir begitu.",
  ui_story_5026_50260902_54_dialog_content = "Benar, aku memang sering dibanding-bandingkan dengannya dalam semua acara sosial di Umbraton.",
  ui_story_5026_50260902_55_dialog_content = "Dia memang luar biasa, tapi aku membuka tokoku semata demi mengikuti kata hatiku.",
  ui_story_5026_50260902_56_dialog_content = "Tapi, jangan salah. Apa pun yang bisa dilakukannya, aku pun pasti bisa, suatu hari nanti!",
  ui_story_5026_50260902_57_dialog_content = "T-tentu saja, dengan usahaku sendiri, bukan dengan mengandalkan ayahku atau siapa pun juga!",
  ui_story_5026_50260902_58_dialog_content = "(Walaupun dia tak mau mengakuinya, dia masih saja membandingkan dirinya dengan Bethel.)",
  ui_story_5026_50260902_59_dialog_content = "Tak mengandalkan siapa pun juga...",
  ui_story_5026_50260902_60_dialog_content = "Nina.",
  ui_story_5026_50260902_61_dialog_content = "Hah? Kenapa tiba-tiba jadi serius begitu?",
  ui_story_5026_50260902_62_dialog_content = "Aku belum pernah bertemu dengan orang tuaku, kecuali dalam mimpi.",
  ui_story_5026_50260902_63_dialog_content = "Sebagai Caelestite terakhir di negeri ini... Sejak dulu aku selalu hidup sendirian.",
  ui_story_5026_50260902_64_dialog_content = "Dulu, kukira aku akan menemui ajal di bawah tanah bersama Soroz...",
  ui_story_5026_50260902_65_dialog_content = "Tapi, kemudian, Vice jatuh dari langit dan mengajakku masuk ke dunia yang sama sekali asing.",
  ui_story_5026_50260902_66_dialog_content = "Dalam perjalanan ini, aku bertemu banyak teman baru, dan mengarungi banyak petualangan luar biasa.",
  ui_story_5026_50260902_67_dialog_content = "Mereka juga banyak membantuku saat aku terpojok dan sendirian.",
  ui_story_5026_50260902_68_dialog_content = "Tanpa mereka, tak mungkin aku bisa berdiri di sini sekarang.",
  ui_story_5026_50260902_69_dialog_content = "Kau tak pernah berkelahi dengan mereka?",
  ui_story_5026_50260902_70_dialog_content = "Iya, kadang-kadang, tapi pada akhirnya kami selalu bisa saling memahami.",
  ui_story_5026_50260902_71_dialog_content = "Kalau ada yang tak kami sukai dari tindakan orang lain, kami langsung menyampaikannya tanpa basa-basi.",
  ui_story_5026_50260902_72_dialog_content = "Bicaralah dengan orang yang kaupedulikan selagi mereka masih ada... Jangan sampai kau mengatakan hal yang suatu hari nanti akan membuatmu menyesal.",
  ui_story_5026_50260902_73_dialog_content = "Kau tak berniat tak mau pulang selamanya hanya karena kau marah kepada ayahmu, 'kan?",
  ui_story_5026_50260902_74_dialog_content = "T-Tentu saja tidak...",
  ui_story_5026_50260902_75_dialog_content = "Seandainya kau bisa bilang kepadanya seperti yang barusan kaukatakan kepadaku...",
  ui_story_5026_50260902_76_dialog_content = "Aku yakin dia pasti bisa paham, dan dia tak akan mengulangi kesalahan yang sama.",
  ui_story_5026_50260902_77_dialog_content = "(Dia tipe orang yang menutup diri dari semua orang lain hanya karena putrinya marah kepadanya...)",
  ui_story_5026_50260902_78_dialog_content = "Sebelum kabur dari rumah, apa kau sudah membicarakannya baik-baik dengan ayahmu?",
  ui_story_5026_50260902_79_dialog_content = "...",
  ui_story_5026_50260902_80_dialog_content = "Bicara baik-baik... begitu? Baiklah.",
  ui_story_5026_50260902_81_dialog_content = "Tapi, sebelum itu, aku ingin mencapai hal yang ingin kucapai.",
  ui_story_5026_50260902_82_dialog_content = "Itu satu-satunya cara bagiku untuk membuktikan kepadanya bahwa aku bisa mencapai banyak hal tanpa harus mengandalkannya!",
  ui_story_5026_50260902_83_dialog_content = "Cloud Gardens aman, 'kan?",
  ui_story_5026_50260902_84_dialog_content = "Ya, kami sudah membasmi semua Eclipsite yang kami temui.",
  ui_story_5026_50260902_85_dialog_content = "Karena tugasnya sudah selesai, berikutnya kita perlu mengurus operasional bisnis.",
  ui_story_5026_50260902_86_dialog_content = "Terpikir olehku untuk mengubah tempat ini menjadi tempat peristirahatan yang tenang dan mendapatkan setumpuk uang dari biaya masuk dan akomodasi.",
  ui_story_5026_50260902_87_dialog_content = "Biaya akomodasi? Semua orang di sini temanku, aku tak akan pernah mau—",
  ui_story_5026_50260902_88_dialog_content = "Lalu mengembangkan lahan di sekitar sini untuk diubah menjadi pusat jaringan logistik yang menjangkau seluruh benua.",
  ui_story_5026_50260902_89_dialog_content = "Apa itu... jaringan logistik?",
  ui_story_5026_50260902_90_dialog_content = "Setelah itu, gunakan Colossus misterius itu, yang teknologinya jauh lebih canggih daripada Aurorian, untuk mengangkut kargo.",
  ui_story_5026_50260902_91_dialog_content = "Mestinya orang ternama sepertimu tak bakal kesulitan mencari pelanggan, 'kan, PlayerName?",
  ui_story_5026_50260902_92_dialog_content = "Kurasa mereka tak punya urusan bisnis denganku...",
  ui_story_5026_50260902_93_dialog_content = "Selalu ada bisnis di mana pun dan dengan siapa pun, PlayerName. Yang beda hanya barangnya, itu saja.",
  ui_story_5026_50260902_94_dialog_content = "Bahkan para klien besar madani yang tidak menjalin bisnis dengan Umbraton Guild...",
  ui_story_5026_50260902_95_dialog_content = "Mereka tak akan ragu membangun relasi bisnis dengan si Caelestite Terakhir.",
  ui_story_5026_50260902_96_dialog_content = "Tak berlebihan kalau membayangkan bahwa seluruh jaringan ekonomi di Astra suatu hari nanti akan ada dalam genggaman kita...",
  ui_story_5026_50260902_97_dialog_content = "Sangat berlebihan...",
  ui_story_5026_50260902_98_dialog_content = "Tapi, justru itulah rencana penaklukan yang sudah kususun untukmu.",
  ui_story_5026_50260902_99_dialog_content = "Nah, sekarang, sebaiknya kita mulai...",
  ui_story_5026_50260902_100_dialog_content = "Walaupun aku sangat ingin mengatakannya... Tapi sepertinya kau punya pendapat lain.",
  ui_story_5026_50260902_101_dialog_content = "Seperti katamu tadi, komunikasi adalah hal penting.",
  ui_story_5026_50260902_102_dialog_content = "Terutama kalau kita adalah mitra bisnis yang saling tergantung. Nah, bilang saja.",
  ui_story_5026_50260902_103_dialog_content = "Apa pendapatku?",
  ui_story_5026_50260902_104_dialog_content = "(Aku ingin Cloud Gardens jadi seperti apa... setelah menyingkirkan semua Eclipsite itu?)",
  ui_story_5026_50260902_105_dialog_content = "(Setelah aku melihat setiap jengkal lahan ini dengan mata kepalaku sendiri...)",
  ui_story_5026_50260902_106_dialog_content = "Aku…",
  ui_story_5026_50260902_107_dialog_content = "Maaf menyela, Nina dan Tuan Navigator.",
  ui_story_5026_50260902_108_dialog_content = "Tapi, ada sesuatu yang harus kulaporkan kepada PlayerName.",
  ui_story_5026_50260902_109_dialog_content = "Sewaktu mengumpulkan kayu tadi, tak ada tanda-tanda keberadaan Eclipsite, tapi sekarang...",
  ui_story_5026_50260902_110_dialog_content = "Sekelompok Eclipsite bergerak mendekat dari hutan.",
  ui_story_5026_50261001_1_dialog_content = "Fyuh... Mestinya itu tadi yang terakhir.",
  ui_story_5026_50261001_2_dialog_content = "PlayerName?",
  ui_story_5026_50261001_3_dialog_content = "Apa ini...?",
  ui_story_5026_50261001_4_dialog_content = "Aku bisa merasakan Darkflow menyelubungi Cloud Gardens...",
  ui_story_5026_50261001_5_dialog_content = "Apa kemampuanku kacau?",
  ui_story_5026_50261001_6_dialog_content = "Ada hal buruk yang sedang terjadi!",
  ui_story_5026_50261001_7_dialog_content = "Apa yang terjadi?",
  ui_story_5026_50261001_8_dialog_content = "Setelah kami pergi dari asrama untuk menemuimu, kami melihat...",
  ui_story_5026_50261001_9_dialog_content = "Kalaupun kuberi tahu, kau tak akan percaya. Sini, biar kutunjukkan langsung saja!",
  ui_story_5026_50261001_10_dialog_content = "Ada apa ini... Kita baru saja membasmi semua Eclipsite di tempat ini, 'kan?",
  ui_story_5026_50261001_11_dialog_content = "Tadinya kukira Eclipsite yang berkeliaran masuk ke sini jumlahnya tak banyak...",
  ui_story_5026_50261001_12_dialog_content = "Lalu, saat aku berpatroli keliling Cloud Gardens, aku baru sadar bahwa ternyata mereka belum semuanya binasa.",
  ui_story_5026_50261001_13_dialog_content = "Lalu, sekarang...",
  ui_story_5026_50261001_14_dialog_content = "Aku sungguh terlalu bodoh.",
  ui_story_5026_50261001_15_dialog_content = "K-Kita hanya perlu mengusir mereka, 'kan?",
  ui_story_5026_50261001_16_dialog_content = "Aku sudah cukup merasa sungkan karena memberimu masa percobaan tanpa gaji...",
  ui_story_5026_50261001_17_dialog_content = "Tapi, krisis ini sama sekali di luar perkiraanku.",
  ui_story_5026_50261001_18_dialog_content = "Umbraton pasti akan menyewa tentara bayaran kalau sampai salah satu kotanya menghadapi Eclipsite sebanyak ini.",
  ui_story_5026_50261001_19_dialog_content = "Tapi, pasti nanti jadinya butuh biaya ekstra.",
  ui_story_5026_50261001_20_dialog_content = "Aku tak mau terbelit utang padahal Cloud Gardens baru saja dibuka, tapi sepertinya aku tak punya pilihan lain...",
  ui_story_5026_50261001_21_dialog_content = "Aku akan kembali ke Umbraton dan menghubungi para tentara bayaran yang terdaftar di Guild.",
  ui_story_5026_50261001_22_dialog_content = "Lebih cepat kalau naik Colossus, tapi kau pasti tak mau meninggalkan Cloud Gardens dalam kondisi seperti ini, 'kan, PlayerName?",
  ui_story_5026_50261001_23_dialog_content = "Aku tahu anggaranmu terbatas. Aku akan berusaha sebaik mungkin agar kau dapat diskon!",
  ui_story_5026_50261001_24_dialog_content = "Apa yang harus kita lakukan sekarang, PlayerName?",
  ui_story_5026_50261001_25_dialog_content = "Kawanan Eclipsite itu sepertinya belum menemukan kita.",
  ui_story_5026_50261001_26_dialog_content = "Hmm... Sepertinya mereka bergerak tanpa tujuan tertentu.",
  ui_story_5026_50261001_27_dialog_content = "Setidaknya, itu berarti ini bukan serangan yang didalangi oleh High-Level Eclipsite.",
  ui_story_5026_50261001_28_dialog_content = "Kalau tak menyusun strategi penanganan jangka panjang, lain kali mungkin saja kita tak akan seberuntung ini.",
  ui_story_5026_50261001_29_dialog_content = "Aku merasakan aktivitas Eclipsite lebih sedikit di sekitar Hyacinth Tower. Kita tunggu Bethel di sana saja.",
  ui_story_5026_50261201_1_dialog_content = "(Obelisk of Return pasti mengusir semua Eclipsite yang ada di Eraveil pada saat itu...)",
  ui_story_5026_50261201_2_dialog_content = "(Kalau begitu, berarti kawanan Eclipsite yang ini pasti berasal dari tempat lain.)",
  ui_story_5026_50261201_3_dialog_content = "(Persis seperti yang dibilang Nina... Kedamaian adalah hal yang langka dan berharga...)",
  ui_story_5026_50261201_4_dialog_content = "(Biaya sewa tentara bayaran dari Umbraton pasti sangat mahal!)",
  ui_story_5026_50261201_5_dialog_content = "Rupanya kau di sini, PlayerName.",
  ui_story_5026_50261201_6_dialog_content = "...",
  ui_story_5026_50261201_7_dialog_content = "Hoi, PlayerName!",
  ui_story_5026_50261201_8_dialog_content = "Nina...?",
  ui_story_5026_50261201_9_dialog_content = "A-Aku kemari bukan karena aku peduli kepadamu!",
  ui_story_5026_50261201_10_dialog_content = "Hanya saja... kalau aku meninggalkanmu seperti ini, bisnis kita pasti akan terpengaruh!",
  ui_story_5026_50261201_11_dialog_content = "Itu saja!",
  ui_story_5026_50261201_12_dialog_content = "Jadi, kau kemari karena kau peduli kepadaku.",
  ui_story_5026_50261201_13_dialog_content = "Anu... Tidak sepenuhnya benar, sih.",
  ui_story_5026_50261201_14_dialog_content = "Minos dan Sanae sedang berjaga. Tak akan ada Eclipsite yang berani mendekat.",
  ui_story_5026_50261201_15_dialog_content = "Sudahlah, kita duduk di sana saja.",
  ui_story_5026_50261201_16_dialog_content = "Kenapa sepertinya kau punya lebih banyak ide daripada aku?",
  ui_story_5026_50261201_17_dialog_content = "Tak lama lagi aku akan kembali ke Umbraton bersama Minos.",
  ui_story_5026_50261201_18_dialog_content = "Aku bertaruh dengannya. Kalau aku bisa mengalahkannya dalam satu hal saja, dia akan membiarkan aku sendiri.",
  ui_story_5026_50261201_19_dialog_content = "Kau tak mungkin bisa mengalahkannya.",
  ui_story_5026_50261201_20_dialog_content = "D-Diam!",
  ui_story_5026_50261201_21_dialog_content = "Aku... mestinya aku tahu Minos tak mungkin bertindak kalau dia tak yakin bisa menang.",
  ui_story_5026_50261201_22_dialog_content = "Entah itu menanam Unique Tree, menggali harta karun, atau memancing...",
  ui_story_5026_50261201_23_dialog_content = "Aku juga kalah saat memancing tadi, 'kan?",
  ui_story_5026_50261201_24_dialog_content = "Kalau kau memang harus bersaing dengannya...",
  ui_story_5026_50261201_25_dialog_content = "Minos mengelompokkan kayu yang sudah dikumpulkannya, dan bahkan mencatat kira-kira kayu itu paling baik digunakan untuk apa.",
  ui_story_5026_50261201_26_dialog_content = "Dia juga bilang, dia menebang dengan metode tebang pilih agar pohon-pohon lainnya bisa tumbuh lebih baik.",
  ui_story_5026_50261201_27_dialog_content = "Aku asal tebang pohon mana saja yang ada di dekatku... Aku bahkan tak tahu ternyata ada metode lain untuk menebang pohon...",
  ui_story_5026_50261201_28_dialog_content = "Jadi, seberapa pun banyaknya kayu yang berhasil kukumpulkan bersama Sanae... Sejak awal, kami memang sudah ditakdirkan bakal kalah.",
  ui_story_5026_50261201_29_dialog_content = "Yah... Sebagai pelayan kami, memang wajar kalau dia punya kemampuan setinggi itu.",
  ui_story_5026_50261201_30_dialog_content = "Lho, sekarang kok kau malah memujinya?",
  ui_story_5026_50261201_31_dialog_content = "Aku hanya sebatas mengakui kegagalanku dan mengatakan fakta.",
  ui_story_5026_50261201_32_dialog_content = "Tapi, seperti yang mungkin sudah kauketahui, tugasnya cuma membawaku pulang.",
  ui_story_5026_50261201_33_dialog_content = "Pada akhirnya, kau tak akan bisa menemukan orang yang cocok untuk mengelola Cloud Gardens, 'kan?",
  ui_story_5026_50261201_34_dialog_content = "Kau tak perlu khawatir soal itu.",
  ui_story_5026_50261201_35_dialog_content = "Mungkin ini terdengar tak bisa dipercaya, tapi Minos bilang...",
  ui_story_5026_50261201_36_dialog_content = "Saat melakukan tugas rutin harian, dia berhasil mengajarkan metode kerjanya kepada para Chubb Farmer.",
  ui_story_5026_50261201_37_dialog_content = "Rupanya itu sebabnya mereka memanggilnya \"Master\".",
  ui_story_5026_50261201_38_dialog_content = "Katanya, walaupun terbatas oleh kondisi bawaan, mereka tetap saja murid yang pintar.",
  ui_story_5026_50261201_39_dialog_content = "Setidaknya, semua Unique Tree pasti bisa tumbuh dengan baik dalam perawatan mereka.",
  ui_story_5026_50261201_40_dialog_content = "Anggaranku jelas tak memungkinkan untuk mempekerjakan pelayan seperti Minos...",
  ui_story_5026_50261201_41_dialog_content = "Aku tak tahu dia berhasil melakukannya... Seperti belum cukup saja, padahal dia juga berhasil mengalahkanku.",
  ui_story_5026_50261201_42_dialog_content = "Tapi... Kurasa, mungkin agak ceroboh kalau aku kabur dari rumah begitu saja.",
  ui_story_5026_50261201_43_dialog_content = "B-Bukan kau yang membuatku berpikir begitu!",
  ui_story_5026_50261201_44_dialog_content = "Aku masih marah kepada ayahku atas tindakannya, dan marah kepada Minos karena dia selalu saja memihak ayahku.",
  ui_story_5026_50261201_45_dialog_content = "Tapi, aku lebih marah kepada diriku sendiri.",
  ui_story_5026_50261201_46_dialog_content = "Arogan sekali aku ini, menyusun rencana bisnis besar untukmu, padahal mengatasi Eclipsite saja aku tak mampu.",
  ui_story_5026_50261201_47_dialog_content = "Pekerjaanku di ladang juga payah... Aku sama sekali belum bisa menjadi diriku seperti yang kucita-citakan.",
  ui_story_5026_50261201_48_dialog_content = "Kau tak payah, kok... tapi tak bagus-bagus amat juga, sih...",
  ui_story_5026_50261201_49_dialog_content = "Hmm? Maksudmu apa, sih?",
  ui_story_5026_50261201_50_dialog_content = "Bukan apa-apa! Menurutku, rencana bisnis besarmu itu keren! Lumayan kreatif dan imajinatif!",
  ui_story_5026_50261201_51_dialog_content = "Heh... Rencana bisnis memang mesti dikritik habis-habisan.",
  ui_story_5026_50261201_52_dialog_content = "Kuakui, masih banyak hal yang harus kuatasi, misalnya masalah geografis dan transportasi, tapi...",
  ui_story_5026_50261201_53_dialog_content = "Pusat bisnis besar tak mungkin bisa hidup kalau tak dilengkapi kafe, restoran, dan taman hiburan, seperti Umbraton!",
  ui_story_5026_50261201_54_dialog_content = "Hmm… Bagaimana cara mengatakannya, ya?",
  ui_story_5026_50261201_55_dialog_content = "Aku tak bisa membayangkan Cloud Gardens menjadi pusat bisnis...",
  ui_story_5026_50261201_56_dialog_content = "Aku juga tak bisa membayangkan Soroz menjadi sarana bisnis.",
  ui_story_5026_50261201_57_dialog_content = "Soroz punya pikiran sendiri.",
  ui_story_5026_50261201_58_dialog_content = "Setidaknya... dulu dia punya. Dialah yang mengasuhku.",
  ui_story_5026_50261201_59_dialog_content = "Lama sekali Soroz mengajariku segala hal yang perlu kuketahui tentang kaum Caelestite.",
  ui_story_5026_50261201_60_dialog_content = "(Seandainya dia melihatku sekarang, kira-kira dia akan bilang apa, ya...?)",
  ui_story_5026_50261201_61_dialog_content = "Oh, begitu. Maaf, pertimbanganku kurang matang.",
  ui_story_5026_50261201_62_dialog_content = "Kalau begitu, coba katakan apa pendapatmu.",
  ui_story_5026_50261201_63_dialog_content = "Apa?",
  ui_story_5026_50261201_64_dialog_content = "Kau ingin Cloud Gardens jadi seperti apa?",
  ui_story_5026_50261201_65_dialog_content = "...",
  ui_story_5026_50261201_66_dialog_content = "Di Eraveil, dulu seorang Caelestite rela berubah menjadi Eclipsite demi mendapatkan kekuatan, dan seluruh kaumku jadi korbannya.",
  ui_story_5026_50261201_67_dialog_content = "Aku benar-benar paham, upayanya untuk mengejar kekuatan itu memang suatu kesalahan besar.",
  ui_story_5026_50261201_68_dialog_content = "Tapi, kupikir...",
  ui_story_5026_50261201_69_dialog_content = "Apa yang mendorongnya untuk menempuh cara itu kalau bukan karena dia congkak dan pengecut?",
  ui_story_5026_50261201_70_dialog_content = "Aku masih belum tahu cerita lengkapnya. Aku hanya tahu sepotong-sepotong.",
  ui_story_5026_50261201_71_dialog_content = "Aku hanya tahu bahwa dia tak mendapatkan kedamaian dan ketenangan yang didambakannya.",
  ui_story_5026_50261201_72_dialog_content = "Jadi... Aku ingin membuat tempat ini menjadi tempat bernaung yang tenang dan tenteram bagi semua orang.",
  ui_story_5026_50261201_73_dialog_content = "Tempat yang berbeda dari Eraveil yang ada pada masa leluhurku dulu.",
  ui_story_5026_50261201_74_dialog_content = "PlayerName…",
  ui_story_5026_50261201_75_dialog_content = "Kata-katamu dalam sekali. Aku bahkan sedikit, tidak, aku sangat tersentuh oleh kata-katamu barusan.",
  ui_story_5026_50261201_76_dialog_content = "Tapi, aku perlu informasi spesifik. Kau berencana akan membangun apa di sini?",
  ui_story_5026_50261201_77_dialog_content = "Kau pragmatis sekali, ya. Seingatku, aku pernah membahas hal seperti ini dengan Bethel.",
  ui_story_5026_50261201_78_dialog_content = "Ini namanya bertindak praktis. Sebaiknya kaubiasakan diri dengan gaya hidup orang-orang Umbraton.",
  ui_story_5026_50261201_79_dialog_content = "Menurut apa yang disampaikan Bethel dalam lowongan pekerjaan, kita harus mencari laba, 'kan?",
  ui_story_5026_50261201_80_dialog_content = "Ya ampun... Mana aku tahu kalau ternyata info intel dari Sheol sangat mahal...",
  ui_story_5026_50261201_81_dialog_content = "Menyepelekan nilai info intel... Dasar kacangan.",
  ui_story_5026_50261201_82_dialog_content = "Apa ada cara untuk mengeruk banyak Nightium sekaligus bagaikan menang lotre?",
  ui_story_5026_50261201_83_dialog_content = "PlayerName, apa kau tahu tentang sektor ekonomi ilegal?",
  ui_story_5026_50261201_84_dialog_content = "Kedengarannya tak bagus...",
  ui_story_5026_50261201_85_dialog_content = "Sumber yang tidak diketahui, tapi menghasilkan laba besar. Banyak Guild di Umbraton punya aset semacam itu...",
  ui_story_5026_50261201_86_dialog_content = "Termasuk keluarga Andersen, sebelum akhirnya diambil alih oleh ayahku.",
  ui_story_5026_50261201_87_dialog_content = "Apa barusan itu informasi yang mestinya tabu?",
  ui_story_5026_50261201_88_dialog_content = "Aku tidak memintamu untuk melakukan hal yang sama, aku hanya ingin menawarkan pilihan.",
  ui_story_5026_50261201_89_dialog_content = "Kok bisa ada orang yang bisa dengan mudah menghasilkan uang tanpa mengetahui dari mana asal-usulnya, terutama mengingat ada orang yang bisa dirugikan dalam prosesnya?",
  ui_story_5026_50261201_90_dialog_content = "Aku tak tahu soal orang-orang lainnya, tapi itu warisan besar untuk ayahku.",
  ui_story_5026_50261201_91_dialog_content = "Meski dia membebaskan keluarga kami dari bisnis gelap seperti itu, dia tak bisa berbuat apa-apa soal warisan masa lalu yang tak bisa dia kendalikan.",
  ui_story_5026_50261201_92_dialog_content = "Tapi, dia bisa menentukan cara untuk memanfaatkan warisan itu.",
  ui_story_5026_50261201_93_dialog_content = "Aku ingat dia mengatakan sesuatu kepadaku setelah kami berkunjung ke klinik dan panti asuhan yang didanai oleh keluarga Andersen.",
  ui_story_5026_50261201_94_dialog_content = "\"Yang sudah berlalu biarlah berlalu. Yang masih bisa kita genggam adalah masa kini dan masa depan.\"",
  ui_story_5026_50261201_95_dialog_content = "Sebagian orang di Umbraton bilang, itu adalah derita bagi kaum kaya, kecongkakan kaum bangsawan yang pamornya makin merosot, atau bisa ular yang disamarkan dengan kata-kata manis...",
  ui_story_5026_50261201_96_dialog_content = "Cih! Mungkin mereka kira mereka bisa naik derajat ke Lumopolis hanya dengan menapaki tangga gading bernama moral!",
  ui_story_5026_50261201_97_dialog_content = "Tapi, aku memang lihat sendiri banyak pihak diuntungkan dengan adanya warisan itu.",
  ui_story_5026_50261201_98_dialog_content = "Aku penasaran, apa ayah mengurus dirinya baik-baik selama aku pergi...",
  ui_story_5026_50261201_99_dialog_content = "Seandainya dia di sini, dia pasti bisa memberimu nasihat yang lebih bagus, PlayerName.",
  ui_story_5026_50261201_100_dialog_content = "A-Aku malah melantur... Sudahlah...",
  ui_story_5026_50261201_101_dialog_content = "Nina, sebenarnya kau sangat menyayangi ayahmu, 'kan?",
  ui_story_5026_50261201_102_dialog_content = "Kenapa kau berpikir begitu!? Baiklah. Memang tadi aku sendiri yang melantur, sih...",
  ui_story_5026_50261201_103_dialog_content = "Tidak terlalu.",
  ui_story_5026_50261201_104_dialog_content = "Bisa dibilang, Cloud Gardens dan para Chubb itu adalah... warisanku.",
  ui_story_5026_50261201_105_dialog_content = "Tapi, entah kenapa, aku tak menyadarinya.",
  ui_story_5026_50261201_106_dialog_content = "Mungkin saja akan ada keuntungan tak terduga dari semua ini...",
  ui_story_5026_50261201_107_dialog_content = "<size=45>Aku setuju!</size>",
  ui_story_5026_50261201_108_dialog_content = "Eeh?",
  ui_story_5026_50261201_109_dialog_content = "Kau kurang memperhatikan para Chubb itu!",
  ui_story_5026_50261201_110_dialog_content = "Aku memang lebih terbiasa melihat hal-hal detail pada wujud fisik karena aku ini desainer...",
  ui_story_5026_50261201_111_dialog_content = "Tapi, bisa-bisanya kau tak bisa membedakan para Chubb itu dari satu sama lain?",
  ui_story_5026_50261201_112_dialog_content = "Perbedaannya memang tak tampak kalau hanya dengan melihat mereka, tapi Sanae juga bilang masing-masing dari mereka punya kepribadian berbeda-beda.",
  ui_story_5026_50261201_113_dialog_content = "Kepribadian berbeda-beda? Sungguh?",
  ui_story_5026_50261201_114_dialog_content = "Sanae merasa tak enak hati karena mengira mereka semua sama, jadi akhirnya dia lebih memperhatikan mereka.",
  ui_story_5026_50261201_115_dialog_content = "Tapi, mestinya kau tak perlu memperhatikan secermat Sanae hanya untuk mengetahui perbedaan mereka. Maksudku, mestinya kau sudah tahu karena kau kan sudah lama tinggal bersama mereka.",
  ui_story_5026_50261201_116_dialog_content = "PlayerName, apa kau pernah mempertimbangkan untuk memberikan pelatihan berkala untuk para karyawanmu?",
  ui_story_5026_50261201_117_dialog_content = "Atau melibatkan mereka untuk mengatasi masalah yang kauhadapi saat mengelola bisnismu?",
  ui_story_5026_50261201_118_dialog_content = "Tapi... kalau kawanan Eclipsite itu tak disingkirkan dulu, tak akan ada bisnis...",
  ui_story_5026_50261201_119_dialog_content = "Kalau sudah bicara soal bisnis, kau jadi seram amat...",
  ui_story_5026_50261201_120_dialog_content = "<size=45>D-Diam!</size> Aku ini berusaha membantumu, tahu!",
  ui_story_5026_50261201_121_dialog_content = "Aku tahu, kok, dan aku berterima kasih untuk itu, Nina.",
  ui_story_5026_50261201_122_dialog_content = "Berkat kata-katamu tadi, aku jadi mempertimbangkan suatu cara... Aku hanya perlu mencobanya dulu...",
  ui_story_5026_50261201_123_dialog_content = "Aku akan coba bertindak sebagai Master di Cloud Gardens...",
  ui_story_5026_50261201_124_dialog_content = "Metode Caelestite.",
  ui_story_5026_50261301_1_dialog_content = "Apa yang kaucari di semak-semak ini? Di sini tak ada apa-apa.",
  ui_story_5026_50261301_2_dialog_content = "Metode Caelestite macam apa ini?",
  ui_story_5026_50261301_3_dialog_content = "Sudah kuduga. Reruntuhan ini sama persis dengan bangunan-bangunan yang kuperbaiki sesuai cetak birunya itu.",
  ui_story_5026_50261301_4_dialog_content = "Asrama, sumur... Dari tampilannya, sepertinya dulu Cloud Gardens adalah area hunian luas. Tak diragukan lagi.",
  ui_story_5026_50261301_5_dialog_content = "Tapi, sisa-sisa pos jaganya sedikit sekali.",
  ui_story_5026_50261301_6_dialog_content = "Karena tindakan defensif di Obelisk of Return sangat sulit untuk diaktifkan...",
  ui_story_5026_50261301_7_dialog_content = "Mungkin Cloud Gardens punya sistem pertahanan otomatis sendiri...",
  ui_story_5026_50261301_8_dialog_content = "Lumayan juga... PlayerName.",
  ui_story_5026_50261301_9_option_content = "Terkesan, nih?",
  ui_story_5026_50261301_10_dialog_content = "S-Sedikit.",
  ui_story_5026_50261301_11_option_content = "Hmph!",
  ui_story_5026_50261301_12_dialog_content = "Jangan congkak.",
  ui_story_5026_50261301_13_dialog_content = "Aku tak menyangka, ternyata mempelajari cetak biru itu bermanfaat sampai sejauh ini.",
  ui_story_5026_50261301_14_dialog_content = "Aku jadi ingat... Mungkin ia tahu soal sistem pertahanan itu.",
  ui_story_5026_50261301_15_dialog_content = "<anim type=Shake>Heh, heh...</anim>",
  ui_story_5026_50261301_16_dialog_content = "Bangun! Bangun!",
  ui_story_5026_50261301_17_dialog_content = "Chubb berkumis panjang... dan teksturnya tampak bagus...",
  ui_story_5026_50261301_18_dialog_content = "Oh, Master! Apa kau menemukan cetak biru baru, Chubb?",
  ui_story_5026_50261301_19_dialog_content = "Hari ini aku kemari bukan untuk mencari cetak biru.",
  ui_story_5026_50261301_20_dialog_content = "Aku ingin tahu apa Cloud Gardens punya sistem pertahanan.",
  ui_story_5026_50261301_21_dialog_content = "Tentu. Chubb.",
  ui_story_5026_50261301_22_dialog_content = "Sungguh? Kenapa tak bilang dari dulu?",
  ui_story_5026_50261301_23_dialog_content = "Master tak pernah tanya, Chubb.",
  ui_story_5026_50261301_24_dialog_content = "Mestinya hal sepenting ini diberitahukan dulu kepadaku, bukannya malah mengajariku menanam pohon dulu!",
  ui_story_5026_50261301_25_dialog_content = "Aku tidak paham. Tolong ulangi, Chubb?",
  ui_story_5026_50261301_26_dialog_content = "(Tiba-tiba aku ingat betapa frustrasinya mencoba bicara dengan Neural Aux di Obelisk of Return dulu...)",
  ui_story_5026_50261301_27_dialog_content = "Bagaimana cara mengaktifkan sistem pertahanan itu?",
  ui_story_5026_50261301_28_dialog_content = "Kau bisa mengaktifkan atau menonaktifkan sistem pertahanan bertarget itu dari terminal kontrol di Hyacinth Tower, Chubb.",
  ui_story_5026_50261301_29_dialog_content = "Bagaimana cara masuk ke terminal kontrol?",
  ui_story_5026_50261301_30_dialog_content = "Informasi rahasia diakses. Mengalihkan mode interaksi. Memverifikasi akses...",
  ui_story_5026_50261301_31_dialog_content = "Target: PlayerName, Caelestite Terakhir.",
  ui_story_5026_50261301_32_dialog_content = "Mengonfirmasi kode kelas \"Defender\"... Verifikasi gagal.",
  ui_story_5026_50261301_33_dialog_content = "Mengakhiri proses verifikasi...",
  ui_story_5026_50261301_34_dialog_content = "\"Highest Decree\" diverifikasi.",
  ui_story_5026_50261301_35_dialog_content = "Perintah PlayerName harus dipatuhi, keinginan PlayerName harus diwujudkan.",
  ui_story_5026_50261301_36_dialog_content = "Akses diverifikasi. Informasi rahasia terbuka.",
  ui_story_5026_50261301_37_dialog_content = "PlayerName, si Caelestite.",
  ui_story_5026_50261301_38_dialog_content = "Ya! Aku di sini!",
  ui_story_5026_50261301_39_dialog_content = "Tiba-tiba saja terasa seperti sedang bicara dengan lansia...",
  ui_story_5026_50261301_40_dialog_content = "Untuk membalik meja kerja dan mengakses terminal kontrol, kau harus melakukan telepati dengan empat Chubb atau lebih dan menyintesis Secret Key.",
  ui_story_5026_50261301_41_dialog_content = "Informasi rahasia disampaikan. Mengalihkan mode interaksi.",
  ui_story_5026_50261301_42_dialog_content = "A-Ada lagi?",
  ui_story_5026_50261301_43_dialog_content = "<anim type=Shake>*Mengorok*</anim>",
  ui_story_5026_50261301_44_dialog_content = "<size=45>Eh, malah tidur!</size>",
  ui_story_5026_50261301_45_dialog_content = "Meja kerja itu pastilah alat yang kugunakan untuk membuat furnitur... Jadi, terminal kontrolnya ada di baliknya?",
  ui_story_5026_50261301_46_dialog_content = "Terakhir kali waktu sedang membuat meja, aku menghantamnya cukup keras... Semoga saja tak rusak...",
  ui_story_5026_50261301_47_dialog_content = "Daripada khawatir soal itu, bagaimana kalau kaucari dulu tiga Chubb lagi?",
  ui_story_5026_50261301_48_dialog_content = "Benar. Mungkin nanti akan ada pertarungan dalam prosesnya.",
  ui_story_5026_50261301_49_dialog_content = "Biar kubantu kau sekali lagi. Eclipsite apa pun yang kita temui nanti, aku akan...",
  ui_story_5026_50261301_50_dialog_content = "Maksudku, aku dan Sanae dan semuanya, akan melindungimu!",
  ui_story_5026_50261301_51_dialog_content = "Lakukan saja tugasmu sebagai komandan. Jangan memperlambat gerakku!",
  ui_story_5026_50261402_1_dialog_content = "Hah! Di sini cocok, 'kan?",
  ui_story_5026_50261402_2_dialog_content = "Nah, semua Chubb yang kita butuhkan sudah ada di sini...",
  ui_story_5026_50261402_3_dialog_content = "Tapi, aku masih ingin dipeluk sebentar lagi, Chubb.",
  ui_story_5026_50261402_4_dialog_content = "Hmm... Kalau begitu, bagaimana kalau aku...",
  ui_story_5026_50261402_5_dialog_content = "Sanae, abaikan saja.",
  ui_story_5026_50261402_6_dialog_content = "(Aku mulai paham maksud Sanae bahwa mereka punya \"kepribadian berbeda-beda\"...)",
  ui_story_5026_50261402_7_dialog_content = "(Kalau hanya keempat Chubb ini, sebenarnya aku bisa membedakan mereka cukup dengan melihatnya...)",
  ui_story_5026_50261402_8_dialog_content = "Jadi, aku harus melakukan telepati dengan mereka untuk menyintesis Secret Key? Sepertinya gampang.",
  ui_story_5026_50261402_9_dialog_content = "Kalau mau, kau bisa mulai menghubungkan dengan Chubb sesuai urutan.",
  ui_story_5026_50261402_10_dialog_content = "Sesuai urutan?",
  ui_story_5026_50261402_11_dialog_content = "Chubb Scholar ada di urutan ketiga, Chubb.",
  ui_story_5026_50261402_12_dialog_content = "Elder Chubb ada di urutan kedua, Chubb.",
  ui_story_5026_50261402_13_dialog_content = "Baiklah... Kalau begitu...",
  ui_story_5026_50261402_14_dialog_content = "Chubb Merchant harusnya ada di urutan ketiga, Chubb.",
  ui_story_5026_50261402_15_dialog_content = "Hah? Apa?",
  ui_story_5026_50261402_16_dialog_content = "Chubb Merchant merasa Chubb Scholar harusnya ada di urutan ketiga, Chubb.",
  ui_story_5026_50261402_17_dialog_content = "Chubb Farmer ada di urutan pertama, Chubb.",
  ui_story_5026_50261402_18_dialog_content = "Chubb Farmer ingat Elder Chubb ada di urutan keempat, Chubb.",
  ui_story_5026_50261402_19_dialog_content = "Kenapa kalian bertingkah seakan kalian tahu segalanya...?",
  ui_story_5026_50261402_20_dialog_content = "Bisa beri tahu saja urutannya, tidak? Elder Chubb mestinya tahu, 'kan?",
  ui_story_5026_50261402_21_dialog_content = "Aku sudah tua dan tidak ingat, Chubb.",
  ui_story_5026_50261402_22_dialog_content = "<size=45>Kukira ingatanmu masih cukup tajam!</size>",
  ui_story_5026_50261402_23_dialog_content = "Tapi, aku tahu apa yang mereka katakan itu setengah benar tapi juga setengah salah. Chubb.",
  ui_story_5026_50261402_24_dialog_content = "Jadi... Aku tidak akan bisa melakukan telepati dengan benar kalau urutannya salah?",
  ui_story_5026_50261402_25_dialog_content = "Tentu saja bisa, tapi berarti kau akan melewatkan keseruan memecahkan teka-teki, Chubb.",
  ui_story_5026_50261402_26_dialog_content = "Master pasti tahu cara memecahkannya. Chubb?",
  ui_story_5026_50261402_27_option_content = "Tentu saja aku tahu!",
  ui_story_5026_50261402_28_dialog_content = "Urutannya adalah: Farmer, Elder, Merchant, dan Scholar.",
  ui_story_5026_50261402_29_dialog_content = "Kau benar, Master.",
  ui_story_5026_50261402_30_option_content = "Ini bukan saatnya bermain-main.",
  ui_story_5026_50261402_31_dialog_content = "Chubb...",
  ui_story_5026_50261402_32_dialog_content = "Mari mulai.",
  ui_story_5026_50261402_33_option_content = "Lakukan telepati",
  ui_story_5026_50261402_34_dialog_content = "Secret Key berhasil disintesis. Nama login operator: \"PlayerName\", Chubb.",
  ui_story_5026_50261402_35_dialog_content = "Verifikasi sedang dalam proses. Silakan pegang Chubb yang berubah wujud menjadi Secret Key.",
  ui_story_5026_50261402_36_dialog_content = "Benda di tanganku ini bicara kepadaku?",
  ui_story_5026_50261402_37_dialog_content = "Bobotnya tak seberat kelihatannya.",
  ui_story_5026_50261402_38_dialog_content = "Verifikasi operator selesai, Chubb.",
  ui_story_5026_50261402_39_dialog_content = "Aku tak menyangka ia masih akan bicara seperti Chubb setelah berubah begini.",
  ui_story_5026_50261402_40_dialog_content = "Aku tak tahu ini namanya keren atau menggemaskan. Dua-duanya bukan kata yang tepat.",
  ui_story_5026_50261402_41_dialog_content = "Dua telinga lancip di ujung. Sepertinya pas dengan lubang di meja kerja ini.",
  ui_story_5026_50261402_42_dialog_content = "Apa ini... juga bisa digunakan sebagai senjata?",
  ui_story_5026_50261402_43_dialog_content = "Peringatan. Jangan gunakan untuk tujuan selain membuka terminal kontrol Hyacinth Tower, Chubb.",
  ui_story_5026_50261402_44_dialog_content = "Silakan masukkan Secret Key ke dalam lubang kunci untuk memulai koneksi manual, Chubb.",
  ui_story_5026_50261402_45_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_5026_50261402_46_dialog_content = "Terhubung.",
  ui_story_5026_50261402_47_dialog_content = "Berusaha membangun koneksi dengan Obelisk of Return... Gagal. Obelisk of Return offline.",
  ui_story_5026_50261402_48_dialog_content = "Status Sistem Pertahanan: Nonaktif.",
  ui_story_5026_50261402_49_dialog_content = "Operator dan terminal kontrol dalam mode telepati.",
  ui_story_5026_50261402_50_dialog_content = "Sebenarnya bagaimana cara kerja sistem pertahanan ini?",
  ui_story_5026_50261402_51_dialog_content = "Mengambil dokumen bantuan...",
  ui_story_5026_50261402_52_dialog_content = "Sistem pertahanan mengaktifkan <color=#FFB400>medan gaya</color> yang menyelubungi area hunian, dengan Hyacinth Tower di bagian tengahnya.",
  ui_story_5026_50261402_53_dialog_content = "Medan gaya ini akan menangkal semua bentuk musuh yang sudah ditandai.",
  ui_story_5026_50261402_54_dialog_content = "Medan gaya yang menghalangi musuh...",
  ui_story_5026_50261402_55_dialog_content = "Tak bisa dibandingkan dengan Chord of the Law, tapi kita toh tak punya pilihan lain.",
  ui_story_5026_50261402_56_dialog_content = "Target Musuh yang Ditetapkan Saat Ini: Aurorian.",
  ui_story_5026_50261402_57_dialog_content = "Harap berikan perintah.",
  ui_story_5026_50261402_58_dialog_content = "<size=45>!!!</size>",
  ui_story_5026_50261402_59_dialog_content = "Hoi, PlayerName? Halo?",
  ui_story_5026_50261402_60_dialog_content = "N-Nina! Aku bisa jelaskan. Yang baru saja kaudengar itu...",
  ui_story_5026_50261402_61_dialog_content = "Aku tak dengar apa pun setelah kau mengambil kuncinya.",
  ui_story_5026_50261402_62_dialog_content = "Kau memasukkan kuncinya tanpa bicara apa pun, dan tampangmu sendu sekali... Karena itulah aku...",
  ui_story_5026_50261402_63_dialog_content = "Kau tak dengar... apa pun?",
  ui_story_5026_50261402_64_dialog_content = "(Jadi, kunci dan terminal ini berkomunikasi denganku melalui telepati?)",
  ui_story_5026_50261402_65_dialog_content = "(Mungkin memang beginilah cara kaum Caelestite berkomunikasi dengan ciptaan mereka...)",
  ui_story_5026_50261402_66_dialog_content = "Apa ini... senjata Caelestite?",
  ui_story_5026_50261402_67_dialog_content = "Kelihatannya lumayan unik.",
  ui_story_5026_50261402_68_dialog_content = "Ini memang cuma kunci, tapi aku paham maksudmu, Sanae.",
  ui_story_5026_50261402_69_dialog_content = "Ini keempat Chubb tadi yang ditumpuk jadi satu!",
  ui_story_5026_50261402_70_dialog_content = "Ya ampun, imut sekali, aku sampai tak tahan!",
  ui_story_5026_50261402_71_dialog_content = "(Benar...)",
  ui_story_5026_50261402_72_dialog_content = "(Tak penting apa kebenarannya. Aku sudah ambil keputusan.)",
  ui_story_5026_50261402_73_dialog_content = "(Nah, aku harus kembali ke komunikasi telepatiku...)",
  ui_story_5026_50261402_74_dialog_content = "(Hmm... Sepertinya... Begitu sadar kalau kita bernapas, jadi sulit melakukannya lagi secara alamiah.)",
  ui_story_5026_50261402_75_dialog_content = "(Fokus!)",
  ui_story_5026_50261402_76_dialog_content = "Terminal System, apa kau bisa mendengarku?",
  ui_story_5026_50261402_77_dialog_content = "Menunggu input perintah.",
  ui_story_5026_50261402_78_dialog_content = "Tandai semua Eclipsite sebagai musuh. Aktifkan sistem pertahanan.",
  ui_story_5026_50261402_79_dialog_content = "Perintah terkonfirmasi. Target: Eclipsite.",
  ui_story_5026_50261402_80_dialog_content = "Progres Medan Gaya: 36%... 67%... 100%.",
  ui_story_5026_50261402_81_dialog_content = "<color=#FFB400>Memulai resonansi sonata</color>.",
  ui_story_5026_50261501_1_dialog_content = "Sudah selesai?",
  ui_story_5026_50261501_2_dialog_content = "Tanda di Hyacinth Tower berkedip, tapi Cloud Gardens tak menunjukkan reaksi.",
  ui_story_5026_50261501_3_dialog_content = "Jangan-jangan pengaturannya gagal? Teknologi ini kan sudah kuno.",
  ui_story_5026_50261501_4_dialog_content = "Yah... Walau aku tak bisa melihatnya, aku bisa merasakan sekarang ada sesuatu yang berbeda.",
  ui_story_5026_50261501_5_dialog_content = "Sistem pertahanan sudah aktif. Medan gaya itu akan menangkal Eclipsite, Chubb.",
  ui_story_5026_50261501_6_dialog_content = "Luar biasa...",
  ui_story_5026_50261501_7_dialog_content = "Bukan hanya Eclipsite yang ada di luar, melainkan juga Eclipsite yang ada di dalam, Chubb.",
  ui_story_5026_50261501_8_dialog_content = "Apa? Kalau mereka ditangkal oleh medan gaya itu, berarti...",
  ui_story_5026_50261501_9_dialog_content = "Mereka akan berkumpul di pusat Cloud Gardens, yaitu di Hyacinth Tower, Chubb.",
  ui_story_5026_50261501_10_dialog_content = "Mestinya kauberi tahu aku soal itu sebelum aku mengaktifkan pertahanannya!",
  ui_story_5026_50261501_11_dialog_content = "PlayerName tidak tanya. Chubb.",
  ui_story_5026_50261501_12_dialog_content = "A... Aku mulai curiga, jangan-jangan kau punya niat tersembunyi di balik penampilanmu yang imut itu.",
  ui_story_5026_50261501_13_dialog_content = "Aku tidak paham. Tolong ulangi, Chubb?",
  ui_story_5026_50261501_14_dialog_content = "Tak usah pikirkan itu. Dari mana sumber tenaga sistem pertahanan ini? Sistemnya tak akan mendadak kehabisan daya, 'kan?",
  ui_story_5026_50261501_15_dialog_content = "Energi kinetik yang dihasilkan dari gerakan para Chubb menyediakan daya untuk Chubb lain dan Hyacinth Tower. Chubb.",
  ui_story_5026_50261501_16_dialog_content = "Rupanya kalian bukan semata berkeliaran tanpa tujuan...",
  ui_story_5026_50261501_17_dialog_content = "Kalau begitu, apa kalian bisa bertarung?",
  ui_story_5026_50261501_18_dialog_content = "Mungkin, misalnya, dengan menggabungkan diri kalian menjadi satu Chubb raksasa melalui telepati...",
  ui_story_5026_50261501_19_dialog_content = "Tidak, Chubb.",
  ui_story_5026_50261501_20_dialog_content = "Sekarang baru kau menjawab cepat!",
  ui_story_5026_50261501_21_dialog_content = "Setidaknya, tak akan ada lagi Eclipsite yang menyerang tempat ini, 'kan?",
  ui_story_5026_50261501_22_dialog_content = "Jadi, jangan bertampang sedih begitu, dong. Kau sudah berusaha semampumu, PlayerName.",
  ui_story_5026_50261501_23_dialog_content = "Apa sekarang ini satu-satunya pilihanku hanyalah menyewa tentara bayaran dari Umbraton...?",
  ui_story_5026_50261501_24_dialog_content = "Utangku terus menumpuk... Kalau Vice sampai tahu, dia pasti syok...",
  ui_story_5026_50261501_25_dialog_content = "Yah, aku sudah berusaha semampuku. Tak ada yang perlu dikeluhkan.",
  ui_story_5026_50261501_26_dialog_content = "Kalau saja aku memperhatikan masalah keamanan Cloud Gardens lebih awal, semua ini tak akan terjadi.",
  ui_story_5026_50261501_27_dialog_content = "PlayerName…",
  ui_story_5026_50261501_28_dialog_content = "Nona Nina, kita harus kembali ke Umbraton sekarang.",
  ui_story_5026_50261501_29_dialog_content = "Sekarang? Tapi, PlayerName sedang kesulitan!",
  ui_story_5026_50261501_30_dialog_content = "Kita hanya perlu menuju medan gaya dan menunggu bantuan Lady Bethel.",
  ui_story_5026_50261501_31_dialog_content = "Kalau bisa melakukannya, berarti Eclipsite itu mestinya tak lagi jadi ancaman.",
  ui_story_5026_50261501_32_dialog_content = "Maafkan kalau kata-kataku terlalu terus terang, tapi sekarang ini baik aku maupun kau sudah tak bisa berbuat apa-apa lagi.",
  ui_story_5026_50261501_33_dialog_content = "Bisa-bisanya kaubilang begitu!? Benar-benar tak berperasaan, bahkan kalaupun itu kau yang bilang, Minos.",
  ui_story_5026_50261501_34_dialog_content = "Kalaupun kita tak bisa membasmi semua Eclipsite itu, kita tetap harus berusaha sebisa mungkin sampai bala bantuan datang!",
  ui_story_5026_50261501_35_dialog_content = "Kalau tidak, PlayerName pasti akan bangkrut, jadi gelandangan, dan terpaksa menjual para Chubb itu agar punya uang!",
  ui_story_5026_50261501_36_dialog_content = "K-Kurasa tak akan sampai seperti itu...",
  ui_story_5026_50261501_37_dialog_content = "Kau tak mahir bertarung, Nona Nina. Memangnya kau bisa bantu apa?",
  ui_story_5026_50261501_38_dialog_content = "Aku tak mau kau terluka dalam pertarungan yang tak perlu.",
  ui_story_5026_50261501_39_dialog_content = "Pertarungan yang tak perlu?",
  ui_story_5026_50261501_40_dialog_content = "Apa pun bantuan yang dibutuhkan PlayerName, berarti itu adalah hal yang perlu bagiku!",
  ui_story_5026_50261501_41_dialog_content = "Cara paling efektif dan efisien adalah menyerahkan tugas itu kepada profesional yang cakap.",
  ui_story_5026_50261501_42_dialog_content = "Dengan kata lain, kaukira aku ini begitu rapuh dan ringkih dan pasti bakal terluka hanya karena segelintir Eclipsite?",
  ui_story_5026_50261501_43_dialog_content = "Kau malah memelintir kata-kataku, Nona. Aku hanya memintamu menepati janjimu.",
  ui_story_5026_50261501_44_dialog_content = "Kalau kau masih bersikeras, coba yakinkan aku melalui tindakanmu.",
  ui_story_5026_50261501_45_dialog_content = "Baiklah. Kalau memang itu maumu.",
  ui_story_5026_50261501_46_dialog_content = "Keluarkan senjatamu.",
  ui_story_5026_50261501_47_dialog_content = "Akan kutunjukkan seberapa jauh peningkatan keterampilan bertarungku.",
  ui_story_5026_50261501_48_dialog_content = "Aku senang mendengarnya. Tapi, tak ada pengaruhnya walaupun kalian semua bersatu untuk melawanku.",
  ui_story_5026_50261501_49_option_content = "Kenapa jadi begini!?",
  ui_story_5026_50261501_50_dialog_content = "N-Nina! Biar kubantu!",
  ui_story_5026_50261501_51_option_content = "Jangan lagi bertarung demi aku!",
  ui_story_5026_50261501_52_dialog_content = "Bukan DEMI kau! Aku hanya tak suka sikapnya yang seakan-akan dia selalu melakukan hal terbaik untukku.",
  ui_story_5026_50261501_53_dialog_content = "Sepertinya aku tak punya pilihan lain.",
  ui_story_5026_50261502_1_dialog_content = "Seram sekali... Membelah tanah bagaikan pisau panas memotong mentega...",
  ui_story_5026_50261502_2_dialog_content = "Apa amunisimu cukup, Nona?",
  ui_story_5026_50261502_3_dialog_content = "<size=45>Berhentilah meremehkanku!</size>",
  ui_story_5026_50261502_4_dialog_content = "Dia berusaha memancing amarahmu, Nina! Jangan sekarang!",
  ui_story_5026_50261502_5_dialog_content = "Sanae, ke kanan!",
  ui_story_5026_50261502_6_dialog_content = "S-Siap! Kau sudah siap, Manae?",
  ui_story_5026_50261502_7_dialog_content = "Aku tak akan melewatkan kesempatan untuk mengalahkan atasanku!",
  ui_story_5026_50261502_8_dialog_content = "Hindari saja serangannya yang berikutnya...",
  ui_story_5026_50261502_9_dialog_content = "<size=45>Cukup sudah! Sekarang saatnya!</size>",
  ui_story_5026_50261502_10_dialog_content = "A-Aku kelelahan...",
  ui_story_5026_50261502_11_dialog_content = "Bagaimana sekarang? S-Sudah puas?",
  ui_story_5026_50261502_12_dialog_content = "(Walaupun aku bisa sedikit memperkirakan geraknya melalui kemampuanku... Tetap saja sulit mengimbanginya.)",
  ui_story_5026_50261502_13_dialog_content = "(Kami menang tipis... Aku hanya berharap semoga aku tak perlu melawan Minos lagi...)",
  ui_story_5026_50261502_14_dialog_content = "Aku terkesan.",
  ui_story_5026_50261502_15_dialog_content = "Nona Nina, Sanae, dan PlayerName...",
  ui_story_5026_50261502_16_dialog_content = "Aksi kalian jauh melampaui harapanku.",
  ui_story_5026_50261502_17_dialog_content = "Sudah lama sekali aku ingin merasakan kekalahan.",
  ui_story_5026_50261502_18_dialog_content = "Selamat, Nona Nina. Kau menang.",
  ui_story_5026_50261502_19_dialog_content = "Dalam pertarungan ini, sekaligus dalam taruhan kita.",
  ui_story_5026_50261502_20_dialog_content = "Kalau kau bisa mengalahkanku dalam \"<color=#FFB400>satu hal saja</color> di Cloud Gardens\", kau menang.",
  ui_story_5026_50261502_21_dialog_content = "Pertarungan ini sangat memenuhi syarat itu.",
  ui_story_5026_50261502_22_dialog_content = "Lain kali aku akan lebih berhati-hati saat membuat kesepakatan lisan.",
  ui_story_5026_50261502_23_dialog_content = "Minos, kau...",
  ui_story_5026_50261502_24_dialog_content = "Tolong jaga bicaramu, Nona. Jangan lupa bersikap elegan seperti layaknya wanita bangsawan.",
  ui_story_5026_50261502_25_dialog_content = "Aku kan belum omong apa-apa!",
  ui_story_5026_50261502_26_dialog_content = "Ya, aku tidak menggunakan segenap kekuatanku dalam pertempuran kita.",
  ui_story_5026_50261502_27_dialog_content = "Tapi, tetap saja kau berhasil membuktikan bahwa kau bisa menjaga dirimu di negeri penuh bahaya ini.",
  ui_story_5026_50261502_28_dialog_content = "Rekan-rekan yang kaupilih bukanlah para pelayan, melainkan teman-teman yang akan selalu mendampingimu.",
  ui_story_5026_50261502_29_dialog_content = "Tuan Minos...",
  ui_story_5026_50261502_30_dialog_content = "Aku akan melaporkannya kepada Master Andersen.",
  ui_story_5026_50261502_31_dialog_content = "Sesuai kesepakatan kita, sekarang aku harus meninggalkanmu, tapi aku benar-benar minta maaf.",
  ui_story_5026_50261502_32_dialog_content = "Seperti yang kaulihat, saat bertarung tadi, aku mengakibatkan kerusakan parah pada Cloud Gardens.",
  ui_story_5026_50261502_33_dialog_content = "Padahal aku ini tamu... tapi aku malah menghancurkan rumah PlayerName dan para Chubb...",
  ui_story_5026_50261502_34_dialog_content = "Walaupun kalian cuma majikan sekaligus muridku untuk sementara, tetap saja aku sudah mengkhianati kepercayaan kalian.",
  ui_story_5026_50261502_35_dialog_content = "Tuan Navigator, aku benar-benar minta maaf atas hal ini.",
  ui_story_5026_50261502_36_dialog_content = "Aku tahu, tak mungkin aku bisa mengganti rugi atas kerusakan yang kutimbulkan pada barang-barang yang sangat kausayangi itu...",
  ui_story_5026_50261502_37_dialog_content = "Tapi, izinkan aku untuk menebus kesalahanku dengan memperbaiki Cloud Gardens.",
  ui_story_5026_50261502_38_dialog_content = "Jangan khawatir. Aku cukup mahir membersihkan semua jenis noda, sampah, dan hama.",
  ui_story_5026_50261502_39_dialog_content = "Yang, tentu saja, mencakup para tamu tak diundang di Cloud Gardens.",
  ui_story_5026_50261502_40_dialog_content = "Maksudmu... Kau akan mengatasi semua Eclipsite itu?",
  ui_story_5026_50261502_41_dialog_content = "Memangnya kau tak mau terima permintaan maafku?",
  ui_story_5026_50261502_42_dialog_content = "Kuterima, tentu saja. Hanya saja...",
  ui_story_5026_50261502_43_dialog_content = "Tak usah bilang apa-apa lagi. Aku hanya ingin menunjukkan ketulusanku.",
  ui_story_5026_50261502_44_dialog_content = "(Kok aku jadi merasa seperti dipermainkan, ya...)",
  ui_story_5026_50261502_45_dialog_content = "(Tapi rasanya ini malah bermanfaat?)",
  ui_story_5026_50261502_46_dialog_content = "Kau pasti lelah.",
  ui_story_5026_50261502_47_dialog_content = "Sanae, tolong antar mereka ke Hyacinth Tower untuk istirahat. Mejanya sudah kutata.",
  ui_story_5026_50261502_48_dialog_content = "Siap, Pak!",
  ui_story_5026_50261502_49_dialog_content = "Anu... Tuan Navigator, Nina...",
  ui_story_5026_50261502_50_dialog_content = "Mau... minum secangkir teh dulu?",
  ui_story_5026_50261601_1_dialog_content = "Begitulah laporan lengkap perjalananku ke Cloud Gardens.",
  ui_story_5026_50261601_2_dialog_content = "Misi gagal karena keteledoranku sendiri. Aku tak akan cari-cari alasan.",
  ui_story_5026_50261601_3_dialog_content = "Tapi, aku yakin Nona Nina bisa mengambil keputusan sendiri.",
  ui_story_5026_50261601_4_dialog_content = "Tekad dan kerja kerasnya, semangat dan ketekunannya, persis seperti Anda.",
  ui_story_5026_50261601_5_dialog_content = "Minos...",
  ui_story_5026_50261601_6_dialog_content = "Ya, Tuan?",
  ui_story_5026_50261601_7_dialog_content = "Saat Nina masih kecil, dia suka berlari melintasi halaman hanya untuk menunjukkan sekuntum bunga cantik yang ditemukannya.",
  ui_story_5026_50261601_8_dialog_content = "Tapi, setelah dia besar... dia bahkan tak mengizinkanku membeli hasil karyanya.",
  ui_story_5026_50261601_9_dialog_content = "Salahkah kalau aku ingin punya sesuatu yang dirancang dan dibuatnya sendiri?",
  ui_story_5026_50261601_10_dialog_content = "Aku ingin punya paling tidak dua set dari setiap jenis dan warna untuk diriku sendiri... Satu untuk dikoleksi, satu lagi untuk dipakai...",
  ui_story_5026_50261601_11_dialog_content = "Satu set lagi untuk kupamerkan di depan Istvan.",
  ui_story_5026_50261601_12_dialog_content = "Tambah tiga set lagi untuk jaga-jaga, kalau-kalau ada yang rusak atau hilang.",
  ui_story_5026_50261601_13_dialog_content = "Mestinya juga tak masalah kalau aku diam-diam menyuruh orang untuk membelikannya untukku...",
  ui_story_5026_50261601_14_dialog_content = "Satu-satunya kesalahanku adalah... membiarkan dia tahu soal itu.",
  ui_story_5026_50261601_15_dialog_content = "Sudah kuduga! Rupanya kau sama sekali belum introspeksi diri atas tindakanmu!",
  ui_story_5026_50261601_16_dialog_content = "Nina? Kau sudah pulang? Minos, apa mataku berhalusinasi?",
  ui_story_5026_50261601_17_dialog_content = "Tidak, Tuan.",
  ui_story_5026_50261601_18_dialog_content = "Satu-satunya alasan aku tak mau Ayah membeli hasil karyaku adalah karena...",
  ui_story_5026_50261601_19_dialog_content = "Ayah selalu ingin memamerkan karya-karyaku yang belum layak itu di hadapan orang-orang dalam semua acara sosial!",
  ui_story_5026_50261601_20_dialog_content = "Itu sangat memalukan!",
  ui_story_5026_50261601_21_dialog_content = "Kau terlalu merendah, Sayang. Yang kubilang tadi adalah yang sebenarnya.",
  ui_story_5026_50261601_22_dialog_content = "Lagi pula, memangnya Ayah perlu sampai memborong semua barang di tokoku?",
  ui_story_5026_50261601_23_dialog_content = "Semua penjaga dan pengawal kita pantas mendapatkan senjata yang indah sekaligus praktis itu...",
  ui_story_5026_50261601_24_dialog_content = "Aku hanya ingin membuatmu bangga dengan mengungguli Bethel...",
  ui_story_5026_50261601_25_dialog_content = "Saat masih seusiaku, tindak-tanduk Minos sangat membantumu, 'kan?",
  ui_story_5026_50261601_26_dialog_content = "Kau tak perlu membuktikan apa pun kepadaku, atau membandingkan dirimu dengan siapa pun.",
  ui_story_5026_50261601_27_dialog_content = "Aku sudah bangga kepadamu sejak kau lahir.",
  ui_story_5026_50261601_28_dialog_content = "Tapi, ada alasan lain! Aku juga mau meraih kesuksesan sendiri!",
  ui_story_5026_50261601_29_dialog_content = "Aku ingin hasil desainku jadi bagian dari kehidupan semua orang.",
  ui_story_5026_50261601_30_dialog_content = "Agar bisa mencapainya, aku butuh masukan nyata dari pelanggan, entah itu saran maupun keluhan.",
  ui_story_5026_50261601_31_dialog_content = "Itu satu-satunya cara agar bisnisku bisa maju.",
  ui_story_5026_50261601_32_dialog_content = "<anim type=Shake>Nina... Kau benar-benar sudah dewasa...</anim>",
  ui_story_5026_50261601_33_dialog_content = "<size=45>K-Kenapa kau malah menangis?</size>Ayah, kenapa dramatis begitu... Ayah membuatku malu.",
  ui_story_5026_50261601_34_dialog_content = "Aku hanya berharap semoga ibumu bisa mendengar kata-katamu barusan.",
  ui_story_5026_50261601_35_dialog_content = "Oh, tadi aku sudah bilang belum bahwa aku bertemu seorang Caelestite menyenangkan di Eraveil?",
  ui_story_5026_50261601_36_dialog_content = "Kalau bukan karena dia, tak mungkin aku sadar betapa kekanak-kanakannya sikapku dalam berbisnis.",
  ui_story_5026_50261601_37_dialog_content = "Bahwa aku butuh waktu untuk berpikir dan menenangkan diri... dan memberitahukan isi hatiku kepadamu.",
  ui_story_5026_50261601_38_dialog_content = "Caranya berjibaku mempertahankan sesuatu dengan usahanya sendiri...",
  ui_story_5026_50261601_39_dialog_content = "Membuatku sedikit sadar akan pandanganmu tentangku.",
  ui_story_5026_50261601_40_dialog_content = "Cih! Lalu, kau! Meski aku langsung tahu tujuanmu yang sebenarnya, aku harus mengatakannya!",
  ui_story_5026_50261601_41_dialog_content = "Dari caramu mengejekku, Minos, kau benar-benar pintar membuatku jengkel!",
  ui_story_5026_50261601_42_dialog_content = "Terima kasih atas pujianmu.",
  ui_story_5026_50261601_43_dialog_content = "Itu bukan pujian, tahu!",
  ui_story_5026_50261601_44_dialog_content = "Terserah, deh... Mungkin memang bisa dianggap pujian.",
  ui_story_5026_50261601_45_dialog_content = "Si Caelestite itu juga ditemani beberapa Chubb imut. Andai saja aku boleh bawa pulang satu...",
  ui_story_5026_50261601_46_dialog_content = "Lalu, Sanae mengajariku cara menangkap ikan! Selain itu...",
  ui_story_5026_50261601_47_dialog_content = "Oh! Aku mau ganti baju dulu. Aku akan segera kembali! Kosongkan jadwalmu untukku!",
  ui_story_5026_50261601_48_dialog_content = "Minos.",
  ui_story_5026_50261601_49_dialog_content = "Ya, Tuan?",
  ui_story_5026_50261601_50_dialog_content = "Memangnya ada apa dengan si PlayerName itu?",
  ui_story_5026_50261601_51_dialog_content = "PlayerName mungkin memang masih muda, tapi aku yakin dia laki-laki yang baik dan jujur.",
  ui_story_5026_50261601_52_dialog_content = "Cih! Aku tak percaya Caelestite terakhir adalah orang yang cinta damai.",
  ui_story_5026_50261601_53_dialog_content = "Kemampuan bawaan mereka membuat mereka tak bisa hidup terasing dari dunia.",
  ui_story_5026_50261601_54_dialog_content = "Padahal dunia ini tak akan bersikap baik kepada orang-orang yang jujur dan baik hati.",
  ui_story_5026_50261601_55_dialog_content = "Benar sekali, Tuan.",
  ui_story_5026_50261601_56_dialog_content = "Kedamaian hanya bisa dipertahankan oleh orang yang punya kuasa lebih besar.",
  ui_story_5026_50261601_57_dialog_content = "Atau... dengan berpihak pada orang yang punya kuasa lebih besar.",
  ui_story_5026_50261601_58_dialog_content = "Tak usah pikirkan itu semua... Aku toh sudah pensiun. Kuserahkan saja semua urusan duniawi ini kepada Shadowlord. Yang lebih penting...",
  ui_story_5026_50261601_59_dialog_content = "Nina yang kusayangi sepertinya sangat menghargai dan peduli kepada Caelestite ini. Benar begitu?",
  ui_story_5026_50261601_60_dialog_content = "Seperti biasa, semua laki-laki yang berinteraksi dengan Nona Nina sudah melalui tahap penyelidikan dan pengamatan menyeluruh.",
  ui_story_5026_50261601_61_dialog_content = "Kuberi kau waktu tiga menit. Aku butuh semua informasi tentang bocah itu, termasuk apa saja yang diberitakan di Umbraton Daily.",
  ui_story_5026_50261601_62_dialog_content = "Baiklah.",
  ui_story_5026_50261601_63_dialog_content = "Sunyi sekali.",
  ui_story_5026_50261601_64_dialog_content = "(Tak lama setelah Minos pergi, Nina dan Sanae juga kembali ke Umbraton.)",
  ui_story_5026_50261601_65_dialog_content = "(Semoga Nina bisa berbaikan dengan ayahnya.)",
  ui_story_5026_50261601_66_dialog_content = "(Tapi... dia masih bersikeras menyusun rencana penaklukannya...)",
  ui_story_5026_50261601_67_dialog_content = "Ada banyak hal yang harus kupahami untuk memadukan idemu tentang \"tempat bernaung yang aman\" itu dengan rencanaku.",
  ui_story_5026_50261601_68_dialog_content = "Itu alasanmu awalnya menolak rencanaku, 'kan?",
  ui_story_5026_50261601_69_dialog_content = "Ketidakmampuanku untuk membuat mitraku percaya kepadaku menunjukkan bahwa aku masih sangat kurang dewasa.",
  ui_story_5026_50261601_70_dialog_content = "Kalau benar begitu, aku tak boleh buang-buang waktu lagi di tempat yang serbasantai ini.",
  ui_story_5026_50261601_71_dialog_content = "Sudah kuputuskan, aku akan pulang dan mempelajari manajemen bisnis dari ayahku.",
  ui_story_5026_50261601_72_dialog_content = "Tapi, aku janji kepadamu, setelah aku selesai belajar semua yang perlu kupahami, aku akan kembali ke sini dan memintamu lagi untuk menjadi mitraku.",
  ui_story_5026_50261601_73_dialog_content = "J-Jangan sampai kau lupa itu!",
  ui_story_5026_50261601_74_dialog_content = "(Mungkinkah Minos memutuskan untuk memberitahuku siapa Nina sesungguhnya karena dia melihat pengaruhku terhadap Nina...?)",
  ui_story_5026_50261601_75_dialog_content = "(Kalau benar begitu... Berarti, dia bukan hanya menguji Nina, melainkan juga aku...)",
  ui_story_5026_50261601_76_dialog_content = "(Mungkin memang dia sudah merencanakannya sejak kami pertama bertemu.)",
  ui_story_5026_50261601_77_dialog_content = "(Seram sekali si pelayan itu...)",
  ui_story_5026_50261601_78_dialog_content = "(Pada akhirnya, aku tak berhasil merekrut manajer baru, tapi para Chubb itu mestinya sudah cukup untuk membantuku mengurus Cloud Gardens.)",
  ui_story_5026_50261601_79_dialog_content = "(Aku juga jadi tahu beberapa hal sejak mengaktifkan sistem pertahanan Hyacinth Tower.)",
  ui_story_5026_50261601_80_dialog_content = "Nah, kalau begitu, aku harus mulai mengurus kerjaan di Cloud Gardens.",
  ui_story_5026_50261601_81_dialog_content = "Pertama… apa tadi namanya? Daftar karyawan?",
  ui_story_5026_50261601_82_dialog_content = "Kenapa kau sendirian saja di sini, PlayerName? Mana Nina dan yang lainnya?",
  ui_story_5026_50261601_83_dialog_content = "Setelah mendengar kabar tentang situasimu, banyak temanmu bersedia membantumu.",
  ui_story_5026_50261601_84_dialog_content = "Memang banyak yang tak bisa kemari karena sudah ada keperluan lain, tapi aku berhasil mengumpulkan beberapa orang yang bisa membantu.",
  ui_story_5026_50261601_85_dialog_content = "Tapi, sepertinya kau sudah mengatasi Eclipsite itu.",
  ui_story_5026_50261601_86_dialog_content = "Ceritanya panjang... Memangnya kau tak menerima pesanku, Bethel?",
  ui_story_5026_50261601_87_dialog_content = "Akan kuganti biaya perjalananmu...",
  ui_story_5026_50261601_88_dialog_content = "Kalau ada pekerjaan yang perlu dituntaskan, jangan sungkan menghubungiku.",
  ui_story_5026_50261601_89_dialog_content = "Dulu kau membantu kami saat insiden Blue Lion Guild. Aku sangat ingin membalas bantuanmu.",
  ui_story_5026_50261601_90_dialog_content = "Aku hanya bertindak sebagaimana mestinya. Kau tak berutang apa pun kepadaku...",
  ui_story_5026_50261601_91_dialog_content = "Kau baik sekali, PlayerName.",
  ui_story_5026_50261601_92_dialog_content = "Kalau begitu, anggap saja begini: Membantu Caelestite Terakhir untuk membangun kembali rumahnya dan menetap di sana tentunya bisa mendongkrak reputasi White Flame Mercenaries.",
  ui_story_5026_50261601_93_dialog_content = "Bisa dibilang, kita sama-sama untung.",
  ui_story_5026_50261601_94_dialog_content = "Baiklah. Kalau begitu, sebelumnya, terima kasih atas bantuanmu.",
  ui_story_5026_50261601_95_dialog_content = "Oh, tugasnya sudah beres?",
  ui_story_5026_50261601_96_dialog_content = "Karena aku sudah sampai di sini, sekalian saja kujalankan bisnisku... Kurasa sebuah lukisan indah pasti cocok dengan rumah barumu, PlayerName.",
  ui_story_5026_50261601_97_dialog_content = "Sebagai bos, kau butuh sentuhan seni agar tempat ini tampak lebih bernuansa, sekaligus untuk menunjukkan seleramu.",
  ui_story_5026_50261601_97X1_dialog_content = "Kalau kau tak suka lukisan, bagaimana kalau patung buatan seniman yang sedang naik daun di Umbraton?",
  ui_story_5026_50261601_97X2_dialog_content = "Cih, sebagai anjing, mau tak mau harus kuakui bahwa dia lebih tampan.",
  ui_story_5026_50261601_98_dialog_content = "Terima kasih atas tawaranmu, tapi tidak.",
  ui_story_5026_50261601_99_dialog_content = "Jangan bilang begitu! Coba lihat dulu brosur ini. Ini semua lukisan indah karya para seniman ternama...",
  ui_story_5026_50261601_100_dialog_content = "Wow!",
  ui_story_5026_50261601_101_dialog_content = "Ini rumah Puppy, 'kan? Luas sekali!",
  ui_story_5026_50261601_102_dialog_content = "Bukan rumah Puppy. Ini rumah PlayerName.",
  ui_story_5026_50261601_103_dialog_content = "Rumah baru Puppy lebih luas daripada Colossus? Aku jadi ingin lari-lari mengitari rumah ni.",
  ui_story_5026_50261601_104_dialog_content = "Bagaimana kalau main petak umpet saja?",
  ui_story_5026_50261601_105_dialog_content = "Ayo main petak umpet!",
  ui_story_5026_50261601_106_dialog_content = "Kalian berdua, hati-hati! Jangan sampai menabrak barang-barang!",
  ui_story_5026_50261601_107_dialog_content = "Silakan saja kalau kau mau menghajar dua orang yang suka mendompleng keuntungan ini, tapi hati-hati dengan reliknya. Tempat ini adalah reruntuhan kuno milik kaum Caelestite.",
  ui_story_5026_50261601_108_dialog_content = "Relik Caelestite adalah barang yang cukup langka, bahkan di Umbraton sekalipun. Aku yakin setiap relik itu pasti akan menarik perhatian kalau dipajang di tokoku nanti.",
  ui_story_5026_50261601_109_dialog_content = "Memang ada sejumlah barang di Museum, tapi aku tak yakin apa itu bisa dianggap relik.",
  ui_story_5026_50261601_110_dialog_content = "Walaupun tak ada kontrak sewa tentara bayaran, bisa melihat koleksimu saja sudah cukup membuat perjalananku terasa sepadan.",
  ui_story_5026_50261601_111_dialog_content = "Aku bisa tunjukkan jalannya! Chubb!",
  ui_story_5026_50261601_112_dialog_content = "Waow... Rasio yang sangat indah... Aku merasakan ada sesuatu yang berharga dalam dirimu.",
  ui_story_5026_50261601_113_dialog_content = "Chubb?",
  ui_story_5026_50261601_114_dialog_content = "Tak usah pikirkan Museumnya. Keberatan tidak kalau aku memeriksamu sebentar?",
  ui_story_5026_50261601_115_dialog_content = "Fyuh... Kedamaian yang hanya sejenak ini terasa ibarat mimpi...",
  ui_story_5026_50261601_116_dialog_content = "Selalu saja ada hal menarik dari dirimu, Navigator pemberani.",
  ui_story_5026_50261601_117_dialog_content = "Kleken!",
  ui_story_5026_50261601_118_dialog_content = "Kapan bahtera baru ini akan membawamu mengarungi laut penuh gejolak?",
  ui_story_5026_50261601_119_dialog_content = "Taman di langit menyelam ke dalamnya lautan. Pasti akan jadi pemandangan menakjubkan!",
  ui_story_5026_50261601_120_dialog_content = "Aku akan berusaha sebaik mungkin agar itu tak pernah terjadi...",
  ui_story_5026_50261601_121_dialog_content = "Ha... Kali ini, dia omong melantur apa lagi?",
  ui_story_5026_50261601_122_dialog_content = "Kau juga, PlayerName. Kau masih saja tampak kikuk seperti biasanya.",
  ui_story_5026_50261601_123_dialog_content = "Hydrad? Aku tak menyangka kau juga akan ke sini...",
  ui_story_5026_50261601_124_dialog_content = "Aku mau pergi sekarang.",
  ui_story_5026_50261601_125_dialog_content = "Tapi, kau kan baru saja sampai!",
  ui_story_5026_50261601_126_dialog_content = "Aku ke sini bukan karena aku ingin! Si gurita picik itu bohong kepadaku, katanya bos di sini punya pekerjaan untukku.",
  ui_story_5026_50261601_127_dialog_content = "Tempat ini terlalu luas dan terbuka. Shadow Wolf jadi resah, sama seperti anjing-anjing di sini.",
  ui_story_5026_50261601_128_dialog_content = "Mau bagaimana lagi. Memang itu sifat mereka!",
  ui_story_5026_50261601_129_dialog_content = "<size=40>Ayo! Ayo! Ayo main petak umpet!</size>",
  ui_story_5026_50261601_130_dialog_content = "<size=45>Fufufu!</size>",
  ui_story_5026_50261601_131_dialog_content = "<size=50>Ribut sekali! Menjauhlah dariku!</size>",
  ui_story_5026_50261601_132_dialog_content = "Situasi di sini... tak seperti dugaanku.",
  ui_story_5026_50261601_133_dialog_content = "Kaget, ya? Kalau tak ada pekerjaan yang harus dilakukan, para profesional di Umbraton itu cuma anak-anak yang suka berbuat onar.",
  ui_story_5026_50261601_134_dialog_content = "Bukankah menyenangkan melihat anak-anak anjing bermain dan kejar-kejaran di tanah lapang?",
  ui_story_5026_50261601_135_dialog_content = "Sepertinya keributan ini masih akan berlangsung cukup lama.",
  ui_story_5026_50261601_136_dialog_content = "Anu... Kalau kalian tak buru-buru...",
  ui_story_5026_50261601_137_dialog_content = "Bagaimana kalau kita minum teh dulu?",
  ui_story_5026_50261601_138_dialog_content = "<color=#e8d9bb>Di Bridge di Soroz, beberapa hari kemudian</color>",
  ui_story_5026_50261601_139_dialog_content = "Jadi... PlayerName ternyata mengalami banyak sekali hal selama kita tak ada di sini.",
  ui_story_5026_50261601_140_dialog_content = "Aku ikut senang, tapi aku juga agak kecewa karena alasan tertentu...",
  ui_story_5026_50261601_141_dialog_content = "Vice…",
  ui_story_5026_50261601_142_dialog_content = "Kalau kau punya kesempatan untuk menciptakan \"Pedang Chubb\" itu lagi suatu hari nanti, kau harus menunjukkannya kepadaku!",
  ui_story_5026_50261601_143_dialog_content = "Kau kecewa gara-gara itu!?",
  ui_story_5026_50261601_144_dialog_content = "Medan gaya... Aku tak tahu Hyacinth Tower punya sistem seperti itu.",
  ui_story_5026_50261601_145_dialog_content = "Dulu aku juga agak khawatir tentang keamanan di Cloud Gardens.",
  ui_story_5026_50261601_146_dialog_content = "Untungnya, semuanya sudah teratasi sebelum sempat ada kerusakan permanen.",
  ui_story_5026_50261601_147_dialog_content = "Kau mampu melindungi rumahmu sendirian. Bagus, PlayerName.",
  ui_story_5026_50261601_148_dialog_content = "Terima kasih, Carleen.",
  ui_story_5026_50261601_149_dialog_content = "Tapi, aku tak melakukannya sendirian. Aku tak mungkin bisa melakukannya tanpa bantuan Nina dan yang lainnya.",
  ui_story_5026_50261601_150_dialog_content = "Seperti halnya Cloud Gardens yang tak mungkin ada di sini sekarang tanpa bantuan semuanya.",
  ui_story_5026_50261601_151_dialog_content = "...",
  ui_story_5026_50261601_152_dialog_content = "Setelah aku tahu lebih banyak tentang Caelestite di Obelisk of Return dan Cloud Gardens...",
  ui_story_5026_50261601_153_dialog_content = "Aku jadi terpesona akan kaumku, dan jadi meragukan diriku sendiri.",
  ui_story_5026_50261601_154_dialog_content = "Tapi, karena sudah bertempur bersamamu dan banyak kawan Aurorian lain, aku jadi sadar sesuatu.",
  ui_story_5026_50261601_155_dialog_content = "Jati diriku tidak ditentukan oleh garis keturunan atau kemampuanku...",
  ui_story_5026_50261601_156_dialog_content = "Tapi oleh kehendak dan pilihanku.",
  ui_story_5026_50261601_157_dialog_content = "Dengan kalian di sisiku, aku tak akan pernah mengambil keputusan yang suatu saat nanti akan kusesali.",
  ui_story_5026_50261601_158_dialog_content = "Nasib Eraveil tak akan terulang lagi.",
  ui_story_5026_50261601_159_dialog_content = "Kita tak akan terlindung atau mendapatkan kedamaian dengan mengasingkan diri.",
  ui_story_5026_50261601_160_dialog_content = "Kita hanya bisa mencapainya dengan memiliki teman.",
  ui_story_5026_50261601_161_dialog_content = "Aku mau tinggal di tanah ini bersama kawan-kawan Aurorianku.",
  ui_story_5026_50261601_162_dialog_content = "Aku mau tempat ini jadi tempat bernaung yang aman, dan semua orang bisa menemukan kedamaian di sini.",
  ui_story_5026_50261601_163_dialog_content = "<color=#FFB400>Rumah sejati</color>.",
  ui_story_5026_50261601_164_dialog_content = "PlayerName…",
  ui_story_5026_50261601_165_dialog_content = "Pidatomu sangat menyentuh. Akhirnya kau bisa bersikap layaknya seorang bos.",
  ui_story_5026_50261601_166_dialog_content = "B-benarkah?",
  ui_story_5026_50261601_167_dialog_content = "Oh, omong-omong, Minos mengajari para Chubb cara yang lebih efektif untuk mengelola Cloud Gardens.",
  ui_story_5026_50261601_168_dialog_content = "Bethel juga bilang bahwa Guild ingin bekerja sama denganku dan menjual barang-barang dari Cloud Gardens di Umbraton.",
  ui_story_5026_50261601_169_dialog_content = "Kalau semuanya lancar, tak lama lagi kita tak perlu khawatir kehabisan Nightium.",
  ui_story_5026_50261601_170_dialog_content = "Oh, soal itu...",
  ui_story_5026_50261601_171_dialog_content = "Sementara kau pergi, aku menerima tagihan dari Sheol untuk membayar info intel darinya, Vice.",
  ui_story_5026_50261601_172_dialog_content = "Baiklah. Tak usah khawatir, biar kutangani urusan akuntansinya. Coba kulihat tagihannya.",
  ui_story_5026_50261601_173_dialog_content = "<size=50>Sebentar. APA!? Harganya segini? Kau pasti bercanda!</size>"
}
return config
